def sha256_bytes(data: bytes) -> bytes:
    return hashlib.sha256(data).digest()

def sha256_hex(data: bytes) -> str:
    return hashlib.sha256(data).hexdigest()

def canonical_json(obj) -> bytes:
    return json.dumps(obj, sort_keys=True, separators=(",", ":")).encode()

def _quantize_tensor(t: torch.Tensor, decimals=QUANTIZE_DECIMALS):
    scale = 10 ** decimals
    return torch.round(t.detach().cpu().float() * scale) / scale

def _tensor_to_bytes(t: torch.Tensor, decimals=QUANTIZE_DECIMALS):
    return _quantize_tensor(t, decimals).contiguous().numpy().tobytes()

def _cos(a: torch.Tensor, b: torch.Tensor) -> float:
    a = a.detach().float().reshape(1, -1)
    b = b.detach().float().reshape(1, -1)
    return float(F.cosine_similarity(a, b, dim=1).item())

def _fisher_z(r):
    return np.arctanh(np.clip(r, -1 + 1e-7, 1 - 1e-7))

def _fisher_inv(z):
    return np.tanh(z)

def wilson_interval(k, n, z=1.959963984540054):
    if n <= 0:
        return (float("nan"), float("nan"))
    p = k / n
    den = 1 + z*z/n
    center = (p + z*z/(2*n)) / den
    half = z * math.sqrt((p*(1-p)/n) + z*z/(4*n*n)) / den
    return max(0.0, center-half), min(1.0, center+half)

