def _get_submodule(model, path):
    parts = path.split(".")
    parent = model
    for p in parts[:-1]:
        parent = getattr(parent, p) if not p.isdigit() else parent[int(p)]
    return parent, parts[-1]

def _tiny_to_device(x, device):
    return {k: v.to(device) for k, v in x.items()}


def init_dataset(n_pool=500):
    """Load the canonical GLUE SST-2 development split used by the reference."""
    global _TOKENIZER, _DATASET, SAMPLE_POOL, LABELS
    if SAMPLE_POOL is not None:
        return

    _TOKENIZER = AutoTokenizer.from_pretrained(HF_MODEL)

    import urllib.request
    import zipfile

    sst_dir = DATA_DIR / 'SST-2'
    dev_tsv = sst_dir / 'dev.tsv'
    if not dev_tsv.exists():
        zip_path = DATA_DIR / 'SST-2.zip'
        url = 'https://dl.fbaipublicfiles.com/glue/data/SST-2.zip'
        print(f'[dataset] Downloading canonical GLUE SST-2: {url}')
        urllib.request.urlretrieve(url, zip_path)
        with zipfile.ZipFile(zip_path, 'r') as zf:
            zf.extractall(DATA_DIR)

    rows = []
    with open(dev_tsv, 'r', encoding='utf-8') as f:
        header = f.readline().rstrip('\n').split('\t')
        si = header.index('sentence') if 'sentence' in header else 0
        li = header.index('label') if 'label' in header else 1
        for line in f:
            p = line.rstrip('\n').split('\t')
            if len(p) <= max(si, li):
                continue
            rows.append({'sentence': p[si], 'label': int(p[li])})

    _DATASET = rows
    SAMPLE_POOL, LABELS = [], []
    for row in rows[:min(int(n_pool), len(rows))]:
        enc = _TOKENIZER(
            row['sentence'],
            return_tensors='pt',
            truncation=True,
            padding='max_length',
            max_length=MAX_LEN,
        )
        SAMPLE_POOL.append({k: v[0].contiguous() for k, v in enc.items()})
        LABELS.append(int(row['label']))

    if len(SAMPLE_POOL) < ENROLL_INPUTS:
        raise RuntimeError(
            f'SST-2 produced only {len(SAMPLE_POOL)} usable samples; '
            f'at least {ENROLL_INPUTS} are required for enrollment.'
        )
    print(
        f"[adapter] TinyBERT/SST-2 samples={len(SAMPLE_POOL)} "
        f"layers={CANDIDATE_LAYERS} model={HF_MODEL}"
    )


def _new_model():
    # This model ID is already fine-tuned for SST-2 in the supplied reference.
    return AutoModelForSequenceClassification.from_pretrained(HF_MODEL).cpu().eval()


def _normalize_state_dict(raw):
    if isinstance(raw, dict) and 'state_dict' in raw:
        raw = raw['state_dict']
    return raw


def _tiny_validation_accuracy(model, limit=500):
    if SAMPLE_POOL is None:
        init_dataset()
    dev = next(model.parameters()).device
    good = 0
    n = min(int(limit), len(SAMPLE_POOL))
    model.eval()
    with torch.no_grad():
        for i in range(n):
            logits = model(**{k: v.to(dev).unsqueeze(0) for k, v in SAMPLE_POOL[i].items()}).logits
            good += int(int(logits.argmax(dim=-1).item()) == int(LABELS[i]))
    return good / max(1, n)


def ensure_clean_model():
    """Cache and reuse the exact fine-tuned TinyBERT state as trusted M*."""
    if SAMPLE_POOL is None:
        init_dataset()

    if CLEAN_PATH.exists():
        try:
            m = _new_model()
            m.load_state_dict(_normalize_state_dict(torch.load(CLEAN_PATH, map_location='cpu')), strict=True)
            acc = _tiny_validation_accuracy(m)
            print(f'[TinyBERT checkpoint] reusing trusted M*: {CLEAN_PATH}')
            print(f'[TinyBERT checkpoint] SST-2 dev accuracy={acc:.4f}')
            return
        except Exception as exc:
            print(f'[TinyBERT checkpoint] cached checkpoint incompatible: {exc}')
            CLEAN_PATH.unlink(missing_ok=True)

    m = _new_model()
    acc = _tiny_validation_accuracy(m)
    torch.save(m.state_dict(), CLEAN_PATH)
    print(f'[TinyBERT checkpoint] cached fine-tuned trusted M*: {CLEAN_PATH}')
    print(f'[TinyBERT checkpoint] SST-2 dev accuracy={acc:.4f}')


def load_model(path=CLEAN_PATH):
    m = _new_model()
    raw = _normalize_state_dict(torch.load(path, map_location='cpu'))
    m.load_state_dict(raw, strict=True)
    return m.eval()


def _model_forward(model, x):
    dev = next(model.parameters()).device
    with torch.no_grad():
        return model(**{k: v.to(dev).unsqueeze(0) for k, v in x.items()}).logits.reshape(-1)


def _shared_prefix_and_suffix(model, x, layer_name):
    """TinyBERT behavioral checkpoints from the supplied reference."""
    dev = next(model.parameters()).device
    kw = {k: v.to(dev).unsqueeze(0) for k, v in x.items()}
    y = model.bert(**kw, return_dict=True)
    hidden = y.last_hidden_state

    def classify_from_hidden(h):
        pooler = getattr(model.bert, 'pooler', None)
        if pooler is not None:
            feat = pooler(h)
        else:
            feat = h[:, 0, :]
        if hasattr(model, 'dropout'):
            feat = model.dropout(feat)
        return model.classifier(feat)

    if layer_name == 'bert':
        return hidden, classify_from_hidden

    if layer_name == 'classifier':
        feat = y.pooler_output if getattr(y, 'pooler_output', None) is not None else hidden[:, 0, :]
        def suffix(q):
            if hasattr(model, 'dropout'):
                q = model.dropout(q)
            return model.classifier(q)
        return feat, suffix

    raise ValueError(f'Unsupported TinyBERT perturbation point: {layer_name}')


class BehavioralExtractor:
    """TinyBERT behavioral extractor used by the full MIV framework."""
    def __init__(self, model):
        self.model = model
        self.model.eval()

    def _prefix(self, x, layer_name):
        return _shared_prefix_and_suffix(self.model, x, layer_name)

    def _forward(self, x):
        return _model_forward(self.model, x)

    def extract(self, x, layer_name, alpha, delta, capture_icrsf=True, nonce=b''):
        tracer = ICRSFTracer(self.model) if capture_icrsf else None
        try:
            if tracer:
                tracer.start()
            with torch.no_grad():
                z_clean = self._forward(x)
            if tracer:
                tracer.stop()

            with torch.no_grad():
                shared, suffix = self._prefix(x, layer_name)
                flat = shared.reshape(shared.shape[0], -1)
                d = min(flat.shape[1], int(delta.numel()))
                pert = flat.clone()
                pert[:, :d] += float(alpha) * delta[:d].to(
                    device=pert.device, dtype=pert.dtype
                )
                z_pert = suffix(pert.reshape_as(shared)).reshape(-1)
        finally:
            if tracer and tracer._handles:
                tracer.stop()

        if tracer:
            return z_clean, z_pert, tracer.events, tracer.digest(nonce)
        return z_clean, z_pert


def compute_alpha(model, layer_name, samples):
    vals = []
    with torch.no_grad():
        for x in samples[:min(8, len(samples))]:
            a, _ = _shared_prefix_and_suffix(model, x, layer_name)
            vals.append(a.detach().float().reshape(-1).cpu())
    if not vals:
        raise RuntimeError(f'No activation samples for TinyBERT layer {layer_name}')
    v = torch.cat(vals)
    return max(float(v.std().item()) / 10.0, 1e-4)


def layer_activation_size(model, layer_name, x):
    with torch.no_grad():
        a, _ = _shared_prefix_and_suffix(model, x, layer_name)
    return int(a.reshape(a.shape[0], -1).shape[1])


def _all_float_parameter_keys(state):
    return [
        k for k, v in state.items()
        if torch.is_tensor(v) and torch.is_floating_point(v) and v.numel() > 0
    ]


def _stable_mode_seed(mode):
    return SEED + int.from_bytes(hashlib.sha256(mode.encode()).digest()[:4], 'big') % 100000


def _adapter_state_mutation(out_path, mode):
    """Create attack checkpoints from the exact enrolled TinyBERT state."""
    state = copy.deepcopy(torch.load(CLEAN_PATH, map_location='cpu'))
    keys = _all_float_parameter_keys(state)
    g = torch.Generator().manual_seed(_stable_mode_seed(mode))

    if mode.startswith('corrupt:'):
        # Distributed parameter corruption. Earlier TinyBERT code accidentally
        # stopped after the first floating tensor, so "1/100" altered only
        # 1% of one tensor rather than approximately 1% across the parameter
        # registry. That made ECMC replacement detection artificially sparse.
        denom = int(mode.split(':')[1])
        changed_tensors = 0
        selected_values = 0
        eligible_values = 0
        for k in keys:
            flat = state[k].reshape(-1)
            if flat.numel() == 0:
                continue
            eligible_values += int(flat.numel())
            # Select approximately 1/denom independently within every floating
            # parameter tensor, matching ECMC's tensor-uniform selector.
            n = max(1, int(round(flat.numel() / denom)))
            n = min(n, flat.numel())
            idx = torch.randperm(flat.numel(), generator=g)[:n]
            sigma = max(float(flat.float().std().item()), 1e-6)
            flat[idx] += (0.25 * sigma) * torch.randn(n, generator=g)
            selected_values += int(n)
            changed_tensors += 1
        if changed_tensors == 0:
            raise RuntimeError(f'No eligible TinyBERT tensors for {mode}')
        print(
            f'[TinyBERT corruption] {mode}: distributed across '
            f'{changed_tensors} tensors, selected={selected_values}/{eligible_values} '
            f'({100.0*selected_values/max(eligible_values,1):.4f}%)'
        )

    elif mode == 'backdoor':
        # Parameter-level backdoor insertion surrogate retained consistently with
        # the paper's deployed-model modification evaluation.
        target = next((k for k in keys if 'classifier' in k and state[k].ndim == 1), keys[-1])
        state[target].reshape(-1)[0] += 0.35

    elif mode == 'poison':
        for k in keys:
            if state[k].ndim >= 2:
                state[k] += 0.01 * torch.randn(state[k].shape, generator=g)
                break

    elif mode == 'finetune':
        # Small unauthorized post-deployment parameter adaptation.
        for k in keys[-max(1, len(keys)//8):]:
            state[k] += 0.003 * torch.randn(state[k].shape, generator=g)

    elif mode == 'early':
        # Early-layer tamper must affect the first Transformer encoder block,
        # not a handful of embedding rows that may never be exercised by the
        # sampled SST-2 tokens. Modify 1% of an early encoder weight matrix.
        early_keys = [k for k in keys if ('encoder.layer.0' in k or 'encoder.layers.0' in k) and state[k].ndim >= 2]
        target = early_keys[0] if early_keys else next((k for k in keys if 'encoder' in k and state[k].ndim >= 2), keys[0])
        flat = state[target].reshape(-1)
        n = max(1, int(round(0.01 * flat.numel())))
        idx = torch.randperm(flat.numel(), generator=g)[:n]
        sigma = max(float(flat.float().std().item()), 1e-6)
        flat[idx] += (0.25 * sigma) * torch.randn(n, generator=g)

    elif mode == 'compression':
        # Symmetric per-tensor INT8 quantize-dequantize (QDQ). The modified
        # weights remain FP32 for the ordinary TinyBERT runtime. This models
        # quantization-induced compression, not native end-to-end INT8 inference.
        changed = total = 0
        sqerr = 0.0
        tensors = 0
        for k in keys:
            w = state[k]
            if w.ndim < 2:
                continue
            wf = w.float()
            max_abs = float(wf.abs().max().item())
            if max_abs <= 0.0:
                continue
            scale = max_abs / 127.0
            q = torch.clamp(torch.round(wf / scale), -127, 127)
            qdq = (q * scale).to(dtype=w.dtype)
            changed += int((qdq != w).sum().item())
            total += int(w.numel())
            sqerr += float(((qdq.float() - wf) ** 2).sum().item())
            tensors += 1
            state[k] = qdq
        mse = sqerr / max(total, 1)
        print(f'[TinyBERT compression] INT8 QDQ tensors={tensors}, changed={changed}/{total} ({100.0*changed/max(total,1):.2f}%), MSE={mse:.8e}')

    elif mode == 'internal':
        target = next((k for k in keys if 'encoder' in k and state[k].ndim >= 2), keys[0])
        flat = state[target].reshape(-1)
        flat[::997] += 0.005

    elif mode == 'drift':
        target = next((k for k in reversed(keys) if 'encoder' in k and state[k].ndim >= 2), keys[-1])
        state[target] += 0.002 * torch.randn(state[target].shape, generator=g)

    elif mode == 'bias':
        target = next((k for k in keys if k.endswith('classifier.bias')), None)
        if target is None:
            target = keys[-1]
        state[target].reshape(-1)[::2] += 0.08

    elif mode == 'scale':
        wk = next((k for k in keys if k.endswith('classifier.weight')), None)
        bk = next((k for k in keys if k.endswith('classifier.bias')), None)
        if wk is not None:
            state[wk] *= SCALE_FACTOR
        if bk is not None:
            state[bk] *= SCALE_FACTOR

    else:
        raise ValueError(mode)

    torch.save(state, out_path)


def ensure_attack_models():
    ensure_clean_model()
    specs = [
        (CORRUPT_100, 'corrupt:100'),
        (CORRUPT_1K, 'corrupt:1000'),
        (CORRUPT_10K, 'corrupt:10000'),
        (BACKDOOR_PATH, 'backdoor'),
        (POISON_PATH, 'poison'),
        (FINETUNE_PATH, 'finetune'),
        (EARLYMOD_PATH, 'early'),
        (OUTPUTPRES_PATH, 'internal'),
        (DRIFT_PATH, 'drift'),
        (BIAS_PATH, 'bias'),
        (SCALE_PATH, 'scale'),
        (COMPRESSION_PATH, 'compression'),
    ]
    clean_mtime = CLEAN_PATH.stat().st_mtime if CLEAN_PATH.exists() else 0.0
    for path, mode in specs:
        stale = path.exists() and path.stat().st_mtime < clean_mtime
        if stale:
            path.unlink()
        if not path.exists():
            _adapter_state_mutation(path, mode)


class _AdapterIdentityOp(nn.Module):
    def __init__(self):
        super().__init__()
        self.dummy = nn.Parameter(torch.zeros(1), requires_grad=False)
    def forward(self, x):
        return x + self.dummy.to(x.device, x.dtype) * 0.0


class _LinearEquivalentPair(nn.Module):
    def __init__(self, old):
        super().__init__()
        self.first = copy.deepcopy(old)
        self.identity = nn.Linear(old.out_features, old.out_features, bias=False)
        with torch.no_grad():
            self.identity.weight.copy_(
                torch.eye(old.out_features, dtype=self.identity.weight.dtype)
            )
    def forward(self, x):
        return self.identity(self.first(x))


def _adapter_safe_linear_path(model):
    # Prefer the classification head so the structural substitution remains
    # semantically simple and input/output compatible.
    cand = [n for n, m in model.named_modules() if n and isinstance(m, nn.Linear)]
    classifier = [n for n in cand if 'classifier' in n]
    if classifier:
        return classifier[-1]
    if not cand:
        raise RuntimeError('TinyBERT structural substitution requires a Linear layer')
    return cand[-1]


def apply_architecture_substitution(model, leaf_path=None, new_k=5):
    path = _adapter_safe_linear_path(model)
    parent, leaf = _get_submodule(model, path)
    old = getattr(parent, leaf)
    setattr(parent, leaf, _LinearEquivalentPair(old))
    return model.eval()


def make_function_preserving_structural_substitution(model, target_path=None):
    path = _adapter_safe_linear_path(model)
    parent, leaf = _get_submodule(model, path)
    old = getattr(parent, leaf)
    setattr(parent, leaf, nn.Sequential(old, _AdapterIdentityOp()))
    return model.eval()


def _v87_make_arch_model():
    return apply_architecture_substitution(load_model(CLEAN_PATH))


def _v87_make_fpss_model():
    return make_function_preserving_structural_substitution(load_model(CLEAN_PATH))


def _v87_arch_layer():
    return 'classifier'


# TinyBERT-aware parameter-registry inference for ECMC.
def _ecmc_tiny_forward(model, x):
    return _model_forward(model, x)



# 4. Architecture-general ICRSF implementation
# ---------------------------------------------------------------------
def _canonical_op_name(module):
    mapping = [
        (nn.Conv1d, "Conv1D"), (nn.Conv2d, "Conv2D"), (nn.Conv3d, "Conv3D"),
        (nn.Linear, "Linear"), (nn.Embedding, "Embedding"),
        (nn.BatchNorm1d, "BatchNorm1D"), (nn.BatchNorm2d, "BatchNorm2D"),
        (nn.BatchNorm3d, "BatchNorm3D"), (nn.LayerNorm, "LayerNorm"),
        (nn.ReLU, "ReLU"), (nn.GELU, "GELU"), (nn.Sigmoid, "Sigmoid"),
        (nn.Tanh, "Tanh"), (nn.MaxPool1d, "MaxPool1D"),
        (nn.MaxPool2d, "MaxPool2D"), (nn.MaxPool3d, "MaxPool3D"),
        (nn.AdaptiveAvgPool1d, "AdaptiveAvgPool1D"),
        (nn.AdaptiveAvgPool2d, "AdaptiveAvgPool2D"),
        (nn.AdaptiveAvgPool3d, "AdaptiveAvgPool3D"),
        (nn.RNN, "RNN"), (nn.GRU, "GRU"), (nn.LSTM, "LSTM"),
        (nn.MultiheadAttention, "MultiheadAttention"),
    ]
    for cls, name in mapping:
        if isinstance(module, cls):
            return name
    return module.__class__.__name__


def _tuple_int(v):
    if isinstance(v, tuple): return tuple(int(x) for x in v)
    if isinstance(v, list): return tuple(int(x) for x in v)
    return (int(v),)


def _canonical_attrs(module):
    if isinstance(module, (nn.Conv1d, nn.Conv2d, nn.Conv3d)):
        return {
            "in": int(module.in_channels), "out": int(module.out_channels),
            "kernel": _tuple_int(module.kernel_size), "stride": _tuple_int(module.stride),
            "padding": _tuple_int(module.padding), "dilation": _tuple_int(module.dilation),
            "groups": int(module.groups), "bias": bool(module.bias is not None),
        }
    if isinstance(module, nn.Linear):
        return {"in": int(module.in_features), "out": int(module.out_features), "bias": bool(module.bias is not None)}
    if isinstance(module, nn.Embedding):
        return {"num_embeddings": int(module.num_embeddings), "dim": int(module.embedding_dim)}
    if isinstance(module, (nn.BatchNorm1d, nn.BatchNorm2d, nn.BatchNorm3d)):
        return {"features": int(module.num_features), "affine": bool(module.affine)}
    if isinstance(module, nn.LayerNorm):
        return {"shape": tuple(int(x) for x in module.normalized_shape), "affine": bool(module.elementwise_affine)}
    if isinstance(module, (nn.RNN, nn.GRU, nn.LSTM)):
        return {
            "input_size": int(module.input_size), "hidden_size": int(module.hidden_size),
            "layers": int(module.num_layers), "bidirectional": bool(module.bidirectional),
            "batch_first": bool(module.batch_first),
        }
    if isinstance(module, nn.MultiheadAttention):
        return {"embed_dim": int(module.embed_dim), "heads": int(module.num_heads), "batch_first": bool(module.batch_first)}
    attrs = {}
    for name in ("kernel_size", "stride", "padding", "output_size"):
        if hasattr(module, name):
            try: attrs[name] = _tuple_int(getattr(module, name))
            except Exception: pass
    return attrs


def _tensor_items(obj):
    if isinstance(obj, torch.Tensor):
        return [obj]
    if isinstance(obj, (tuple, list)):
        out = []
        for x in obj: out.extend(_tensor_items(x))
        return out
    if isinstance(obj, dict):
        out = []
        for key in sorted(obj.keys(), key=str): out.extend(_tensor_items(obj[key]))
        return out
    return []


def _logical_shape(t):
    return tuple(int(v) for v in t.shape)


def _tensor_identity(t):
    try:
        return (int(t.data_ptr()), tuple(t.shape), str(t.dtype))
    except Exception:
        return (id(t), tuple(t.shape), str(t.dtype))


def participation_descriptor(output, regions=ICRSF_REGIONS, qmax=ICRSF_QMAX):
    tensors = [t.detach().float().reshape(-1) for t in _tensor_items(output) if t.numel() > 0]
    if not tensors:
        return [0] * regions
    v = torch.cat(tensors)
    n = int(v.numel())
    # tensor_split avoids requiring divisibility and works for n < regions.
    chunks = torch.tensor_split(v.abs(), regions)
    sums = torch.stack([c.sum() if c.numel() else torch.tensor(0.0, device=v.device) for c in chunks])
    total = sums.sum() + 1e-12
    rho = sums / total
    q = torch.clamp(torch.round(rho * qmax), 0, qmax).to(torch.int64).cpu().tolist()
    return [int(x) for x in q]


def _is_monitorable(module):
    # Leaf modules are generic and avoid double-counting compound blocks.
    if len(list(module.children())) > 0:
        return False
    return any(True for _ in module.parameters(recurse=False)) or isinstance(module, (
        nn.ReLU, nn.GELU, nn.Sigmoid, nn.Tanh,
        nn.MaxPool1d, nn.MaxPool2d, nn.MaxPool3d,
        nn.AdaptiveAvgPool1d, nn.AdaptiveAvgPool2d, nn.AdaptiveAvgPool3d,
    ))


class ICRSFTracer:
    def __init__(self, model, regions=ICRSF_REGIONS):
        self.model = model
        self.regions = regions
        self.events = []
        self._handles = []
        self._producer = {}
        self._active = False
        self.monitored = [(n, m) for n, m in model.named_modules() if n and _is_monitorable(m)]
        self.ordinal = {name: i for i, (name, _) in enumerate(self.monitored)}

    def _hook(self, name):
        ordinal = self.ordinal[name]
        def fn(module, inp, out):
            if not self._active: return
            ins = _tensor_items(inp)
            outs = _tensor_items(out)
            preds = sorted(set(
                self._producer.get(_tensor_identity(t))
                for t in ins if self._producer.get(_tensor_identity(t)) is not None
            ))
            event = {
                "id": int(ordinal),
                "op": _canonical_op_name(module),
                "attr": _canonical_attrs(module),
                "pred": preds,
                "sin": [_logical_shape(t) for t in ins],
                "sout": [_logical_shape(t) for t in outs],
                "part": participation_descriptor(out, self.regions),
            }
            self.events.append(event)
            for t in outs:
                self._producer[_tensor_identity(t)] = int(ordinal)
        return fn

    def start(self):
        self.events = []
        self._producer = {}
        self._active = True
        self._handles = [m.register_forward_hook(self._hook(n)) for n, m in self.monitored]

    def stop(self):
        self._active = False
        for h in self._handles: h.remove()
        self._handles = []

    def digest(self, nonce=b""):
        payload = ICRSF_VERSION.encode() + b"|" + MODEL_ID.encode() + b"|" + CANONICALIZATION_ID.encode() + b"|" + nonce + b"|" + canonical_json(self.events)
        return sha256_hex(payload)


def _graph_projection(events):
    return [{k: e[k] for k in ("id", "op", "attr", "pred", "sin", "sout")} for e in events]


def compare_icrsf(edge_events, ref_events, tau=ICRSF_DISTANCE_TAU):
    """Compare ICRSF evidence with strict numerical invariants.

    Because each participation entry is quantized into [0, ICRSF_QMAX],
    the normalized mean absolute distance MUST lie in [0, 1]. Any value
    outside that range indicates malformed evidence, stale notebook state,
    or an implementation error and is rejected instead of silently used.
    """
    graph_ok = _graph_projection(edge_events) == _graph_projection(ref_events)
    if not graph_ok or len(edge_events) != len(ref_events):
        return {"graph_ok": False, "distance": 1.0, "pass": False,
                "valid": True, "reason": "graph mismatch"}

    diffs = []
    for idx, (a, b) in enumerate(zip(edge_events, ref_events)):
        pa = np.asarray(a.get("part", []), dtype=np.float64)
        pb = np.asarray(b.get("part", []), dtype=np.float64)

        if pa.shape != pb.shape:
            return {"graph_ok": False, "distance": 1.0, "pass": False,
                    "valid": False, "reason": f"descriptor shape mismatch at event {idx}"}

        if (not np.all(np.isfinite(pa)) or not np.all(np.isfinite(pb)) or
                np.any(pa < 0) or np.any(pb < 0) or
                np.any(pa > ICRSF_QMAX) or np.any(pb > ICRSF_QMAX)):
            return {"graph_ok": True, "distance": 1.0, "pass": False,
                    "valid": False, "reason": f"descriptor out of [0,{ICRSF_QMAX}] at event {idx}"}

        if pa.size:
            diffs.append(float(np.mean(np.abs(pa - pb)) / max(ICRSF_QMAX, 1)))

    d = float(np.mean(diffs)) if diffs else 0.0
    valid = bool(np.isfinite(d) and 0.0 <= d <= 1.0 + 1e-12)
    if not valid:
        return {"graph_ok": True, "distance": 1.0, "pass": False,
                "valid": False, "reason": f"invalid normalized distance {d!r}"}

    d = min(max(d, 0.0), 1.0)
    return {"graph_ok": True, "distance": d, "pass": d <= tau,
            "valid": True, "reason": "ok"}


# ---------------------------------------------------------------------
# ---------------------------------------------------------------------
# 5. Behavioral verification utilities
# ---------------------------------------------------------------------
def random_session_seed():
    return os.urandom(16)


def derive_delta(seed: bytes, d):
    raw = bytearray()
    ctr = 0
    while len(raw) < 4*d:
        raw.extend(hashlib.sha256(seed + ctr.to_bytes(4, "big") + b"delta").digest())
        ctr += 1
    arr = np.frombuffer(bytes(raw[:4*d]), dtype=np.uint32).astype(np.float64) / (2**32)
    arr = np.clip(arr, 1e-12, 1-1e-12)
    arr = np.log(arr) - np.log1p(-arr)
    t = torch.tensor(arr, dtype=torch.float32)
    return t / (t.norm() + 1e-12)


# ---------------------------------------------------------------------
# 6. Enrollment and explicit verification
# ---------------------------------------------------------------------
@dataclass
class IntegrityProfile:
    tau_z: dict = field(default_factory=dict)
    tau_dz: dict = field(default_factory=dict)
    tau_mag: dict = field(default_factory=dict)
    tau_struct_by_layer: dict = field(default_factory=dict)
    tau_struct: float = ICRSF_DISTANCE_TAU
    node_id: str = ""


def calibrate_profile(ref_model, samples, edge_model=None, node_id="node"):
    """Trusted Phase-1 enrollment, preserving the previous settings.

    - 10 enrollment inputs per candidate layer.
    - K_SIGMA=3 in Fisher-z space.
    - sigma_z floor=1e-3; sigma_dz floor=3e-3.
    - 4-decimal floored behavioral thresholds.
    - magnitude band preserved at +/-10% (0.9..1.1).
    - ICRSF threshold calibrated per layer with ICRSF_DISTANCE_TAU as a
      conservative numerical floor.

    `edge_model` is the actual model instance assigned to the enrolled node.
    During trusted enrollment all nine nodes use CLEAN_PATH, exactly as in the
    previous code; scenario models are assigned only after profiles are frozen.
    """
    edge_model = edge_model or ref_model
    profile = IntegrityProfile(node_id=node_id)
    ref_ex = BehavioralExtractor(ref_model)
    edge_ex = BehavioralExtractor(edge_model)
    samples = list(samples)[:ENROLL_INPUTS]

    print(f"\n  [Enrollment] {node_id}: {len(samples)} inputs x {len(CANDIDATE_LAYERS)} layers | K_SIGMA={K_SIGMA}")
    for layer in CANDIDATE_LAYERS:
        d = layer_activation_size(ref_model, layer, samples[0])
        alpha = compute_alpha(ref_model, layer, samples)
        cz, cd, struct_dist = [], [], []

        for j, x in enumerate(samples):
            # Node-specific deterministic enrollment nonce for reproducibility.
            nonce = hashlib.sha256(f"enroll|{SEED}|{node_id}|{layer}|{j}".encode()).digest()[:16]
            delta = derive_delta(nonce, d)
            zr, zpr, re, _ = ref_ex.extract(x, layer, alpha, delta, capture_icrsf=True, nonce=nonce)
            ze, zpe, ee, _ = edge_ex.extract(x, layer, alpha, delta, capture_icrsf=True, nonce=nonce)
            dzr, dze = zpr-zr, zpe-ze
            cz.append(_cos(_quantize_tensor(zr), _quantize_tensor(ze)))
            cd.append(_cos(_quantize_tensor(dzr), _quantize_tensor(dze)))
            struct_dist.append(compare_icrsf(ee, re, tau=1.0)["distance"])

        def _behavior_tau(vals, sigma_floor, fallback):
            if len(vals) < 2:
                return fallback
            zvals = _fisher_z(np.asarray(vals, dtype=float))
            mu = float(zvals.mean())
            sd = max(float(zvals.std(ddof=1)), float(sigma_floor))
            raw = _fisher_inv(mu - K_SIGMA*sd)
            return float(np.floor(raw * (10**QUANTIZE_DECIMALS)) / (10**QUANTIZE_DECIMALS))

        profile.tau_z[layer] = _behavior_tau(cz, SIGMA_Z_FLOOR, 0.95)
        profile.tau_dz[layer] = _behavior_tau(cd, SIGMA_DZ_FLOOR, 0.90)
        profile.tau_mag[layer] = 0.10  # same 0.9..1.1 band as the previous code

        smu = float(np.mean(struct_dist)) if struct_dist else 0.0
        ssd = float(np.std(struct_dist, ddof=1)) if len(struct_dist) > 1 else 0.0
        profile.tau_struct_by_layer[layer] = max(ICRSF_DISTANCE_TAU, smu + K_SIGMA*ssd)

        print(f"    {layer:<10} tau_z={profile.tau_z[layer]:.4f} "
              f"tau_dz={profile.tau_dz[layer]:.4f} tau_S={profile.tau_struct_by_layer[layer]:.5f}")
    return profile


