# Previous node-enrollment configuration (preserved)
# ---------------------------------------------------------------------
NODE_POOL_SEED = 42
NODE_POOL_MODELS = [
    CLEAN_PATH, CORRUPT_10K, CORRUPT_1K, CORRUPT_100,
    BACKDOOR_PATH, POISON_PATH, FINETUNE_PATH,
    EARLYMOD_PATH, OUTPUTPRES_PATH,
]
_NODE_POOL = {}
_NODE_IDS = []
_INTEGRITY_PROFILES = {}


def enroll_all_nodes(ref_model):
    """Enroll 9 physical/logical edge nodes once with the trusted CLEAN model.

    The node IDs are shuffled with NODE_POOL_SEED=42 and then associated with
    the same nine scenario models as the previous implementation. All
    thresholds are frozen before any attack/tampered model is evaluated.
    """
    global _NODE_POOL, _NODE_IDS, _INTEGRITY_PROFILES
    rng = random.Random(NODE_POOL_SEED)
    node_ids = [f"node_{i}" for i in range(len(NODE_POOL_MODELS))]
    rng.shuffle(node_ids)
    trusted_edge = load_model(CLEAN_PATH)
    samples = SAMPLE_POOL[:ENROLL_INPUTS]

    print("\n" + "="*72)
    print(f"NODE POOL ENROLLMENT ({len(node_ids)} nodes, {ENROLL_INPUTS} inputs/layer, seed={NODE_POOL_SEED})")
    print("="*72)
    for nid, scenario_path in zip(node_ids, NODE_POOL_MODELS):
        print(f"  {nid:<10} enrolled=CLEAN_PATH  assigned_after_enrollment={Path(scenario_path).name}")
        _INTEGRITY_PROFILES[nid] = calibrate_profile(
            ref_model, samples, edge_model=trusted_edge, node_id=nid
        )

    _NODE_IDS = node_ids
    _NODE_POOL = dict(zip(node_ids, NODE_POOL_MODELS))
    print("\n  All 9 node profiles frozen. Live verification cannot update them.")
    return _INTEGRITY_PROFILES


def get_node_for_scenario(model_path):
    target = str(model_path)
    for nid, p in _NODE_POOL.items():
        if str(p) == target:
            return nid
    # Scenarios without a dedicated ninth-pool mapping (drift/bias/scale/arch)
    # reuse an enrolled node, exactly as the earlier evaluation reused nodes.
    return _NODE_IDS[0]


def profile_for_scenario(model_path):
    return _INTEGRITY_PROFILES[get_node_for_scenario(model_path)]


def icrsf_digest_from_events(events, nonce: bytes):
    payload = ICRSF_VERSION.encode() + b"|" + MODEL_ID.encode() + b"|" + CANONICALIZATION_ID.encode() + b"|" + nonce + b"|" + canonical_json(events)
    return sha256_hex(payload)


def explicit_proof(model, x, layer, alpha, delta, node_id, nonce, counter, k_t):
    extractor = BehavioralExtractor(model)
    z, zp, events, digest = extractor.extract(x, layer, alpha, delta, capture_icrsf=True, nonce=nonce)
    dz = zp-z
    payload = (
        node_id.encode() + b"|" + MODEL_ID.encode() + b"|" + nonce + counter.to_bytes(8, "big") +
        digest.encode() + _tensor_to_bytes(z) + _tensor_to_bytes(dz)
    )
    tag = hmac.new(k_t, payload, hashlib.sha256).hexdigest()
    return {"node_id": node_id, "counter": counter, "nonce": nonce.hex(), "icrsf": events,
            "icrsf_digest": digest, "z": z, "dz": dz, "mag": float(dz.norm().item()), "tag": tag}


def verify_explicit(ref_model, proof, x, layer, alpha, delta, expected_node_id, expected_nonce, counter, k_t, profile):
    if proof.get("node_id") != expected_node_id or proof.get("counter") != counter or proof.get("nonce") != expected_nonce.hex():
        return {"pass": False, "auth": False, "reason": "context mismatch"}
    recomputed_icrsf_digest = icrsf_digest_from_events(proof.get("icrsf", []), expected_nonce)
    if recomputed_icrsf_digest != proof.get("icrsf_digest"):
        return {"pass": False, "auth": False, "reason": "ICRSF digest/evidence mismatch"}
    payload = (
        expected_node_id.encode() + b"|" + MODEL_ID.encode() + b"|" + expected_nonce + counter.to_bytes(8, "big") +
        proof["icrsf_digest"].encode() + _tensor_to_bytes(proof["z"]) + _tensor_to_bytes(proof["dz"])
    )
    expected_tag = hmac.new(k_t, payload, hashlib.sha256).hexdigest()
    auth = hmac.compare_digest(expected_tag, proof.get("tag", ""))
    ref_ex = BehavioralExtractor(ref_model)
    zr, zpr, ref_events, _ = ref_ex.extract(x, layer, alpha, delta, capture_icrsf=True, nonce=expected_nonce)
    dzr = zpr-zr
    tau_s = profile.tau_struct_by_layer.get(layer, profile.tau_struct)
    structural = compare_icrsf(proof["icrsf"], ref_events, tau_s)
    cosz = _cos(_quantize_tensor(proof["z"]), _quantize_tensor(zr))
    cosdz = _cos(_quantize_tensor(proof["dz"]), _quantize_tensor(dzr))
    ratio = float(proof["dz"].norm()/(dzr.norm()+1e-12))
    ez = cosz >= profile.tau_z[layer]
    ed = cosdz >= profile.tau_dz[layer]
    em = abs(ratio-1.0) <= profile.tau_mag[layer]
    ok = auth and structural["pass"] and ez and ed and em
    return {"pass": ok, "auth": auth, "struct": structural["pass"], "graph_ok": structural["graph_ok"],
            "struct_distance": structural["distance"], "cosz": cosz, "cosdz": cosdz, "mag_ratio": ratio,
            "ez": ez, "ed": ed, "em": em, "reason": "PASS" if ok else "verification gate failed"}


# ---------------------------------------------------------------------
# 7. Architecture-independent ECMC parameter registry and chain
# ---------------------------------------------------------------------
@dataclass(frozen=True)
class ParamEntry:
    registry_id: int
    module_name: str
    param_name: str
    numel: int
    shape: tuple


def build_parameter_registry(model):
    entries = []
    idx = 0
    for module_name, module in model.named_modules():
        if not module_name: continue
        for param_name, p in module.named_parameters(recurse=False):
            if p is None or p.numel() == 0: continue
            entries.append(ParamEntry(idx, module_name, param_name, int(p.numel()), tuple(int(x) for x in p.shape)))
            idx += 1
    return entries


def canonical_arch_digest(model):
    rows = []
    for n, m in model.named_modules():
        if n and _is_monitorable(m):
            rows.append({"name": n, "op": _canonical_op_name(m), "attr": _canonical_attrs(m)})
    return sha256_hex(canonical_json(rows))


def canonical_param_digest(model):
    h = hashlib.sha256()
    for n, p in model.state_dict().items():
        h.update(n.encode()+b"|")
        if torch.is_tensor(p): h.update(p.detach().cpu().contiguous().numpy().tobytes())
    return h.hexdigest()


def model_identifier(model):
    da = canonical_arch_digest(model)
    dp = canonical_param_digest(model)
    return sha256_hex((da+"|"+dp).encode())


def _prf_int(seed: bytes, label: bytes, upper: int):
    if upper <= 0: return 0
    return int.from_bytes(hmac.new(seed, label, hashlib.sha256).digest(), "big") % upper


def derive_request_nonce(epoch_seed: bytes, epoch: int, counter: int):
    return sha256_bytes(epoch_seed + epoch.to_bytes(8, "big") + counter.to_bytes(8, "big") + b"ecmc-request")


def select_registry_entries(registry, nonce: bytes, m: int):
    if not registry: return []
    # Stratify over parameter tensors by deterministic permutation.
    scored = []
    for e in registry:
        score = hmac.new(nonce, f"entry:{e.registry_id}".encode(), hashlib.sha256).digest()
        scored.append((score, e))
    scored.sort(key=lambda x: x[0])
    return [e for _, e in scored[:min(m, len(scored))]]


def select_positions(entry: ParamEntry, nonce: bytes, k: int):
    if entry.numel <= 0: return []
    out, used = [], set()
    ctr = 0
    while len(out) < min(k, entry.numel):
        j = _prf_int(nonce, f"pos:{entry.registry_id}:{ctr}".encode(), entry.numel)
        ctr += 1
        if j not in used:
            used.add(j); out.append(j)
    return out


def _ecmc_value_bytes(values):
    arr = np.asarray(values, dtype=np.float32)
    arr = np.round(arr, QUANTIZE_DECIMALS)
    return arr.tobytes()


class ECMCEdgeState:
    def __init__(self, model, node_id, model_id, epoch=0, epoch_seed=None, initial_chain=None,
                 m=ECMC_M_OPERATORS, k=ECMC_K_VALUES, window=ECMC_WINDOW):
        self.model = model
        self.node_id = node_id
        self.model_id = model_id
        self.epoch = epoch
        self.epoch_seed = epoch_seed or os.urandom(32)
        self.counter = 0
        self.registry = build_parameter_registry(model)
        self.m, self.k, self.window = m, k, window
        self.chain = initial_chain or sha256_bytes(b"CHAIN-INIT|"+node_id.encode()+b"|"+model_id.encode())
        self.records = []

    def new_epoch(self, epoch, epoch_seed, anchor):
        self.epoch = int(epoch)
        self.epoch_seed = bytes(epoch_seed)
        self.counter = 0
        self.chain = bytes(anchor)
        self.records = []

    def infer(self, x):
        self.counter += 1
        i = self.counter
        nonce = derive_request_nonce(self.epoch_seed, self.epoch, i)
        selected = select_registry_entries(self.registry, nonce, self.m)
        selected_by_module = defaultdict(list)
        for e in selected: selected_by_module[e.module_name].append(e)
        contributions = {}
        handles = []
        modules = dict(self.model.named_modules())

        for module_name, entries in selected_by_module.items():
            if module_name not in modules: continue
            def make_hook(mname, ents):
                def hook(module, inp, out):
                    local = []
                    pmap = dict(module.named_parameters(recurse=False))
                    for e in sorted(ents, key=lambda q:q.registry_id):
                        p = pmap[e.param_name].detach().reshape(-1)
                        pos = select_positions(e, nonce, self.k)
                        vals = [float(p[j].item()) for j in pos]
                        local.append((e.registry_id, e.module_name, e.param_name, pos, vals))
                    contributions[mname] = local
                return hook
            handles.append(modules[module_name].register_forward_hook(make_hook(module_name, entries)))

        try:
            with torch.no_grad():
                y = _model_forward(self.model, x).squeeze(0)
        finally:
            for h in handles: h.remove()

        # Build the chain from evidence captured during executing callbacks.
        A = hashlib.sha256(self.chain + self.epoch.to_bytes(8,"big") + i.to_bytes(8,"big") + nonce).digest()
        observed = []
        for e in sorted(selected, key=lambda q:q.registry_id):
            matches = contributions.get(e.module_name, [])
            item = next((x for x in matches if x[0] == e.registry_id), None)
            if item is None:
                # For the current fixed TinyBERT serving path, selected parameterized
                # modules are expected to execute. A dynamic-model adapter may
                # explicitly encode an executed mask and apply a different audit rule.
                raise RuntimeError(f"Selected operator did not execute: {e.module_name}.{e.param_name}")
            _, mname, pname, pos, vals = item
            event = {
                "rid": e.registry_id, "module": mname, "param": pname,
                "pos": pos, "vals": [round(v, QUANTIZE_DECIMALS) for v in vals],
            }
            A = hashlib.sha256(A + canonical_json(event)).digest()
            observed.append({k:event[k] for k in ("rid","module","param","pos")})
        C = hashlib.sha256(A + b"|FORWARD-COMPLETE|").digest()
        self.chain = C
        rec = {"epoch": self.epoch, "counter": i, "nonce": nonce.hex(), "chain": C.hex(), "selected": observed}
        self.records.append(rec)
        if len(self.records) > self.window:
            self.records = self.records[-self.window:]
        return y, rec


class ECMCCloudVerifier:
    def __init__(self, ref_model, node_id, model_id, epoch=0, epoch_seed=None, initial_chain=None,
                 m=ECMC_M_OPERATORS, k=ECMC_K_VALUES):
        self.ref_model = ref_model
        self.node_id = node_id
        self.model_id = model_id
        self.epoch = epoch
        self.epoch_seed = epoch_seed or os.urandom(32)
        self.registry = build_parameter_registry(ref_model)
        self.m, self.k = m, k
        self.anchor = initial_chain or sha256_bytes(b"CHAIN-INIT|"+node_id.encode()+b"|"+model_id.encode())

    def new_epoch(self, epoch, epoch_seed, anchor):
        self.epoch = int(epoch); self.epoch_seed = bytes(epoch_seed); self.anchor = bytes(anchor)

    def expected_step(self, prev_chain, counter):
        nonce = derive_request_nonce(self.epoch_seed, self.epoch, counter)
        selected = select_registry_entries(self.registry, nonce, self.m)
        modules = dict(self.ref_model.named_modules())
        A = hashlib.sha256(prev_chain + self.epoch.to_bytes(8,"big") + counter.to_bytes(8,"big") + nonce).digest()
        for e in sorted(selected, key=lambda q:q.registry_id):
            module = modules[e.module_name]
            p = dict(module.named_parameters(recurse=False))[e.param_name].detach().reshape(-1)
            pos = select_positions(e, nonce, self.k)
            vals = [float(p[j].item()) for j in pos]
            event = {"rid": e.registry_id, "module": e.module_name, "param": e.param_name,
                     "pos": pos, "vals": [round(v, QUANTIZE_DECIMALS) for v in vals]}
            A = hashlib.sha256(A + canonical_json(event)).digest()
        return hashlib.sha256(A + b"|FORWARD-COMPLETE|").digest()

    def audit_head(self, counter: int, reported_chain_hex: str, start_chain=None):
        """Reconstruct the expected head from the epoch anchor through counter.

        This requires no user input. It is useful for lightweight periodic
        audits when the cloud only needs the current committed head.
        """
        chain = start_chain or self.anchor
        for ctr in range(1, int(counter)+1):
            chain = self.expected_step(chain, ctr)
        ok = hmac.compare_digest(chain.hex(), str(reported_chain_hex))
        return {"result":"PASS" if ok else "FAIL",
                "reason":"continuity head verified" if ok else f"chain mismatch at/through counter {counter}",
                "expected_chain":chain.hex()}

    def audit(self, records, start_chain=None, start_counter=0):
        if not records:
            return {"result":"FAIL", "reason":"no records"}
        chain = start_chain or self.anchor
        expected_ctr = start_counter + 1
        seen = set()
        for r in records:
            if int(r["epoch"]) != self.epoch:
                return {"result":"FAIL", "reason":"cross-epoch record"}
            ctr = int(r["counter"])
            if ctr in seen:
                return {"result":"FAIL", "reason":"duplicate/replayed counter"}
            if ctr != expected_ctr:
                return {"result":"FAIL", "reason":f"counter gap/reorder expected {expected_ctr}, got {ctr}"}
            seen.add(ctr)
            expected_nonce = derive_request_nonce(self.epoch_seed, self.epoch, ctr).hex()
            if r.get("nonce") != expected_nonce:
                return {"result":"FAIL", "reason":"nonce mismatch"}
            chain = self.expected_step(chain, ctr)
            if r.get("chain") != chain.hex():
                return {"result":"FAIL", "reason":f"chain mismatch at counter {ctr}"}
            expected_ctr += 1
        return {"result":"PASS", "reason":"continuity verified", "final_chain":chain.hex()}


# ---------------------------------------------------------------------
# 8. Verified-anchor helper
# ---------------------------------------------------------------------
def make_verified_anchor(previous_chain: bytes, node_id: str, model_id: str, nonce: bytes, verify_result: dict):
    payload = canonical_json({
        "node": node_id, "model": model_id, "nonce": nonce.hex(),
        "struct_distance": round(float(verify_result.get("struct_distance", 1.0)), 8),
        "cosz": round(float(verify_result.get("cosz", 0.0)), 8),
        "cosdz": round(float(verify_result.get("cosdz", 0.0)), 8),
        "mag_ratio": round(float(verify_result.get("mag_ratio", 0.0)), 8),
    })
    return hashlib.sha256(b"VERIFIED-ANCHOR|"+previous_chain+payload).digest()


# ---------------------------------------------------------------------
# 9. Explicit attack scenarios
# ---------------------------------------------------------------------
def run_explicit_trial(ref_model, edge_model, profile, x, layer, node_id="nodeA", counter=1,
                       k_t=None, nonce=None):
    k_t = k_t or b"T"*32
    nonce = nonce or os.urandom(16)
    d = layer_activation_size(ref_model, layer, x)
    delta = derive_delta(nonce, d)
    alpha = compute_alpha(ref_model, layer, SAMPLE_POOL[:16])
    proof = explicit_proof(edge_model, x, layer, alpha, delta, node_id, nonce, counter, k_t)
    return verify_explicit(ref_model, proof, x, layer, alpha, delta, node_id, nonce, counter, k_t, profile), proof


