def result1_empirical_detection(ref_model, _unused_profile=None):
    print("\nRESULT 1 - Empirical explicit-verification detection")
    scenarios = [
        ("Clean", CLEAN_PATH, {}),
        ("Corrupt 1/10000", CORRUPT_10K, {}),
        ("Corrupt 1/1000", CORRUPT_1K, {}),
        ("Corrupt 1/100", CORRUPT_100, {}),
        ("Backdoor", BACKDOOR_PATH, {}),
        ("Poisoning", POISON_PATH, {}),
        ("Unauthorized fine-tuning", FINETUNE_PATH, {}),
        ("Early-layer tamper", EARLYMOD_PATH, {}),
        ("Output-preserving tamper", OUTPUTPRES_PATH, {}),
        ("Behavioral drift", DRIFT_PATH, {}),
        ("Architecture substitution", CLEAN_PATH, {"arch": True}),
        ("Output bias", BIAS_PATH, {}),
        ("Logit scaling", SCALE_PATH, {}),
    ]
    rows=[]
    for label,path,extra in scenarios:
        model = load_model(path)
        if extra.get("arch"):
            model = apply_architecture_substitution(model)
        profile = profile_for_scenario(path)
        nid = get_node_for_scenario(path)
        fails=struct_fail=beh_fail=0
        for r in range(CORE_ROUNDS):
            x=SAMPLE_POOL[r % len(SAMPLE_POOL)]
            layer=CANDIDATE_LAYERS[r % len(CANDIDATE_LAYERS)]
            vr,_=run_explicit_trial(ref_model,model,profile,x,layer,node_id=nid,counter=r+1)
            detected=not vr["pass"]
            fails += int(detected)
            struct_fail += int(not vr.get("struct",False))
            beh_fail += int(not (vr.get("ez",False) and vr.get("ed",False) and vr.get("em",False)))
        rate=fails/CORE_ROUNDS; lo,hi=wilson_interval(fails,CORE_ROUNDS)
        rows.append({"Scenario":label,"Node":nid,"Trials":CORE_ROUNDS,"DetectionRate":rate,
                     "CI_low":lo,"CI_high":hi,"StructuralFailures":struct_fail,"BehavioralFailures":beh_fail})
        print(f"  {label:28s} node={nid} detected {fails}/{CORE_ROUNDS} = {rate:.3f}")
    df=pd.DataFrame(rows); save_table(df,"result1_explicit_detection.csv"); return df


def _hypergeom_hit_prob(P, t, k):
    if P <= 0 or t <= 0 or k <= 0:
        return 0.0
    k=min(k,P); t=min(t,P)
    if P-t < k:
        return 1.0
    miss=1.0
    for j in range(k):
        miss *= (P-t-j)/(P-j)
    return 1.0-miss


def result2_icrsf_structure(ref_model):
    print("\nRESULT 2A - ICRSF structural analysis")
    rows=[]
    for label, path in [("Clean", CLEAN_PATH), ("Corrupt 1/1000", CORRUPT_1K), ("Early-layer tamper", EARLYMOD_PATH),
                        ("Output-preserving", OUTPUTPRES_PATH), ("Fine-tuned", FINETUNE_PATH)]:
        m=load_model(path)
        for r in range(CORE_ROUNDS):
            x=SAMPLE_POOL[r % len(SAMPLE_POOL)]
            layer=CANDIDATE_LAYERS[r % len(CANDIDATE_LAYERS)]
            nonce=hashlib.sha256(f"r2a|{label}|{r}".encode()).digest()[:16]
            d=layer_activation_size(ref_model,layer,x); delta=derive_delta(nonce,d)
            alpha=compute_alpha(ref_model,layer,SAMPLE_POOL[:16])
            exr=BehavioralExtractor(ref_model); exe=BehavioralExtractor(m)
            _,_,re,_=exr.extract(x,layer,alpha,delta,True,nonce)
            _,_,ee,_=exe.extract(x,layer,alpha,delta,True,nonce)
            tau_s=profile_for_scenario(path).tau_struct_by_layer.get(layer, ICRSF_DISTANCE_TAU)
            cmp=compare_icrsf(ee,re,tau=tau_s)
            rows.append({"Scenario":label,"Trial":r,"Layer":layer,"GraphOK":cmp["graph_ok"],
                         "Distance":cmp["distance"],"TauS":tau_s,"Pass":cmp["pass"]})

    arch=apply_architecture_substitution(load_model(CLEAN_PATH))
    arch_prof=profile_for_scenario(CLEAN_PATH)
    for r in range(CORE_ROUNDS):
        x=SAMPLE_POOL[r % len(SAMPLE_POOL)]; layer=CANDIDATE_LAYERS[0]
        nonce=hashlib.sha256(f"r2a|arch|{r}".encode()).digest()[:16]
        d=layer_activation_size(ref_model,layer,x); delta=derive_delta(nonce,d)
        alpha=compute_alpha(ref_model,layer,SAMPLE_POOL[:16])
        _,_,re,_=BehavioralExtractor(ref_model).extract(x,layer,alpha,delta,True,nonce)
        _,_,ee,_=BehavioralExtractor(arch).extract(x,layer,alpha,delta,True,nonce)
        tau_s=arch_prof.tau_struct_by_layer.get(layer, ICRSF_DISTANCE_TAU)
        cmp=compare_icrsf(ee,re,tau=tau_s)
        rows.append({"Scenario":"Architecture substitution","Trial":r,"Layer":layer,"GraphOK":cmp["graph_ok"],
                     "Distance":cmp["distance"],"TauS":tau_s,"Pass":cmp["pass"]})
    icrsf_df=pd.DataFrame(rows); save_table(icrsf_df,"result2a_icrsf.csv")

    print("\nRESULT 2B - ECMC sparse sampling: theory vs empirical")
    registry=build_parameter_registry(ref_model)
    # Representative large tensor so low tamper ratios are meaningful.
    target=max(registry,key=lambda e:e.numel)
    q=len(registry); P=target.numel
    sim_rows=[]
    for ratio in (1e-4,1e-3,1e-2):
        t=max(1,int(round(P*ratio)))
        changed=set(range(t))  # location identity is irrelevant under uniform sampling
        for k in (8,16,32):
            # Preserve 100 cheap trials/cell from the previous result settings.
            hits=0
            for trial in range(STRUCT_SIM_TRIALS):
                nonce=hashlib.sha256(f"r2b|{ratio}|{k}|{trial}|{SEED}".encode()).digest()
                selected=select_registry_entries(registry,nonce,ECMC_M_OPERATORS)
                chosen=next((e for e in selected if e.registry_id==target.registry_id),None)
                if chosen is not None:
                    pos=select_positions(chosen,nonce,k)
                    hits += int(any(j in changed for j in pos))
            p_tensor=min(ECMC_M_OPERATORS,q)/q
            p_within=_hypergeom_hit_prob(P,t,k)
            theory=p_tensor*p_within
            rate=hits/STRUCT_SIM_TRIALS; lo,hi=wilson_interval(hits,STRUCT_SIM_TRIALS)
            sim_rows.append({"TargetTensor":f"{target.module_name}.{target.param_name}","P":P,
                             "TamperRatio":ratio,"Changed":t,"k":k,"m":ECMC_M_OPERATORS,
                             "RegistryTensors":q,"TheoreticalSingleRequestDetection":theory,
                             "EmpiricalDetection":rate,"CI_low":lo,"CI_high":hi,"Trials":STRUCT_SIM_TRIALS})
    sim_df=pd.DataFrame(sim_rows); save_table(sim_df,"result2b_ecmc_sampling_theory_vs_empirical.csv")
    print(sim_df.to_string(index=False))
    return {"ICRSF":icrsf_df,"ECMC_sampling":sim_df}


def result3_complementarity(ref_model, profile):
    print("\nRESULT 3 - Structural / behavioral complementarity")
    scenarios=[("Architecture substitution",None),("Backdoor",BACKDOOR_PATH),("Behavioral drift",DRIFT_PATH),
               ("Corrupt 1/1000",CORRUPT_1K),("Output-preserving",OUTPUTPRES_PATH),("Output bias",BIAS_PATH),
               ("Logit scaling",SCALE_PATH),("Unauthorized fine-tuning",FINETUNE_PATH)]
    rows=[]
    for label,path in scenarios:
        sdet=bdet=cdet=0
        scenario_path = CLEAN_PATH if path is None else path
        scenario_profile = profile_for_scenario(scenario_path)
        scenario_node = get_node_for_scenario(scenario_path)
        model = apply_architecture_substitution(load_model(CLEAN_PATH)) if path is None else load_model(path)
        for r in range(CORE_ROUNDS):
            x=SAMPLE_POOL[r%len(SAMPLE_POOL)]
            layer=_v87_arch_layer() if label=="Architecture substitution" else CANDIDATE_LAYERS[r%len(CANDIDATE_LAYERS)]
            vr,_=run_explicit_trial(ref_model,model,scenario_profile,x,layer,node_id=scenario_node,counter=r+1)
            sd=not vr["struct"]
            bd=not (vr["ez"] and vr["ed"] and vr["em"])
            sdet+=sd; bdet+=bd; cdet+=(sd or bd)
        rows.append({"Scenario":label,"StructuralDetection":sdet/CORE_ROUNDS,"BehavioralDetection":bdet/CORE_ROUNDS,
                     "CombinedDetection":cdet/CORE_ROUNDS})
        print(f"  {label:26s} S={sdet/CORE_ROUNDS:.2f} B={bdet/CORE_ROUNDS:.2f} C={cdet/CORE_ROUNDS:.2f}")
    df=pd.DataFrame(rows); save_table(df,"result3_complementarity.csv"); return df


