def result5_protocol_attacks(ref_model, _unused_profile=None):
    print("\nRESULT 5 - Replay / theft / fabrication / rogue key")
    rows=[]
    keyA=b"A"*32; keyB=b"B"*32
    profileA=profile_for_scenario(CLEAN_PATH)
    nodeA=get_node_for_scenario(CLEAN_PATH)
    nodeB=next((n for n in _NODE_IDS if n != nodeA), _NODE_IDS[0])
    profileB=_INTEGRITY_PROFILES[nodeB]

    for attack in ["Replay","Proof theft","Naive fabrication","Rogue key"]:
        hits=0
        for r in range(PROTOCOL_ROUNDS):
            x=SAMPLE_POOL[r % len(SAMPLE_POOL)]
            layer=CANDIDATE_LAYERS[r % len(CANDIDATE_LAYERS)]
            nonce1=hashlib.sha256(f"proto1-{attack}-{r}".encode()).digest()[:16]
            nonce2=hashlib.sha256(f"proto2-{attack}-{r}".encode()).digest()[:16]
            d=layer_activation_size(ref_model,layer,x); alpha=compute_alpha(ref_model,layer,SAMPLE_POOL[:16])
            delta1=derive_delta(nonce1,d)
            good=explicit_proof(ref_model,x,layer,alpha,delta1,nodeA,nonce1,r+1,keyA)
            if attack=="Replay":
                res=verify_explicit(ref_model,good,x,layer,alpha,derive_delta(nonce2,d),nodeA,nonce2,r+2,keyA,profileA)
            elif attack=="Proof theft":
                res=verify_explicit(ref_model,good,x,layer,alpha,delta1,nodeB,nonce1,r+1,keyB,profileB)
            elif attack=="Naive fabrication":
                forged=copy.deepcopy(good); forged["z"]=torch.randn_like(good["z"]); forged["dz"]=torch.randn_like(good["dz"])
                res=verify_explicit(ref_model,forged,x,layer,alpha,delta1,nodeA,nonce1,r+1,keyA,profileA)
            else:
                rogue=explicit_proof(ref_model,x,layer,alpha,delta1,nodeA,nonce1,r+1,os.urandom(32))
                res=verify_explicit(ref_model,rogue,x,layer,alpha,delta1,nodeA,nonce1,r+1,keyA,profileA)
            hits += int(not res["pass"])
        rate=hits/PROTOCOL_ROUNDS; lo,hi=wilson_interval(hits,PROTOCOL_ROUNDS)
        rows.append({"Attack":attack,"Detected":hits,"Trials":PROTOCOL_ROUNDS,"DetectionRate":rate,"CI_low":lo,"CI_high":hi})
        print(f"  {attack:20s}: {hits}/{PROTOCOL_ROUNDS} detected")
    df=pd.DataFrame(rows); save_table(df,"result5_protocol_attacks.csv"); return df


def _make_ecmc_pair(ref_model, edge_model, tag="ecmc"):
    mid=model_identifier(ref_model); seed=os.urandom(32); init=sha256_bytes(b"ANCHOR|"+tag.encode())
    cloud=ECMCCloudVerifier(ref_model,tag,mid,epoch=1,epoch_seed=seed,initial_chain=init)
    edge=ECMCEdgeState(edge_model,tag,mid,epoch=1,epoch_seed=seed,initial_chain=init)
    return cloud,edge,init


def result6_replacement_ecmc(ref_model):
    print("\nRESULT 6 - Replacement / challenge-aware switching with ECMC")
    tampered=load_model(CORRUPT_100)
    checkpoints=[1,5,10,20,25]
    first=[]
    for tr in range(REPLACEMENT_TRIALS):
        cloud,edge,init=_make_ecmc_pair(ref_model,tampered,f"rep{tr}")
        det=None
        for s in range(1,REPLACEMENT_MAX_SLOTS+1):
            edge.infer(SAMPLE_POOL[(s+tr)%len(SAMPLE_POOL)])
            if random.random() <= ECMC_AUDIT_PROB:
                audit=cloud.audit_head(edge.counter,edge.chain.hex(),start_chain=init)
                if audit["result"]=="FAIL":
                    det=s; break
        first.append(det)

    curve=[]
    for k in checkpoints:
        hits=sum(1 for d in first if d is not None and d<=k)
        lo,hi=wilson_interval(hits,REPLACEMENT_TRIALS)
        curve.append({"Slots":k,"Detected":hits,"Trials":REPLACEMENT_TRIALS,
                      "DetectionRate":hits/REPLACEMENT_TRIALS,"CI_low":lo,"CI_high":hi})
    curve_df=pd.DataFrame(curve)
    detected=[d for d in first if d is not None]
    summary=pd.DataFrame([{"Trials":REPLACEMENT_TRIALS,"Detected":len(detected),
                           "DetectionRate":len(detected)/REPLACEMENT_TRIALS,
                           "MeanDetectionSlot":float(np.mean(detected)) if detected else np.nan,
                           "MedianDetectionSlot":float(np.median(detected)) if detected else np.nan,
                           "MaxSlots":REPLACEMENT_MAX_SLOTS,"AuditProbability":ECMC_AUDIT_PROB,
                           "m":ECMC_M_OPERATORS,"k":ECMC_K_VALUES,"Window":ECMC_WINDOW}])
    save_table(summary,"result6_replacement_ecmc.csv"); save_table(curve_df,"result6_replacement_curve.csv")

    # Chain-integrity attacks use a six-record trace, which fits W=8.
    cloud,edge,init=_make_ecmc_pair(ref_model,load_model(CLEAN_PATH),"chainattacks")
    for i in range(6): edge.infer(SAMPLE_POOL[i])
    clean=copy.deepcopy(edge.records)
    attacks=[]
    dup=copy.deepcopy(clean); dup.insert(3,copy.deepcopy(dup[2])); attacks.append(("Duplicate record",dup))
    reorder=copy.deepcopy(clean); reorder[2],reorder[3]=reorder[3],reorder[2]; attacks.append(("Reorder",reorder))
    delete=copy.deepcopy(clean); del delete[2]; attacks.append(("Deletion",delete))
    rollback=copy.deepcopy(clean); rollback[-1]=copy.deepcopy(clean[-2]); attacks.append(("Rollback",rollback))
    cross=copy.deepcopy(clean); cross[2]["epoch"]=0; attacks.append(("Cross-epoch replay",cross))
    attack_rows=[]
    for name,recs in attacks:
        a=cloud.audit(recs,start_chain=init,start_counter=0)
        attack_rows.append({"Attack":name,"Detected":a["result"]=="FAIL","Reason":a["reason"]})
    chain_df=pd.DataFrame(attack_rows); save_table(chain_df,"result6_chain_attacks.csv")
    return summary,curve_df,chain_df


def result7_ablation(ref_model, _unused_profile=None):
    print("\nRESULT 7 - Targeted ablation")
    tests=[
        ("ICRSF","Architecture substitution",CLEAN_PATH,_v87_arch_layer(),True),
        ("Clean output cosine","Output bias",BIAS_PATH,_v87_arch_layer(),False),
        ("Perturbation response","Output-preserving",OUTPUTPRES_PATH,CANDIDATE_LAYERS[0],False),
        ("Magnitude","Logit scaling",SCALE_PATH,_v87_arch_layer(),False),
    ]
    rows=[]
    for component,attack,path,layer,is_arch in tests:
        model=load_model(path)
        if is_arch: model=apply_architecture_substitution(model)
        profile=profile_for_scenario(path); nid=get_node_for_scenario(path)
        full=without=0
        for r in range(CORE_ROUNDS):
            vr,_=run_explicit_trial(ref_model,model,profile,SAMPLE_POOL[r],layer,node_id=nid,counter=r+1)
            full += int(not vr["pass"])
            gates={"auth":vr["auth"],"struct":vr["struct"],"ez":vr["ez"],"ed":vr["ed"],"em":vr["em"]}
            if component=="ICRSF": gates["struct"]=True
            elif component=="Clean output cosine": gates["ez"]=True
            elif component=="Perturbation response": gates["ed"]=True
            elif component=="Magnitude": gates["em"]=True
            without += int(not all(gates.values()))
        rows.append({"Component":component,"Attack":attack,"FullDetection":full/CORE_ROUNDS,
                     "DetectionWithout":without/CORE_ROUNDS,"Drop":full/CORE_ROUNDS-without/CORE_ROUNDS})
    rep,_,_=result6_replacement_ecmc(ref_model)
    rr=float(rep.iloc[0]["DetectionRate"])
    rows.append({"Component":"ECMC","Attack":"Replacement/challenge switching","FullDetection":rr,"DetectionWithout":0.0,"Drop":rr})
    df=pd.DataFrame(rows); save_table(df,"result7_ablation.csv"); return df


def _stats(ms):
    a=np.asarray(ms,dtype=float)
    return {"mean_ms":float(a.mean()),"median_ms":float(np.median(a)),"p95_ms":float(np.percentile(a,95)),"sd_ms":float(a.std())}


def result8_performance(ref_model, profile):
    """Measure edge/cloud performance with a paired, order-balanced benchmark.

    Baseline inference and ECMC-protected inference use the same clean model
    object, the same inputs, and alternating measurement order. This reduces
    warm-cache, CPU-frequency, and scheduler bias in Colab/CPU timing.
    """
    print("\nRESULT 8 - Edge/cloud/periodic performance")

    # EQ4 must use a real independently enrolled node.  Experiment labels such
    # as "perf" are never valid node identities.
    perf_node = sorted(_INTEGRITY_PROFILES.keys())[0]
    perf_profile = profile_for_node(perf_node)
    if profile is not perf_profile:
        # The caller may pass the same logical profile through another reference;
        # node identity remains authoritative for all enrollment-dependent values.
        profile = perf_profile

    ref_model = ref_model.to(torch.device("cpu")).eval()
    xs = [SAMPLE_POOL[i % len(SAMPLE_POOL)] for i in range(TIMING_WARMUP + TIMING_ITERS)]

    # Same model object for both normal and ECMC-protected inference.
    mid = model_identifier(ref_model)
    perf_seed = hashlib.sha256(b"result8-paired-ecmc-seed").digest()
    perf_previous = sha256_bytes(b"PREVIOUS-TRUSTED-CHAIN|result8-paired")
    perf_anchor, _, _ = establish_verified_anchor(
        ref_model, perf_node, perf_previous, challenge_tag="result8-perf-anchor"
    )
    edge = ECMCEdgeState(
        ref_model, perf_node, mid, epoch=1,
        epoch_seed=perf_seed, initial_chain=perf_anchor,
        m=ECMC_M_OPERATORS, k=ECMC_K_VALUES, window=ECMC_WINDOW,
    )

    def _time_normal(x):
        t0 = time.perf_counter()
        with torch.no_grad():
            _model_forward(ref_model, x)
        return (time.perf_counter() - t0) * 1000.0

    def _time_ecmc(x):
        t0 = time.perf_counter()
        edge.infer(x)
        return (time.perf_counter() - t0) * 1000.0

    # Warm both paths with alternating order; discard warm-up values.
    for q, x in enumerate(xs[:TIMING_WARMUP]):
        if q % 2 == 0:
            _time_normal(x); _time_ecmc(x)
        else:
            _time_ecmc(x); _time_normal(x)

    base, chain, paired_delta = [], [], []
    for q, x in enumerate(xs[TIMING_WARMUP:]):
        if q % 2 == 0:
            tb = _time_normal(x)
            tc = _time_ecmc(x)
        else:
            tc = _time_ecmc(x)
            tb = _time_normal(x)
        base.append(tb)
        chain.append(tc)
        paired_delta.append(tc - tb)

    # Explicit verification: measure complete edge proof and cloud verification directly.
    edge_ev, cloud_ev = [], []
    k_t = b"P" * 32
    for q, x in enumerate(xs[TIMING_WARMUP:]):
        layer = CANDIDATE_LAYERS[q % len(CANDIDATE_LAYERS)]
        nonce = hashlib.sha256(f"perf-ev-{q}".encode()).digest()[:16]
        d = layer_activation_size(ref_model, layer, x)
        delta = derive_delta(nonce, d)
        # Use the frozen alpha for this exact enrolled Node x Layer profile.
        alpha = _node_layer_alpha(perf_node, layer)

        t0 = time.perf_counter()
        proof = explicit_proof(ref_model, x, layer, alpha, delta, perf_node, nonce, q + 1, k_t)
        edge_ev.append((time.perf_counter() - t0) * 1000.0)

        t0 = time.perf_counter()
        verify_explicit(ref_model, proof, x, layer, alpha, delta, perf_node, nonce, q + 1, k_t, perf_profile)
        cloud_ev.append((time.perf_counter() - t0) * 1000.0)

    sb, sc, se, scl = _stats(base), _stats(chain), _stats(edge_ev), _stats(cloud_ev)
    sd = _stats(paired_delta)
    throughput_base = 1000.0 / sb["mean_ms"]
    throughput_chain = 1000.0 / sc["mean_ms"]
    latency_overhead_pct = (sc["mean_ms"] - sb["mean_ms"]) / sb["mean_ms"] * 100.0
    throughput_reduction_pct = (throughput_base - throughput_chain) / throughput_base * 100.0

    rows = [
        {"Condition":"Normal inference", **sb, "throughput_ops_s":throughput_base,
         "ecmc_latency_overhead_pct":np.nan, "ecmc_throughput_reduction_pct":np.nan,
         "paired_delta_mean_ms":np.nan, "paired_delta_median_ms":np.nan},
        {"Condition":"Normal inference + ECMC", **sc, "throughput_ops_s":throughput_chain,
         "ecmc_latency_overhead_pct":latency_overhead_pct,
         "ecmc_throughput_reduction_pct":throughput_reduction_pct,
         "paired_delta_mean_ms":sd["mean_ms"], "paired_delta_median_ms":sd["median_ms"]},
        {"Condition":"Edge explicit proof (ICRSF + behavioral, shared execution)", **se,
         "throughput_ops_s":1000.0/se["mean_ms"], "ecmc_latency_overhead_pct":np.nan,
         "ecmc_throughput_reduction_pct":np.nan, "paired_delta_mean_ms":np.nan,
         "paired_delta_median_ms":np.nan},
        {"Condition":"Cloud explicit verification/reference computation", **scl,
         "throughput_ops_s":1000.0/scl["mean_ms"], "ecmc_latency_overhead_pct":np.nan,
         "ecmc_throughput_reduction_pct":np.nan, "paired_delta_mean_ms":np.nan,
         "paired_delta_median_ms":np.nan},
    ]
    df = pd.DataFrame(rows)
    save_table(df, "result8_performance.csv")

    paired_df = pd.DataFrame({
        "Trial": np.arange(1, TIMING_ITERS + 1),
        "Order": ["Normal_then_ECMC" if q % 2 == 0 else "ECMC_then_Normal" for q in range(TIMING_ITERS)],
        "Normal_ms": base,
        "Normal_plus_ECMC_ms": chain,
        "Paired_delta_ms": paired_delta,
    })
    save_table(paired_df, "result8a_paired_timing_samples.csv")

    periodic = []
    for R in [10,50,100,500,1000]:
        avg = (R * sc["mean_ms"] + se["mean_ms"]) / (R + 1)
        periodic.append({
            "R_normal_per_EV":R,
            "AmortizedEdgeMean_ms":avg,
            "Throughput_ops_s":1000.0/avg,
            "Overhead_vs_unprotected_normal_pct":(avg - sb["mean_ms"]) / sb["mean_ms"] * 100.0,
        })
    pdf = pd.DataFrame(periodic)
    save_table(pdf, "result8_periodic.csv")

    resources = pd.DataFrame([
        {"Item":"ECMC chain head","Bytes":32},
        {"Item":"ECMC nonce","Bytes":32},
        {"Item":"Approx per-record metadata","Bytes":32+32+16},
        {"Item":"Bounded window (approx)","Bytes":ECMC_WINDOW*(32+32+16)},
        {"Item":"ICRSF digest","Bytes":32},
    ])
    save_table(resources, "result8_resources.csv")

    diagnostic = pd.DataFrame([{
        "TimingWarmup":TIMING_WARMUP,
        "TimingIterations":TIMING_ITERS,
        "SameModelObject":True,
        "AlternatingOrder":True,
        "NormalMean_ms":sb["mean_ms"],
        "ECMCMean_ms":sc["mean_ms"],
        "PairedDeltaMean_ms":sd["mean_ms"],
        "PairedDeltaMedian_ms":sd["median_ms"],
        "LatencyOverhead_pct":latency_overhead_pct,
        "ThroughputReduction_pct":throughput_reduction_pct,
    }])
    save_table(diagnostic, "result8_benchmark_diagnostic.csv")
    return df, pdf, resources

def _hypergeom_hit(P,t,k):
    if t<=0 or k<=0: return 0.0
    if k>P: k=P
    if P-t<k: return 1.0
    # stable product form for miss probability
    miss=1.0
    for j in range(k):
        miss *= (P-t-j)/(P-j)
    return 1.0-miss


def result9_sensitivity(ref_model):
    print("\nRESULT 9 - Sensitivity")
    # Generic theoretical sparse-parameter sampling sensitivity.
    P=sum(e.numel for e in build_parameter_registry(ref_model))
    rows=[]
    for ratio in [1e-4,1e-3,1e-2]:
        t=max(1,int(P*ratio))
        for k_eff in [8,16,32,64]:
            p=_hypergeom_hit(P,t,k_eff)
            rows.append({"ParameterCount":P,"TamperRatio":ratio,"Changed":t,"EffectiveSamples":k_eff,"SingleRequestTheory":p,
                         "Detect10":1-(1-p)**10,"Detect100":1-(1-p)**100})
    df=pd.DataFrame(rows); save_table(df,"result9_sampling_sensitivity.csv")
    return df



