import io as _io
import contextlib as _contextlib

def _result_banner(title, subtitle=None, width=78):
    print("\n" + "=" * width)
    print(title)
    if subtitle:
        print(subtitle)
    print("=" * width)

def _plot_saved(path):
    print(f"  -> saved plot {path}")

def _save_current_plot(filename):
    PLOT_DIR.mkdir(parents=True, exist_ok=True)
    p = PLOT_DIR / filename
    plt.tight_layout()
    plt.savefig(p, dpi=160, bbox_inches="tight")
    plt.close()
    _plot_saved(p)
    return p

def _silent_call(fn, *args, **kwargs):
    buf = _io.StringIO()
    with _contextlib.redirect_stdout(buf):
        return fn(*args, **kwargs)

_v81_result1 = result1_empirical_detection
_v81_result2 = result2_icrsf_structure
_v81_result4 = result4_output_preserving
_v81_result5 = result5_protocol_attacks
_v81_result6 = result6_replacement_ecmc
_v81_result7 = result7_ablation
