def result1_empirical_detection(ref_model, _unused_profile=None):
    _result_banner(
        "RESULT 1 — PURE EMPIRICAL MODEL-TAMPERING DETECTION",
        "Question: Does the full ICRSF + behavioral method distinguish genuine and modified models?"
    )
    df = _silent_call(_v81_result1, ref_model, _unused_profile)
    rows = []
    for _, r in df.iterrows():
        is_clean = (r["Scenario"] == "Clean")
        hits = int(round(float(r["DetectionRate"]) * int(r["Trials"])))
        rows.append({
            "Scenario": r["Scenario"],
            "Ground": "clean" if is_clean else "attack",
            "Trials": int(r["Trials"]),
            "Hits": hits,
            "Metric": "False rejection rate" if is_clean else "Attack detection rate",
            "Rate": float(r["DetectionRate"]),
            "CI_low": float(r["CI_low"]),
            "CI_high": float(r["CI_high"]),
        })
    out = pd.DataFrame(rows)
    print(out.to_string(index=False))

    attack_df = out[out["Ground"] == "attack"]
    fig, ax = plt.subplots(figsize=(11, 6))
    ax.barh(attack_df["Scenario"], attack_df["Rate"])
    ax.set_xlim(0, 1.05)
    ax.set_xlabel("Detection rate")
    ax.set_title("Result 1 — Empirical Model-Tampering Detection")
    _save_current_plot("result1_empirical_model_tampering.png")
    print()
    return df


def result2_icrsf_structure(ref_model):
    _result_banner(
        "RESULT 2 — STRUCTURAL VERIFICATION",
        "Question: Does ICRSF detect runtime-structural change, and does ECMC sampling follow its analytical probability?"
    )
    out = _silent_call(_v81_result2, ref_model)
    icrsf_df = out["ICRSF"]
    sim_df = out["ECMC_sampling"]

    print("\n2A — ICRSF INPUT-CONDITIONED RUNTIME STRUCTURAL EVALUATION")
    summary_rows = []
    for scenario, g in icrsf_df.groupby("Scenario"):
        trials = len(g)
        graph_fail = int((~g["GraphOK"].astype(bool)).sum())
        struct_fail = int((~g["Pass"].astype(bool)).sum())
        lo, hi = wilson_interval(struct_fail, trials)
        summary_rows.append({
            "Scenario": scenario,
            "Trials": trials,
            "Graph_mismatches": graph_fail,
            "ICRSF_detections": struct_fail,
            "Detection_rate": struct_fail / max(1, trials),
            "CI_low": lo,
            "CI_high": hi,
            "Mean_distance": float(g["Distance"].mean()),
            "Mean_tau_S": float(g["TauS"].mean()),
        })
    s2a = pd.DataFrame(summary_rows)
    print(s2a.to_string(index=False))

    print("\n2B — ECMC SPARSE SAMPLING: THEORY VS EMPIRICAL")
    cols = [
        "TargetTensor","P","TamperRatio","Changed","k","m","RegistryTensors",
        "TheoreticalSingleRequestDetection","EmpiricalDetection","CI_low","CI_high","Trials"
    ]
    print(sim_df[cols].to_string(index=False))

    fig, ax = plt.subplots(figsize=(9, 6))
    for k in sorted(sim_df["k"].unique()):
        sub = sim_df[sim_df["k"] == k]
        ax.plot(sub["TamperRatio"], sub["TheoreticalSingleRequestDetection"],
                marker="o", label=f"Theory k={k}")
        ax.scatter(sub["TamperRatio"], sub["EmpiricalDetection"],
                   marker="x", label=f"Empirical k={k}")
    ax.set_xscale("log")
    ax.set_xlabel("Tampered-parameter ratio")
    ax.set_ylabel("Single-request detection probability")
    ax.set_title("Result 2B — ECMC Sampling: Theory vs Empirical")
    ax.legend(fontsize=8, ncol=2)
    _save_current_plot("result2_ecmc_theory_vs_empirical.png")
    print()
    return out


def result3_complementarity(ref_model, profile):
    _result_banner(
        "RESULT 3 — STRUCTURAL–BEHAVIORAL COMPLEMENTARITY (MAIN RQ1 RESULT)",
        "Structural, behavioral, and combined decisions are evaluated on the same explicit-verification trials."
    )

    scenarios = [
        ("Clean", CLEAN_PATH, False),
        ("Architecture substitution", CLEAN_PATH, True),
        ("Backdoor", BACKDOOR_PATH, False),
        ("Behavioral drift", DRIFT_PATH, False),
        ("Corrupt 1/1000", CORRUPT_1K, False),
        ("Output-preserving tamper", OUTPUTPRES_PATH, False),
        ("Output bias", BIAS_PATH, False),
        ("Logit scaling", SCALE_PATH, False),
        ("Unauthorized fine-tuning", FINETUNE_PATH, False),
    ]

    rows = []
    for label, path, is_arch in scenarios:
        scenario_profile = profile_for_scenario(path)
        scenario_node = get_node_for_scenario(path)
        model = load_model(path)
        if is_arch:
            model = apply_architecture_substitution(model)

        structural_correct = 0
        behavioral_correct = 0
        combined_correct = 0

        for r in range(CORE_ROUNDS):
            x = SAMPLE_POOL[r % len(SAMPLE_POOL)]
            layer = _v87_arch_layer() if is_arch else CANDIDATE_LAYERS[r % len(CANDIDATE_LAYERS)]
            vr, _ = run_explicit_trial(
                ref_model, model, scenario_profile, x, layer,
                node_id=scenario_node, counter=r + 1
            )

            struct_pass = bool(vr["struct"])
            beh_pass = bool(vr["ez"] and vr["ed"] and vr["em"])
            full_pass = bool(vr["pass"])

            if label == "Clean":
                structural_correct += int(struct_pass)
                behavioral_correct += int(beh_pass)
                combined_correct += int(full_pass)
            else:
                structural_correct += int(not struct_pass)
                behavioral_correct += int(not beh_pass)
                combined_correct += int(not full_pass)

        rows.extend([
            {"Scenario": label, "Configuration": "Behavioral only",
             "CorrectRate": behavioral_correct / CORE_ROUNDS},
            {"Scenario": label, "Configuration": "Combined",
             "CorrectRate": combined_correct / CORE_ROUNDS},
            {"Scenario": label, "Configuration": "Structural only",
             "CorrectRate": structural_correct / CORE_ROUNDS},
        ])

    long_df = pd.DataFrame(rows)
    pivot = long_df.pivot(index="Scenario", columns="Configuration", values="CorrectRate")
    pivot = pivot[["Behavioral only", "Combined", "Structural only"]]

    print(pivot.to_string())
    save_table(long_df, "result3_complementarity.csv")

    fig, ax = plt.subplots(figsize=(11, 6))
    pivot.plot(kind="bar", ax=ax, edgecolor="white")
    ax.set_ylim(0, 1.08)
    ax.set_ylabel("Correct verification rate")
    ax.set_xlabel("")
    ax.set_title("Result 3 — Structural–Behavioral Complementarity")
    ax.legend(title="Configuration", fontsize=8)
    ax.tick_params(axis="x", rotation=30)
    _save_current_plot("result3_rq1_complementarity.png")
    print()
    return long_df


def result4_output_preserving(ref_model, profile):
    _result_banner(
        "RESULT 4 — OUTPUT-PRESERVING TAMPERING",
        "Question: Which explicit-verification gates detect the internal channel-permutation attack?"
    )
    df = _silent_call(_v81_result4, ref_model, profile)
    n = len(df)
    struct_hits = int(df["StructDetect"].astype(bool).sum())
    clean_hits = int(df["CleanDetect"].astype(bool).sum())
    delta_hits = int(df["DeltaDetect"].astype(bool).sum())
    mag_hits = int(df["MagnitudeDetect"].astype(bool).sum())
    combined_hits = int(df["CombinedDetect"].astype(bool).sum())

    rows = []
    for metric, hits in [
        ("ICRSF structural detection", struct_hits),
        ("Clean-output cosine detection", clean_hits),
        ("Perturbation-response detection", delta_hits),
        ("Magnitude-consistency detection", mag_hits),
        ("Combined detection", combined_hits),
    ]:
        lo, hi = wilson_interval(hits, n)
        rows.append({"Metric": metric, "Hits": hits, "Trials": n,
                     "Rate": hits / max(1, n), "CI_low": lo, "CI_high": hi})
    summary = pd.DataFrame(rows)
