    print(f"  magnitude-consistency failures  : {mag_hits}/{n}")

    fig, ax = plt.subplots(figsize=(9, 5))
    ax.bar(summary["Metric"], summary["Rate"])
    ax.set_ylim(0, 1.05)
    ax.set_ylabel("Detection rate")
    ax.set_title("Result 4 — Output-Preserving Tamper: Gate Contributions")
    ax.tick_params(axis="x", rotation=30)
    _save_current_plot("result4_output_preserving_gates.png")
