def result8_performance(ref_model, profile):
    _result_banner(
        "RESULT 8 — EDGE/CLOUD PERFORMANCE, PERIODIC OVERHEAD, AND RESOURCES"
    )
    print(
        "Structural = ICRSF. Behavioral = cos(z) + cos(delta_z) + magnitude. "
        "These logical checks share model execution and are not summed as independent forward-pass costs."
    )

    perf_df, periodic_df, resources_df = _silent_call(_v81_result8, ref_model, profile)

    normal = perf_df[perf_df["Condition"] == "Normal inference"].copy()
    chain = perf_df[perf_df["Condition"] == "Normal inference + ECMC"].copy()
    edge_ev = perf_df[perf_df["Condition"].str.startswith("Edge explicit")].copy()
    cloud_ev = perf_df[perf_df["Condition"].str.startswith("Cloud explicit")].copy()

    print("\n8A — EDGE-SIDE NORMAL INFERENCE OVERHEAD")
    print(pd.concat([normal, chain], ignore_index=True).to_string(index=False))
    if len(chain):
        r = chain.iloc[0]
        print(
            f"\nPaired timing diagnostic: mean Δ={float(r.get('paired_delta_mean_ms', np.nan)):.3f} ms, "
            f"median Δ={float(r.get('paired_delta_median_ms', np.nan)):.3f} ms, "
            f"latency overhead={float(r.get('ecmc_latency_overhead_pct', np.nan)):.2f}%, "
            f"throughput reduction={float(r.get('ecmc_throughput_reduction_pct', np.nan)):.2f}%"
        )

    print("\n8B — EDGE-SIDE EXPLICIT VERIFICATION COST")
    print(edge_ev.to_string(index=False))

    print("\n8C — CLOUD-SIDE VERIFICATION COST")
    print(cloud_ev.to_string(index=False))

    print("\n8D — AMORTIZED PERIODIC VERIFICATION OVERHEAD")
    print(periodic_df.to_string(index=False))

    print("\n8E — COMMUNICATION AND MEMORY OVERHEAD")
    print(resources_df.to_string(index=False))

    fig, ax = plt.subplots(figsize=(7.5, 5))
    sub = pd.concat([normal, chain], ignore_index=True)
    ax.bar(sub["Condition"], sub["mean_ms"])
    ax.set_ylabel("Mean latency (ms)")
    ax.set_title("Result 8A — Normal Inference vs ECMC")
    ax.tick_params(axis="x", rotation=15)
    _save_current_plot("result8a_edge_normal_vs_ecmc.png")

    fig, ax = plt.subplots(figsize=(7.5, 5))
    ax.bar(["Edge explicit", "Cloud verification"],
           [float(edge_ev["mean_ms"].iloc[0]), float(cloud_ev["mean_ms"].iloc[0])])
    ax.set_ylabel("Mean latency (ms)")
    ax.set_title("Result 8B/C — Explicit Verification Cost")
    _save_current_plot("result8bc_edge_cloud_cost.png")

    fig, ax = plt.subplots(figsize=(8, 5))
    ax.plot(periodic_df["R_normal_per_EV"], periodic_df["Throughput_ops_s"], marker="o")
    ax.set_xscale("log")
    ax.set_xlabel("Explicit verification every R normal requests")
    ax.set_ylabel("Amortized edge throughput (ops/s)")
    ax.set_title("Result 8D — Periodic Verification Throughput")
    _save_current_plot("result8d_periodic_throughput_overhead.png")
    print()
    return perf_df, periodic_df, resources_df


