# =====================================================================
# v8.3 VALIDATION + THEORY LAYER
# =====================================================================

def deterministic_nonce(experiment, scenario, trial, seed=SEED):
    return hashlib.sha256(
        f"{experiment}|{scenario}|{trial}|{seed}".encode()
    ).digest()[:16]


def _rounded_changed_mask(a, b, decimals=QUANTIZE_DECIMALS):
    scale = 10 ** decimals
    qa = torch.round(a.detach().cpu().float().reshape(-1) * scale)
    qb = torch.round(b.detach().cpu().float().reshape(-1) * scale)
    return qa.ne(qb)


def ecmc_changed_counts(ref_model, tampered_model):
    """Count ECMC-visible modified positions per registered parameter tensor.

    Counts are based on the same 4-decimal quantization used in the chain,
    so the analytical model matches what the implementation can actually
    distinguish.
    """
    ref_reg = build_parameter_registry(ref_model)
    tam_reg = build_parameter_registry(tampered_model)
    if [(e.module_name, e.param_name, e.numel) for e in ref_reg] != [
        (e.module_name, e.param_name, e.numel) for e in tam_reg
    ]:
        raise ValueError("ECMC theory requires matching parameter registries")

    rmods = dict(ref_model.named_modules())
    tmods = dict(tampered_model.named_modules())
    rows = []
    for e in ref_reg:
        rp = dict(rmods[e.module_name].named_parameters(recurse=False))[e.param_name]
        tp = dict(tmods[e.module_name].named_parameters(recurse=False))[e.param_name]
        changed = int(_rounded_changed_mask(rp, tp).sum().item())
        rows.append({
            "entry": e,
            "P": e.numel,
            "t": changed,
            "ratio": changed / max(1, e.numel),
        })
    return rows


def _miss_probability_within_tensor(P, t, k):
    return 1.0 - _hypergeom_hit_prob(P, t, k)


def _mean_product_for_uniform_subset(values, m):
    """Average product over all size-m subsets via elementary symmetric DP."""
    values = [float(v) for v in values]
    q = len(values)
    m = min(int(m), q)
    if m <= 0:
        return 1.0
    dp = [0.0] * (m + 1)
    dp[0] = 1.0
    seen = 0
    for v in values:
        seen += 1
        for j in range(min(m, seen), 0, -1):
            dp[j] += dp[j - 1] * v
    return dp[m] / math.comb(q, m)


def ecmc_exact_single_request_detection_probability(ref_model, tampered_model,
                                                    m=ECMC_M_OPERATORS,
                                                    k=ECMC_K_VALUES):
    """Exact expected ECMC hit probability under uniform tensor selection.

    The code selects m parameter tensors uniformly by PRF-ranking, then k
    positions uniformly within each selected tensor. The miss probability
    therefore is the mean product of each selected tensor's hypergeometric
    miss probability—not a simple global 1-(1-r)^(m*k) approximation.
    """
    counts = ecmc_changed_counts(ref_model, tampered_model)
    miss_by_tensor = [
        _miss_probability_within_tensor(r["P"], r["t"], k)
        for r in counts
    ]
    miss = _mean_product_for_uniform_subset(miss_by_tensor, m)
    return 1.0 - miss, counts


def ecmc_detection_curve_theory(single_request_pd, audit_probability, max_slots):
    """Probability of detection by each slot.

    State S0: no ECMC mismatch has occurred.
    State S1: mismatch has occurred but has not yet been audited.
    Once a mismatch occurs the chain head remains divergent, so any later
    audit detects it. This matches audit_head() behavior.
    """
    pd = float(single_request_pd)
    pa = float(audit_probability)
    s0, s1 = 1.0, 0.0
    out = {}
    for slot in range(1, int(max_slots) + 1):
        new_s0 = s0 * (1.0 - pd)
        new_s1 = (s1 + s0 * pd) * (1.0 - pa)
        s0, s1 = new_s0, new_s1
        out[slot] = 1.0 - s0 - s1
    return out


def ecmc_selector_monte_carlo(ref_model, tampered_model, trials=5000,
                              m=ECMC_M_OPERATORS, k=ECMC_K_VALUES, seed=SEED):
    """Cheap validation of the selector/theory; no model forward passes."""
    counts = ecmc_changed_counts(ref_model, tampered_model)
    registry = build_parameter_registry(ref_model)
    changed_sets = {}
    rmods = dict(ref_model.named_modules())
    tmods = dict(tampered_model.named_modules())
    for row in counts:
        e = row["entry"]
        rp = dict(rmods[e.module_name].named_parameters(recurse=False))[e.param_name]
        tp = dict(tmods[e.module_name].named_parameters(recurse=False))[e.param_name]
        mask = _rounded_changed_mask(rp, tp)
        changed_sets[e.registry_id] = set(torch.nonzero(mask, as_tuple=False).reshape(-1).tolist())

    hits = 0
    for trial in range(int(trials)):
        nonce = hashlib.sha256(f"selector-mc|{seed}|{trial}".encode()).digest()
        selected = select_registry_entries(registry, nonce, m)
        detected = False
        for e in selected:
            changed = changed_sets[e.registry_id]
            if changed:
                pos = select_positions(e, nonce, k)
                if any(j in changed for j in pos):
                    detected = True
                    break
        hits += int(detected)
    rate = hits / max(1, int(trials))
    lo, hi = wilson_interval(hits, int(trials))
    return {"hits": hits, "trials": int(trials), "rate": rate, "CI_low": lo, "CI_high": hi}


def implementation_sanity_checks(ref_model):
    _result_banner(
        "IMPLEMENTATION SANITY CHECKS — BEFORE R1",
        "These checks are designed to catch stale notebook state, invalid ICRSF distances, "
        "non-equivalent architecture substitution, and a broken ECMC analytical model."
    )
    rows = []

    # 1. ICRSF self-comparison must be exactly zero and bounded.
    x = SAMPLE_POOL[0]
    layer = _v87_arch_layer()
    nonce = deterministic_nonce("sanity", "self", 0)
    d = layer_activation_size(ref_model, layer, x)
    delta = derive_delta(nonce, d)
    alpha = compute_alpha(ref_model, layer, SAMPLE_POOL[:16])
    _, _, ev, _ = BehavioralExtractor(ref_model).extract(
        x, layer, alpha, delta, True, nonce
    )
    cmp = compare_icrsf(ev, ev, tau=ICRSF_DISTANCE_TAU)
    self_ok = bool(cmp["valid"] and cmp["graph_ok"] and cmp["distance"] == 0.0 and cmp["pass"])
    rows.append({"Check": "ICRSF self-distance", "PASS": self_ok,
                 "Detail": f"distance={cmp['distance']:.6g}, valid={cmp.get('valid')}"})

    # 2. Architecture substitution should change structure while preserving ordinary output.
    arch = apply_architecture_substitution(load_model(CLEAN_PATH))
    with torch.no_grad():
        z0 = _model_forward(ref_model, x).reshape(-1)
        z1 = _model_forward(arch, x).reshape(-1)
    max_abs = float((z0 - z1).abs().max().item())
    _, _, ref_events, _ = BehavioralExtractor(ref_model).extract(
        x, layer, alpha, delta, True, nonce
    )
    _, _, arch_events, _ = BehavioralExtractor(arch).extract(
        x, layer, alpha, delta, True, nonce
    )
    arch_cmp = compare_icrsf(arch_events, ref_events, ICRSF_DISTANCE_TAU)
    arch_ok = bool(max_abs < 1e-4 and not arch_cmp["pass"] and not arch_cmp["graph_ok"])
    rows.append({"Check": "Architecture substitution sanity", "PASS": arch_ok,
                 "Detail": f"max|Δlogit|={max_abs:.3e}, graph_ok={arch_cmp['graph_ok']}"})

    # 3. Magnitude attack should isolate E_M on representative trials.
    scale_model = load_model(SCALE_PATH)
    scale_profile = profile_for_scenario(SCALE_PATH)
    nid = get_node_for_scenario(SCALE_PATH)
    gate_counts = {"struct": 0, "ez": 0, "ed": 0, "em_fail": 0}
    ncheck = min(5, len(SAMPLE_POOL))
    for r in range(ncheck):
        vr, _ = run_explicit_trial(
            ref_model, scale_model, scale_profile, SAMPLE_POOL[r], _v87_arch_layer(),
            node_id=nid, counter=r + 1,
            nonce=deterministic_nonce("sanity", "magnitude", r)
        )
        gate_counts["struct"] += int(vr["struct"])
        gate_counts["ez"] += int(vr["ez"])
        gate_counts["ed"] += int(vr["ed"])
        gate_counts["em_fail"] += int(not vr["em"])
    mag_ok = all(gate_counts[k] == ncheck for k in ("struct", "ez", "ed", "em_fail"))
    rows.append({"Check": "Magnitude-isolator sanity", "PASS": mag_ok,
                 "Detail": f"factor={SCALE_FACTOR}; gates={gate_counts}/{ncheck}"})

    # 4. ECMC exact theory should agree with cheap selector Monte Carlo.
    tampered = load_model(CORRUPT_100)
    pd_exact, _ = ecmc_exact_single_request_detection_probability(ref_model, tampered)
    mc = ecmc_selector_monte_carlo(
        ref_model, tampered, trials=ROBUSTNESS_SELECTOR_TRIALS, seed=SEED
    )
    # Accept theory if it lies inside the Monte Carlo 95% CI, with a tiny
    # numerical cushion.
    theory_ok = (mc["CI_low"] - 1e-6 <= pd_exact <= mc["CI_high"] + 1e-6)
    rows.append({"Check": "ECMC selector theory vs Monte Carlo", "PASS": theory_ok,
                 "Detail": f"theory={pd_exact:.5f}, MC={mc['rate']:.5f}, "
                           f"95%CI=[{mc['CI_low']:.5f},{mc['CI_high']:.5f}]"})

    out = pd.DataFrame(rows)
    print(out.to_string(index=False))
    save_table(out, "implementation_sanity_checks.csv")

    failed = out.loc[~out["PASS"].astype(bool)]
    if len(failed):
        print("\nWARNING: one or more sanity checks failed. Do not interpret the affected "
              "result as evidence until the diagnostic is resolved.")
    else:
        print("\nAll implementation sanity checks passed.")
    print()
    return out


def result1_empirical_detection(ref_model, _unused_profile=None):
    _result_banner(
        "RESULT 1 — PURE EMPIRICAL MODEL-TAMPERING DETECTION",
        "Question: Does the full ICRSF + behavioral method distinguish genuine and modified models?"
    )
    scenarios = [
        ("Clean", CLEAN_PATH, False),
        ("Corrupt 1/10000", CORRUPT_10K, False),
        ("Corrupt 1/1000", CORRUPT_1K, False),
        ("Corrupt 1/100", CORRUPT_100, False),
        ("Backdoor", BACKDOOR_PATH, False),
        ("Poisoning", POISON_PATH, False),
        ("Unauthorized fine-tuning", FINETUNE_PATH, False),
        ("Early-layer tamper", EARLYMOD_PATH, False),
        ("Internal channel-permutation tamper", OUTPUTPRES_PATH, False),
        ("Behavioral drift", DRIFT_PATH, False),
        ("Architecture substitution", CLEAN_PATH, True),
        ("Output bias", BIAS_PATH, False),
        ("Logit scaling", SCALE_PATH, False),
    ]

    rows = []
    for label, path, is_arch in scenarios:
        model = load_model(path)
        if is_arch:
            model = apply_architecture_substitution(model)
        profile = profile_for_scenario(path)
        nid = get_node_for_scenario(path)

        hits = sf = bf = 0
        for r in range(CORE_ROUNDS):
            x = SAMPLE_POOL[r % len(SAMPLE_POOL)]
            layer = CANDIDATE_LAYERS[r % len(CANDIDATE_LAYERS)]
            vr, _ = run_explicit_trial(
                ref_model, model, profile, x, layer, node_id=nid, counter=r + 1,
                nonce=deterministic_nonce("r1", label, r)
            )
            detected = not vr["pass"]
            hits += int(detected)
            sf += int(not vr["struct"])
            bf += int(not (vr["ez"] and vr["ed"] and vr["em"]))

        rate = hits / CORE_ROUNDS
        lo, hi = wilson_interval(hits, CORE_ROUNDS)
        rows.append({
            "Scenario": label,
            "Ground": "clean" if label == "Clean" else "attack",
            "Trials": CORE_ROUNDS,
            "Hits": hits,
            "Metric": "False rejection rate" if label == "Clean" else "Attack detection rate",
            "Rate": rate,
            "CI_low": max(0.0, lo),
            "CI_high": min(1.0, hi),
            "StructuralFailures": sf,
            "BehavioralFailures": bf,
        })

    out = pd.DataFrame(rows)
    print(out[["Scenario","Ground","Trials","Hits","Metric","Rate","CI_low","CI_high"]].to_string(index=False))
    save_table(out, "result1_empirical_model_tampering.csv")

    attack_df = out[out["Ground"] == "attack"]
    fig, ax = plt.subplots(figsize=(11, 6))
    ax.barh(attack_df["Scenario"], attack_df["Rate"])
    ax.set_xlim(0, 1.05)
    ax.set_xlabel("Detection rate")
    ax.set_title("Result 1 — Empirical Model-Tampering Detection")
    _save_current_plot("result1_empirical_model_tampering.png")
    print()
    return out


def result2_icrsf_structure(ref_model):
    _result_banner(
        "RESULT 2 — STRUCTURAL VERIFICATION",
        "Question: What changes does ICRSF detect, and does ECMC sampling match its exact analytical probability?"
    )

    icrsf_rows = []
    cases = [
        ("Clean", CLEAN_PATH),
        ("Corrupt 1/1000", CORRUPT_1K),
        ("Early-layer tamper", EARLYMOD_PATH),
        ("Internal channel permutation", OUTPUTPRES_PATH),
        ("Fine-tuned", FINETUNE_PATH),
    ]
    for label, path in cases:
        model = load_model(path)
        profile = profile_for_scenario(path)
        for r in range(CORE_ROUNDS):
            x = SAMPLE_POOL[r % len(SAMPLE_POOL)]
            layer = CANDIDATE_LAYERS[r % len(CANDIDATE_LAYERS)]
            nonce = deterministic_nonce("r2a", label, r)
            d = layer_activation_size(ref_model, layer, x)
            delta = derive_delta(nonce, d)
            alpha = compute_alpha(ref_model, layer, SAMPLE_POOL[:16])
            _, _, re, _ = BehavioralExtractor(ref_model).extract(x, layer, alpha, delta, True, nonce)
            _, _, ee, _ = BehavioralExtractor(model).extract(x, layer, alpha, delta, True, nonce)
            tau_s = profile.tau_struct_by_layer.get(layer, ICRSF_DISTANCE_TAU)
            cmp = compare_icrsf(ee, re, tau=tau_s)
            icrsf_rows.append({
                "Scenario": label, "Trial": r, "Layer": layer,
                "GraphOK": cmp["graph_ok"], "Valid": cmp.get("valid", True),
                "Distance": cmp["distance"], "TauS": tau_s, "Pass": cmp["pass"],
                "Reason": cmp.get("reason", ""),
            })

    arch = apply_architecture_substitution(load_model(CLEAN_PATH))
    arch_prof = profile_for_scenario(CLEAN_PATH)
    for r in range(CORE_ROUNDS):
        x = SAMPLE_POOL[r % len(SAMPLE_POOL)]
        layer = _v87_arch_layer()
        nonce = deterministic_nonce("r2a", "Architecture substitution", r)
        d = layer_activation_size(ref_model, layer, x)
        delta = derive_delta(nonce, d)
        alpha = compute_alpha(ref_model, layer, SAMPLE_POOL[:16])
        _, _, re, _ = BehavioralExtractor(ref_model).extract(x, layer, alpha, delta, True, nonce)
        _, _, ee, _ = BehavioralExtractor(arch).extract(x, layer, alpha, delta, True, nonce)
        cmp = compare_icrsf(ee, re, arch_prof.tau_struct_by_layer.get(layer, ICRSF_DISTANCE_TAU))
        icrsf_rows.append({
            "Scenario": "Architecture substitution", "Trial": r, "Layer": layer,
            "GraphOK": cmp["graph_ok"], "Valid": cmp.get("valid", True),
            "Distance": cmp["distance"],
            "TauS": arch_prof.tau_struct_by_layer.get(layer, ICRSF_DISTANCE_TAU),
            "Pass": cmp["pass"], "Reason": cmp.get("reason", ""),
        })

    icrsf_df = pd.DataFrame(icrsf_rows)
    save_table(icrsf_df, "result2a_icrsf.csv")

    print("\n2A — ICRSF INPUT-CONDITIONED RUNTIME STRUCTURAL EVALUATION")
    srows = []
    for scenario, g in icrsf_df.groupby("Scenario"):
        trials = len(g)
        det = int((~g["Pass"].astype(bool)).sum())
        bad = int((~g["Valid"].astype(bool)).sum())
        lo, hi = wilson_interval(det, trials)
        srows.append({
            "Scenario": scenario,
            "Trials": trials,
            "Graph_mismatches": int((~g["GraphOK"].astype(bool)).sum()),
            "Invalid_descriptors": bad,
            "ICRSF_detections": det,
            "Detection_rate": det / max(1, trials),
            "CI_low": max(0.0, lo),
            "CI_high": min(1.0, hi),
            "Mean_distance": float(g["Distance"].mean()),
            "Max_distance": float(g["Distance"].max()),
            "Mean_tau_S": float(g["TauS"].mean()),
        })
    s2a = pd.DataFrame(srows)
    print(s2a.to_string(index=False))

    if (icrsf_df["Distance"] > 1.0 + 1e-12).any() or (~icrsf_df["Valid"].astype(bool)).any():
        print("\n[DIAGNOSTIC] Invalid ICRSF evidence was observed. This is an implementation "
              "problem, not attack evidence. Inspect result2a_icrsf.csv before interpreting R2A.")

    print("\n2B — ECMC SPARSE SAMPLING: EXACT THEORY VS EMPIRICAL")
    tampered = load_model(CORRUPT_100)
    sim_rows = []
    for k in (8, 16, 32):
        theory, _ = ecmc_exact_single_request_detection_probability(
            ref_model, tampered, m=ECMC_M_OPERATORS, k=k
        )
        mc = ecmc_selector_monte_carlo(
            ref_model, tampered, trials=STRUCT_SIM_TRIALS,
            m=ECMC_M_OPERATORS, k=k, seed=SEED + k
        )
        sim_rows.append({
            "TamperedModel": Path(CORRUPT_100).name,
            "m": ECMC_M_OPERATORS,
            "k": k,
            "ExactSingleRequestDetection": theory,
            "EmpiricalDetection": mc["rate"],
            "CI_low": mc["CI_low"],
            "CI_high": mc["CI_high"],
            "Trials": mc["trials"],
            "TheoryInside95CI": mc["CI_low"] <= theory <= mc["CI_high"],
        })
    sim_df = pd.DataFrame(sim_rows)
    save_table(sim_df, "result2b_ecmc_exact_theory_vs_empirical.csv")
    print(sim_df.to_string(index=False))

    fig, ax = plt.subplots(figsize=(8, 5))
    ax.plot(sim_df["k"], sim_df["ExactSingleRequestDetection"], marker="o", label="Exact theory")
    ax.scatter(sim_df["k"], sim_df["EmpiricalDetection"], marker="x", label="Monte Carlo")
    ax.set_xlabel("k values sampled per selected tensor")
    ax.set_ylabel("Single-request detection probability")
    ax.set_title("Result 2B — ECMC Exact Theory vs Empirical Selector")
    ax.legend()
    _save_current_plot("result2_ecmc_theory_vs_empirical.png")
    print()
    return {"ICRSF": icrsf_df, "ICRSF_summary": s2a, "ECMC_sampling": sim_df}


def result3_complementarity(ref_model, profile):
    _result_banner(
        "RESULT 3 — STRUCTURAL–BEHAVIORAL COMPLEMENTARITY (MAIN RQ1 RESULT)",
        "Structural, behavioral, and combined decisions are evaluated on the same explicit-verification trials."
    )
    scenarios = [
        ("Clean", CLEAN_PATH, False),
        ("Architecture substitution", CLEAN_PATH, True),
        ("Backdoor", BACKDOOR_PATH, False),
        ("Behavioral drift", DRIFT_PATH, False),
        ("Corrupt 1/1000", CORRUPT_1K, False),
        ("Internal channel-permutation tamper", OUTPUTPRES_PATH, False),
        ("Output bias", BIAS_PATH, False),
        ("Logit scaling", SCALE_PATH, False),
        ("Unauthorized fine-tuning", FINETUNE_PATH, False),
    ]

    rows = []
    for label, path, is_arch in scenarios:
        model = load_model(path)
        if is_arch:
            model = apply_architecture_substitution(model)
        prof = profile_for_scenario(path)
        nid = get_node_for_scenario(path)
        s_ok = b_ok = c_ok = 0

        for r in range(CORE_ROUNDS):
            x = SAMPLE_POOL[r % len(SAMPLE_POOL)]
            layer = _v87_arch_layer() if is_arch else CANDIDATE_LAYERS[r % len(CANDIDATE_LAYERS)]
            vr, _ = run_explicit_trial(
                ref_model, model, prof, x, layer, node_id=nid, counter=r + 1,
                nonce=deterministic_nonce("r3", label, r)
            )
            struct_pass = bool(vr["struct"])
            behavioral_pass = bool(vr["ez"] and vr["ed"] and vr["em"])
            combined_pass = bool(vr["pass"])
            clean = (label == "Clean")
            s_ok += int(struct_pass if clean else not struct_pass)
            b_ok += int(behavioral_pass if clean else not behavioral_pass)
            c_ok += int(combined_pass if clean else not combined_pass)

        rows.extend([
            {"Scenario": label, "Configuration": "Behavioral only", "CorrectRate": b_ok / CORE_ROUNDS},
            {"Scenario": label, "Configuration": "Combined", "CorrectRate": c_ok / CORE_ROUNDS},
            {"Scenario": label, "Configuration": "Structural only", "CorrectRate": s_ok / CORE_ROUNDS},
        ])

    long_df = pd.DataFrame(rows)
    pivot = long_df.pivot(index="Scenario", columns="Configuration", values="CorrectRate")
    pivot = pivot[["Behavioral only", "Combined", "Structural only"]]
    print(pivot.to_string())
    save_table(long_df, "result3_complementarity.csv")

    fig, ax = plt.subplots(figsize=(11, 6))
    pivot.plot(kind="bar", ax=ax, edgecolor="white")
    ax.set_ylim(0, 1.08)
    ax.set_ylabel("Correct verification rate")
    ax.set_xlabel("")
    ax.set_title("Result 3 — Structural–Behavioral Complementarity")
    ax.legend(title="Configuration", fontsize=8)
    ax.tick_params(axis="x", rotation=30)
    _save_current_plot("result3_rq1_complementarity.png")
    print()
    return long_df


def result4_output_preserving(ref_model, profile):
    _result_banner(
        "RESULT 4 — INTERNAL CHANNEL-PERMUTATION TAMPERING",
        "The ordinary clean output is function-preserving, but a fixed-coordinate "
        "perturbation challenge need not be invariant to the internal channel permutation."
    )
    model = load_model(OUTPUTPRES_PATH)
    nid = get_node_for_scenario(OUTPUTPRES_PATH)
    rows = []
    for r in range(CORE_ROUNDS):
        x = SAMPLE_POOL[r % len(SAMPLE_POOL)]
        vr, _ = run_explicit_trial(
            ref_model, model, profile, x, CANDIDATE_LAYERS[0], node_id=nid, counter=r + 1,
            nonce=deterministic_nonce("r4", "channel-permutation", r)
        )
        rows.append({
            "Trial": r,
            "StructDetect": not vr["struct"],
            "CleanDetect": not vr["ez"],
            "DeltaDetect": not vr["ed"],
            "MagnitudeDetect": not vr["em"],
            "CombinedDetect": not vr["pass"],
            "StructDistance": vr["struct_distance"],
            "CosZ": vr["cosz"],
            "CosDelta": vr["cosdz"],
            "MagRatio": vr["mag_ratio"],
        })
    df = pd.DataFrame(rows)
    save_table(df, "result4_channel_permutation.csv")

    n = len(df)
    srows = []
    for metric, col in [
        ("ICRSF structural detection", "StructDetect"),
        ("Clean-output cosine detection", "CleanDetect"),
        ("Perturbation-response detection", "DeltaDetect"),
        ("Magnitude-consistency detection", "MagnitudeDetect"),
        ("Combined detection", "CombinedDetect"),
    ]:
        hits = int(df[col].astype(bool).sum())
        lo, hi = wilson_interval(hits, n)
        srows.append({"Metric": metric, "Hits": hits, "Trials": n, "Rate": hits/n,
                      "CI_low": max(0.0,lo), "CI_high": min(1.0,hi)})
    summary = pd.DataFrame(srows)
    print(summary.to_string(index=False))
    print("\nInterpretation: this experiment demonstrates that preserving the ordinary "
          "clean function does not imply invariance of the perturbation-response channel.")
    print()
    return df


def _make_ecmc_pair(ref_model, edge_model, tag="ecmc", seed_material=None):
    mid = model_identifier(ref_model)
    if seed_material is None:
        epoch_seed = os.urandom(32)
    else:
        epoch_seed = hashlib.sha256(str(seed_material).encode()).digest()
    init = sha256_bytes(b"ANCHOR|" + tag.encode())
    cloud = ECMCCloudVerifier(ref_model, tag, mid, epoch=1,
                              epoch_seed=epoch_seed, initial_chain=init)
    edge = ECMCEdgeState(edge_model, tag, mid, epoch=1,
                         epoch_seed=epoch_seed, initial_chain=init)
    return cloud, edge, init


def _replacement_run(ref_model, tampered_model, seed, trials, max_slots,
                     audit_probability=ECMC_AUDIT_PROB):
    first = []
    for tr in range(int(trials)):
        tag = f"rep-{seed}-{tr}"
        cloud, edge, init = _make_ecmc_pair(
            ref_model, tampered_model, tag,
            seed_material=f"ecmc-epoch|{seed}|{tr}"
        )
        rng = random.Random(int(seed) * 1_000_003 + tr)
        detected = None
        for slot in range(1, int(max_slots) + 1):
            idx = rng.randrange(len(SAMPLE_POOL))
            edge.infer(SAMPLE_POOL[idx])
            if rng.random() <= audit_probability:
                audit = cloud.audit_head(edge.counter, edge.chain.hex(), start_chain=init)
                if audit["result"] == "FAIL":
                    detected = slot
                    break
        first.append(detected)
    return first


def result6_replacement_ecmc(ref_model):
    _result_banner(
        "RESULT 6 — ADAPTIVE REPLACEMENT / VERIFICATION-AWARE SWITCHING",
        "Attacker serves a tampered model on ordinary traffic while a clean model may answer recognizable explicit verification."
    )
    tampered = load_model(CORRUPT_100)
    checkpoints = [1, 5, 10, 20, 25]

    exact_pd, counts = ecmc_exact_single_request_detection_probability(
        ref_model, tampered, ECMC_M_OPERATORS, ECMC_K_VALUES
    )
    theory_curve = ecmc_detection_curve_theory(
        exact_pd, ECMC_AUDIT_PROB, REPLACEMENT_MAX_SLOTS
    )

    first = _replacement_run(
        ref_model, tampered, SEED + 6000, REPLACEMENT_TRIALS,
        REPLACEMENT_MAX_SLOTS, ECMC_AUDIT_PROB
    )

    rows = []
    for k in checkpoints:
        hits = sum(1 for d in first if d is not None and d <= k)
        lo, hi = wilson_interval(hits, REPLACEMENT_TRIALS)
        rows.append({
            "Slots": k,
            "Trials": REPLACEMENT_TRIALS,
            "Hits": hits,
            "Empirical_detection": hits / REPLACEMENT_TRIALS,
            "CI_low": max(0.0, lo),
            "CI_high": min(1.0, hi),
            "Exact_p_d": exact_pd,
            "Audit_probability": ECMC_AUDIT_PROB,
            "Theory": theory_curve[k],
            "TheoryInside95CI": lo <= theory_curve[k] <= hi,
        })
    curve_df = pd.DataFrame(rows)

    detected = [d for d in first if d is not None]
    summary = pd.DataFrame([{
        "Trials": REPLACEMENT_TRIALS,
        "Detected": len(detected),
        "DetectionRate": len(detected) / REPLACEMENT_TRIALS,
        "MeanDetectionSlot": float(np.mean(detected)) if detected else np.nan,
        "MedianDetectionSlot": float(np.median(detected)) if detected else np.nan,
        "MaxSlots": REPLACEMENT_MAX_SLOTS,
        "AuditProbability": ECMC_AUDIT_PROB,
        "ExactSingleRequest_p_d": exact_pd,
        "m": ECMC_M_OPERATORS,
        "k": ECMC_K_VALUES,
        "Window": ECMC_WINDOW,
    }])
    save_table(summary, "result6_replacement_ecmc.csv")
    save_table(curve_df, "result6_replacement_curve_theory_vs_empirical.csv")

    print(curve_df.to_string(index=False))
    if detected:
        print(f"\nDetection slot mean={np.mean(detected):.2f}, median={np.median(detected):.2f}")

    # Chain integrity attacks.
    cloud, edge, init = _make_ecmc_pair(
        ref_model, load_model(CLEAN_PATH), "chainattacks",
        seed_material="chainattacks-v83"
    )
    for i in range(6):
        edge.infer(SAMPLE_POOL[i])
    clean = copy.deepcopy(edge.records)
    attacks = []
    dup = copy.deepcopy(clean); dup.insert(3, copy.deepcopy(dup[2])); attacks.append(("Duplicate record", dup))
    reorder = copy.deepcopy(clean); reorder[2], reorder[3] = reorder[3], reorder[2]; attacks.append(("Reorder", reorder))
    delete = copy.deepcopy(clean); del delete[2]; attacks.append(("Deletion", delete))
    rollback = copy.deepcopy(clean); rollback[-1] = copy.deepcopy(clean[-2]); attacks.append(("Rollback", rollback))
    cross = copy.deepcopy(clean); cross[2]["epoch"] = 0; attacks.append(("Cross-epoch replay", cross))

    attack_rows = []
    for name, recs in attacks:
        a = cloud.audit(recs, start_chain=init, start_counter=0)
        attack_rows.append({"Attack": name, "Detected": a["result"] == "FAIL", "Reason": a["reason"]})
    chain_df = pd.DataFrame(attack_rows)
    save_table(chain_df, "result6_chain_attacks.csv")
    print("\nChain-integrity attacks:")
    print(chain_df.to_string(index=False))

    fig, ax = plt.subplots(figsize=(8, 5))
    ax.plot(curve_df["Slots"], curve_df["Empirical_detection"], marker="o", label="Empirical")
    ax.plot(curve_df["Slots"], curve_df["Theory"], marker="x", label="Exact theory")
    ax.set_ylim(0, 1.05)
    ax.set_xlabel("Ordinary protected slots")
    ax.set_ylabel("Detection probability")
    ax.set_title("Result 6 — ECMC Replacement: Theory vs Empirical")
    ax.legend()
    _save_current_plot("result6_replacement_theory_vs_empirical.png")
    print()
    return summary, curve_df, chain_df


def result7_ablation(ref_model, _unused_profile=None, replacement_summary=None):
    _result_banner(
        "RESULT 7 — TARGETED ABLATION STUDY",
        "A component is called independently necessary only when removing it materially lowers "
        "detection for its dedicated attack."
    )
    tests = [
        ("ICRSF", "Architecture substitution", CLEAN_PATH, _v87_arch_layer(), True),
        ("Clean output cosine", "Output bias", BIAS_PATH, _v87_arch_layer(), False),
        ("Perturbation response", "Internal channel permutation", OUTPUTPRES_PATH, CANDIDATE_LAYERS[0], False),
        ("Magnitude", f"Positive logit scaling x{SCALE_FACTOR:.2f}", SCALE_PATH, _v87_arch_layer(), False),
    ]

    rows = []
    for component, attack, path, layer, is_arch in tests:
        model = load_model(path)
        if is_arch:
            model = apply_architecture_substitution(model)
        prof = profile_for_scenario(path)
        nid = get_node_for_scenario(path)
        full = without = 0
        gate_fail_counts = {"struct":0, "ez":0, "ed":0, "em":0}

        for r in range(CORE_ROUNDS):
            vr, _ = run_explicit_trial(
                ref_model, model, prof, SAMPLE_POOL[r % len(SAMPLE_POOL)], layer,
                node_id=nid, counter=r + 1,
                nonce=deterministic_nonce("r7", attack, r)
            )
            full += int(not vr["pass"])
            for g in gate_fail_counts:
                gate_fail_counts[g] += int(not vr[g])

            gates = {"auth": vr["auth"], "struct": vr["struct"],
                     "ez": vr["ez"], "ed": vr["ed"], "em": vr["em"]}
            if component == "ICRSF":
                gates["struct"] = True
            elif component == "Clean output cosine":
                gates["ez"] = True
            elif component == "Perturbation response":
                gates["ed"] = True
            elif component == "Magnitude":
                gates["em"] = True
            without += int(not all(gates.values()))

        full_rate = full / CORE_ROUNDS
        without_rate = without / CORE_ROUNDS
        drop = full_rate - without_rate
        isolator_valid = bool(drop >= 0.20)
        rows.append({
            "Component": component,
            "Dedicated_attack": attack,
            "Trials": CORE_ROUNDS,
            "Detection_full": full_rate,
            "Detection_without": without_rate,
            "Detection_drop": drop,
            "Isolator_valid": isolator_valid,
            "Struct_fail": gate_fail_counts["struct"],
            "CosZ_fail": gate_fail_counts["ez"],
            "CosDelta_fail": gate_fail_counts["ed"],
            "Magnitude_fail": gate_fail_counts["em"],
        })

    if replacement_summary is None:
        rep, _, _ = result6_replacement_ecmc(ref_model)
    else:
        rep = replacement_summary
    rr = float(rep.iloc[0]["DetectionRate"])
    rows.append({
        "Component": "ECMC",
        "Dedicated_attack": "Replacement/challenge switching",
        "Trials": int(rep.iloc[0]["Trials"]),
        "Detection_full": rr,
        "Detection_without": 0.0,
        "Detection_drop": rr,
        "Isolator_valid": rr >= 0.20,
        "Struct_fail": np.nan, "CosZ_fail": np.nan,
        "CosDelta_fail": np.nan, "Magnitude_fail": np.nan,
    })

    df = pd.DataFrame(rows)
    save_table(df, "result7_ablation.csv")
    print(df.to_string(index=False))

    invalid = df.loc[~df["Isolator_valid"].astype(bool)]
    if len(invalid):
        print("\n[ABLATION WARNING] At least one dedicated attack does not isolate its "
              "component. Do not claim independent necessity for those rows.")
    print()
    return df


def result9_sensitivity(ref_model):
    _result_banner(
        "RESULT 9 — PARAMETER SENSITIVITY",
        "Exact ECMC theory under the tensor-uniform selection strategy used by the code."
    )
    registry = build_parameter_registry(ref_model)
    rows = []

    for ratio in (1e-4, 1e-3, 1e-2):
        # Hypothetical distributed tamper: each tensor has approximately the
        # same modified fraction. This matches the selection design better
        # than treating m*k as uniform samples from one global flat vector.
        hypothetical_miss = []
        for e in registry:
            t = max(1, int(round(e.numel * ratio)))
            hypothetical_miss.append(_miss_probability_within_tensor(e.numel, t, ECMC_K_VALUES))

        for m in (1, 2, 4, 8):
            m_eff = min(m, len(registry))
            miss = _mean_product_for_uniform_subset(hypothetical_miss, m_eff)
            p_detect = 1.0 - miss
            curve = ecmc_detection_curve_theory(p_detect, ECMC_AUDIT_PROB, 100)
            rows.append({
                "TamperRatioPerTensor": ratio,
                "m_selected_tensors": m_eff,
                "k_per_tensor": ECMC_K_VALUES,
                "SingleRequest_p_d": p_detect,
                "Detect10_with_audit": curve[10],
                "Detect100_with_audit": curve[100],
                "AuditProbability": ECMC_AUDIT_PROB,
            })

    df = pd.DataFrame(rows)
    save_table(df, "result9_sensitivity.csv")
    print(df.to_string(index=False))

    fig, ax = plt.subplots(figsize=(8, 5))
    for m in sorted(df["m_selected_tensors"].unique()):
        sub = df[df["m_selected_tensors"] == m]
        ax.plot(sub["TamperRatioPerTensor"], sub["SingleRequest_p_d"], marker="o", label=f"m={m}")
    ax.set_xscale("log")
    ax.set_xlabel("Tamper ratio per parameter tensor")
    ax.set_ylabel("Exact single-request p_d")
    ax.set_title("Result 9 — ECMC Sensitivity")
    ax.legend()
    _save_current_plot("result9_sensitivity.png")
    print()
    return df


def result10_robustness_validation(ref_model):
    _result_banner(
        "RESULT 10 — ROBUSTNESS / ANTI-LUCK VALIDATION",
        "Critical results are repeated with independent seeds, shuffled inputs/layers, "
        "and independently generated ECMC session/audit randomness."
    )

    explicit_cases = [
        ("Clean", CLEAN_PATH, False, "clean"),
        ("Architecture substitution", CLEAN_PATH, True, "attack"),
        ("Backdoor", BACKDOOR_PATH, False, "attack"),
        ("Internal channel permutation", OUTPUTPRES_PATH, False, "attack"),
        ("Logit scaling", SCALE_PATH, False, "attack"),
    ]

    seed_rows = []
    for seed in ROBUSTNESS_SEEDS:
        rng = random.Random(seed)
        for label, path, is_arch, ground in explicit_cases:
            model = load_model(path)
            if is_arch:
                model = apply_architecture_substitution(model)
            prof = profile_for_scenario(path)
            nid = get_node_for_scenario(path)
            hits = 0

            for r in range(ROBUSTNESS_ROUNDS):
                x = SAMPLE_POOL[rng.randrange(len(SAMPLE_POOL))]
                layer = CANDIDATE_LAYERS[rng.randrange(len(CANDIDATE_LAYERS))]
                vr, _ = run_explicit_trial(
                    ref_model, model, prof, x, layer, node_id=nid, counter=r + 1,
                    nonce=deterministic_nonce("robust-explicit", label, r, seed=seed)
                )
                event = (not vr["pass"]) if ground == "attack" else (not vr["pass"])
                hits += int(event)

            seed_rows.append({
                "Seed": seed, "Scenario": label, "Ground": ground,
                "Trials": ROBUSTNESS_ROUNDS,
                "EventRate": hits / ROBUSTNESS_ROUNDS,
                "Event": "False rejection" if ground == "clean" else "Detection",
            })

    seed_df = pd.DataFrame(seed_rows)
    save_table(seed_df, "result10_explicit_seed_robustness.csv")

    agg_rows = []
    for scenario, g in seed_df.groupby("Scenario"):
        total_hits = int(round((g["EventRate"] * g["Trials"]).sum()))
        total_n = int(g["Trials"].sum())
        lo, hi = wilson_interval(total_hits, total_n)
        agg_rows.append({
            "Scenario": scenario,
            "Seeds": len(g),
            "TotalTrials": total_n,
            "AggregateRate": total_hits / total_n,
            "SeedMean": float(g["EventRate"].mean()),
            "SeedSD": float(g["EventRate"].std(ddof=1)) if len(g) > 1 else 0.0,
            "SeedMin": float(g["EventRate"].min()),
            "SeedMax": float(g["EventRate"].max()),
            "CI_low": max(0.0, lo),
            "CI_high": min(1.0, hi),
        })
    agg_df = pd.DataFrame(agg_rows)

    print("\n10A — Explicit-verification robustness across seeds")
    print(agg_df.to_string(index=False))

    # Replacement robustness across independent seeds.
    tampered = load_model(CORRUPT_100)
    exact_pd, _ = ecmc_exact_single_request_detection_probability(ref_model, tampered)
    theory25 = ecmc_detection_curve_theory(exact_pd, ECMC_AUDIT_PROB, REPLACEMENT_MAX_SLOTS)[REPLACEMENT_MAX_SLOTS]
    rep_rows = []
    for seed in ROBUSTNESS_SEEDS:
        first = _replacement_run(
            ref_model, tampered, seed,
            ROBUSTNESS_REPLACEMENT_TRIALS,
            REPLACEMENT_MAX_SLOTS,
            ECMC_AUDIT_PROB
        )
        hits = sum(d is not None for d in first)
        rep_rows.append({
            "Seed": seed,
            "Trials": ROBUSTNESS_REPLACEMENT_TRIALS,
            "Detected": hits,
            "DetectionRateBy25": hits / ROBUSTNESS_REPLACEMENT_TRIALS,
            "MeanDetectionSlot": float(np.mean([d for d in first if d is not None]))
                                 if hits else np.nan,
            "TheoryBy25": theory25,
        })
    rep_df = pd.DataFrame(rep_rows)
    save_table(rep_df, "result10_replacement_seed_robustness.csv")

    total_hits = int(rep_df["Detected"].sum())
    total_trials = int(rep_df["Trials"].sum())
    lo, hi = wilson_interval(total_hits, total_trials)
    rep_summary = pd.DataFrame([{
        "Seeds": len(rep_df),
        "TotalTrials": total_trials,
        "AggregateDetectionBy25": total_hits / total_trials,
        "SeedSD": float(rep_df["DetectionRateBy25"].std(ddof=1)) if len(rep_df) > 1 else 0.0,
        "SeedMin": float(rep_df["DetectionRateBy25"].min()),
        "SeedMax": float(rep_df["DetectionRateBy25"].max()),
        "CI_low": max(0.0, lo),
        "CI_high": min(1.0, hi),
        "ExactTheoryBy25": theory25,
        "TheoryInsideAggregate95CI": lo <= theory25 <= hi,
    }])

    print("\n10B — Replacement robustness across seeds")
    print(rep_df.to_string(index=False))
    print("\nAggregate:")
    print(rep_summary.to_string(index=False))
    save_table(rep_summary, "result10_replacement_aggregate.csv")

    # Selector anti-bug validation at much larger cheap Monte Carlo count.
    mc = ecmc_selector_monte_carlo(
        ref_model, tampered,
        trials=ROBUSTNESS_SELECTOR_TRIALS,
        seed=SEED + 10000
    )
    selector_summary = pd.DataFrame([{
        "Trials": mc["trials"],
        "MonteCarlo_p_d": mc["rate"],
        "CI_low": mc["CI_low"],
        "CI_high": mc["CI_high"],
        "Exact_p_d": exact_pd,
        "TheoryInside95CI": mc["CI_low"] <= exact_pd <= mc["CI_high"],
    }])
    print("\n10C — ECMC selector anti-bug check")
    print(selector_summary.to_string(index=False))
    save_table(selector_summary, "result10_ecmc_selector_validation.csv")
    print()
    return {"explicit": agg_df, "replacement": rep_summary, "selector": selector_summary}



# =====================================================================
# v8.6 METHODOLOGY-CONFORMANCE LAYER
# Aligns all standalone experiments with the formal RQ1 specification:
#   1) cryptographic enrolled model identity is used in explicit evidence;
#   2) explicit-verification context binds the actual perturbation point;
#   3) successful explicit verification creates the ECMC epoch anchor;
#   4) ECMC audits use retained records from a trusted starting head and
#      return COVERAGE_GAP rather than PASS when continuity history is lost.
# =====================================================================

_ENROLLED_MODEL_ID = None

def set_enrolled_model_id(ref_model):
    global _ENROLLED_MODEL_ID
    _ENROLLED_MODEL_ID = model_identifier(ref_model)
    return _ENROLLED_MODEL_ID

def get_enrolled_model_id():
    if not _ENROLLED_MODEL_ID:
        raise RuntimeError("Enrolled model identity has not been initialized. Call set_enrolled_model_id(ref_model).")
    return _ENROLLED_MODEL_ID

def _v86_icrsf_digest(self, nonce=b""):
    payload = (
        ICRSF_VERSION.encode() + b"|" + get_enrolled_model_id().encode() + b"|" +
        CANONICALIZATION_ID.encode() + b"|" + nonce + b"|" + canonical_json(self.events)
    )
    return sha256_hex(payload)

ICRSFTracer.digest = _v86_icrsf_digest

def icrsf_digest_from_events(events, nonce: bytes):
    payload = (
        ICRSF_VERSION.encode() + b"|" + get_enrolled_model_id().encode() + b"|" +
        CANONICALIZATION_ID.encode() + b"|" + nonce + b"|" + canonical_json(events)
    )
    return sha256_hex(payload)

def _explicit_auth_payload(node_id, enrolled_model_id, nonce, counter, layer, digest, z, dz):
    return (
        node_id.encode() + b"|" + enrolled_model_id.encode() + b"|" + nonce +
        counter.to_bytes(8, "big") + b"|" + str(layer).encode() + b"|" +
        digest.encode() + _tensor_to_bytes(z) + _tensor_to_bytes(dz)
    )

def explicit_proof(model, x, layer, alpha, delta, node_id, nonce, counter, k_t):
    extractor = BehavioralExtractor(model)
    z, zp, events, digest = extractor.extract(x, layer, alpha, delta, capture_icrsf=True, nonce=nonce)
    dz = zp - z
    mid = get_enrolled_model_id()
    payload = _explicit_auth_payload(node_id, mid, nonce, counter, layer, digest, z, dz)
    tag = hmac.new(k_t, payload, hashlib.sha256).hexdigest()
    return {
        "node_id": node_id,
        "model_id": mid,
        "counter": counter,
        "nonce": nonce.hex(),
        "layer": str(layer),
        "icrsf": events,
        "icrsf_digest": digest,
        "z": z,
        "dz": dz,
        "mag": float(dz.norm().item()),
        "tag": tag,
    }

def verify_explicit(ref_model, proof, x, layer, alpha, delta, expected_node_id,
                    expected_nonce, counter, k_t, profile):
    expected_mid = get_enrolled_model_id()
    if (proof.get("node_id") != expected_node_id or
            proof.get("model_id") != expected_mid or
            proof.get("counter") != counter or
            proof.get("nonce") != expected_nonce.hex() or
            proof.get("layer") != str(layer)):
        return {"pass": False, "auth": False, "reason": "context mismatch"}

    recomputed_icrsf_digest = icrsf_digest_from_events(proof.get("icrsf", []), expected_nonce)
    if recomputed_icrsf_digest != proof.get("icrsf_digest"):
        return {"pass": False, "auth": False, "reason": "ICRSF digest/evidence mismatch"}

    payload = _explicit_auth_payload(
        expected_node_id, expected_mid, expected_nonce, counter, layer,
        proof["icrsf_digest"], proof["z"], proof["dz"]
    )
    expected_tag = hmac.new(k_t, payload, hashlib.sha256).hexdigest()
    auth = hmac.compare_digest(expected_tag, proof.get("tag", ""))

    ref_ex = BehavioralExtractor(ref_model)
    zr, zpr, ref_events, _ = ref_ex.extract(
        x, layer, alpha, delta, capture_icrsf=True, nonce=expected_nonce
    )
    dzr = zpr - zr
    tau_s = profile.tau_struct_by_layer.get(layer, profile.tau_struct)
    structural = compare_icrsf(proof["icrsf"], ref_events, tau_s)
    cosz = _cos(_quantize_tensor(proof["z"]), _quantize_tensor(zr))
    cosdz = _cos(_quantize_tensor(proof["dz"]), _quantize_tensor(dzr))
    ratio = float(proof["dz"].norm() / (dzr.norm() + 1e-12))
    ez = cosz >= profile.tau_z[layer]
    ed = cosdz >= profile.tau_dz[layer]
    em = abs(ratio - 1.0) <= profile.tau_mag[layer]
    ok = auth and structural["pass"] and ez and ed and em
    return {
        "pass": ok, "auth": auth, "struct": structural["pass"],
        "graph_ok": structural["graph_ok"],
        "struct_distance": structural["distance"],
        "cosz": cosz, "cosdz": cosdz, "mag_ratio": ratio,
        "ez": ez, "ed": ed, "em": em,
        "reason": "PASS" if ok else "verification gate failed",
    }

def _behavioral_digest_from_proof(proof):
    return sha256_hex(
        _tensor_to_bytes(proof["z"]) +
        _tensor_to_bytes(proof["dz"]) +
        canonical_json({"mag": round(float(proof.get("mag", 0.0)), 8)})
    )

def make_verified_anchor(previous_chain: bytes, node_id: str, model_id: str,
                         nonce: bytes, verify_result: dict, proof=None):
    if not verify_result.get("pass", False):
        raise ValueError("A verified anchor can only be created after PASS_EV.")
    actual_mid = get_enrolled_model_id()
    if model_id != actual_mid:
        raise ValueError("Verified-anchor model identity does not match enrollment.")
    icrsf_digest = proof.get("icrsf_digest", "") if proof is not None else ""
    behavioral_digest = _behavioral_digest_from_proof(proof) if proof is not None else sha256_hex(
        canonical_json({
            "cosz": round(float(verify_result.get("cosz", 0.0)), 8),
            "cosdz": round(float(verify_result.get("cosdz", 0.0)), 8),
            "mag_ratio": round(float(verify_result.get("mag_ratio", 0.0)), 8),
        })
    )
    return hashlib.sha256(
        b"VERIFIED-ANCHOR|" + node_id.encode() + b"|" + actual_mid.encode() + b"|" +
        nonce + b"|" + previous_chain + b"|" + icrsf_digest.encode() + b"|" +
        behavioral_digest.encode()
    ).digest()

def establish_verified_anchor(ref_model, node_id, previous_chain,
                              challenge_tag="epoch-anchor", max_attempts=64):
    """Establish an ECMC anchor from a successful clean explicit verification.

    A behavioral perturbation challenge is only informative when the trusted
    reference produces a non-zero canonical (4-decimal) Delta-z vector.
    With the fine-tuned SST-2 classifier, a particular deterministic
    input/layer/nonce can occasionally produce an extremely small response
    that quantizes entirely to zero. Cosine similarity of two zero vectors is
    undefined and PyTorch returns 0, which would incorrectly reject the clean
    model.

    The cloud therefore pre-screens candidate challenges on its trusted
    reference model and issues the first deterministic candidate whose
    canonical Delta-z is non-zero. This is challenge validation, not a retry
    after observing an untrusted edge response.
    """
    profile = profile_for_scenario(CLEAN_PATH)

    for attempt in range(int(max_attempts)):
        candidate_tag = f"{challenge_tag}|candidate={attempt}"
        idx = int.from_bytes(
            hashlib.sha256(candidate_tag.encode()).digest()[:8], "big"
        )
        x = SAMPLE_POOL[idx % len(SAMPLE_POOL)]
        layer = CANDIDATE_LAYERS[
            (idx // max(1, len(SAMPLE_POOL))) % len(CANDIDATE_LAYERS)
        ]
        nonce = hashlib.sha256(
            ("verified-anchor|" + candidate_tag).encode()
        ).digest()[:16]

        # Cloud-side challenge informativeness check using only M*.
        d = layer_activation_size(ref_model, layer, x)
        delta = derive_delta(nonce, d)
        alpha = compute_alpha(ref_model, layer, SAMPLE_POOL[:16])
        zr, zpr = BehavioralExtractor(ref_model).extract(
            x, layer, alpha, delta, capture_icrsf=False, nonce=nonce
        )
        dzr = zpr - zr
        canonical_dzr = _quantize_tensor(dzr)
        canonical_norm = float(canonical_dzr.norm().item())

        if (not math.isfinite(canonical_norm)) or canonical_norm <= 0.0:
            continue

        vr, proof = run_explicit_trial(
            ref_model, ref_model, profile, x, layer,
            node_id=node_id, counter=1, nonce=nonce
        )

        if vr.get("pass", False):
            anchor = make_verified_anchor(
                previous_chain, node_id, get_enrolled_model_id(),
                nonce, vr, proof=proof
            )
            return anchor, vr, proof

        # A clean-model failure with an informative reference response means
        # something other than the zero-Delta-z degeneracy is wrong. Do not
        # silently search until a passing trial is found.
        raise RuntimeError(
            "Trusted anchor establishment failed on an informative challenge: "
            f"layer={layer}, canonical_dz_norm={canonical_norm:.6g}, result={vr}"
        )

    raise RuntimeError(
        f"Unable to construct an informative verified-anchor challenge after "
        f"{max_attempts} deterministic candidates. Increase the perturbation "
        "strength or inspect compute_alpha()/behavioral quantization."
    )

# Retained-window auditing with a cloud-trusted checkpoint.
_v86_cloud_init_original = ECMCCloudVerifier.__init__
_v86_cloud_new_epoch_original = ECMCCloudVerifier.new_epoch

def _v86_cloud_init(self, *args, **kwargs):
    _v86_cloud_init_original(self, *args, **kwargs)
    self.trusted_counter = 0
    self.trusted_chain = bytes(self.anchor)

def _v86_cloud_new_epoch(self, epoch, epoch_seed, anchor):
    _v86_cloud_new_epoch_original(self, epoch, epoch_seed, anchor)
    self.trusted_counter = 0
    self.trusted_chain = bytes(anchor)

def _v86_audit_retained(self, records):
    if not records:
        return {"result": "COVERAGE_GAP", "reason": "no retained continuity records"}
    ordered = sorted(records, key=lambda r: int(r["counter"]))
    expected_start = int(self.trusted_counter) + 1
    first = int(ordered[0]["counter"])
    last = int(ordered[-1]["counter"])
    if first > expected_start:
        return {
            "result": "COVERAGE_GAP",
            "reason": f"requested continuity starts at {expected_start}, oldest retained record is {first}",
        }
    subset = [r for r in ordered if int(r["counter"]) >= expected_start]
    if not subset:
        return {"result": "PASS", "reason": "no new continuity records", "final_chain": self.trusted_chain.hex()}
    if int(subset[0]["counter"]) != expected_start:
        return {"result": "COVERAGE_GAP", "reason": "trusted starting interval is no longer retained"}
    out = self.audit(subset, start_chain=self.trusted_chain, start_counter=self.trusted_counter)
    if out.get("result") == "PASS":
        self.trusted_counter = int(subset[-1]["counter"])
        self.trusted_chain = bytes.fromhex(out["final_chain"])
    return out

ECMCCloudVerifier.__init__ = _v86_cloud_init
ECMCCloudVerifier.new_epoch = _v86_cloud_new_epoch
ECMCCloudVerifier.audit_retained = _v86_audit_retained

def _make_ecmc_pair(ref_model, edge_model, tag="ecmc", seed_material=None):
    mid = get_enrolled_model_id()
    if seed_material is None:
        epoch_seed = os.urandom(32)
    else:
        epoch_seed = hashlib.sha256(str(seed_material).encode()).digest()
    previous_chain = sha256_bytes(b"PREVIOUS-TRUSTED-CHAIN|" + tag.encode())
    anchor, _, _ = establish_verified_anchor(
        ref_model, tag, previous_chain, challenge_tag=f"{tag}|{seed_material}|anchor"
    )
    cloud = ECMCCloudVerifier(
        ref_model, tag, mid, epoch=1, epoch_seed=epoch_seed, initial_chain=anchor
    )
    edge = ECMCEdgeState(
        edge_model, tag, mid, epoch=1, epoch_seed=epoch_seed, initial_chain=anchor
    )
    return cloud, edge, anchor

def _replacement_run(ref_model, tampered_model, seed, trials, max_slots,
                     audit_probability=ECMC_AUDIT_PROB):
    first = []
    coverage_gaps = 0
    for tr in range(int(trials)):
        tag = f"rep-{seed}-{tr}"
        cloud, edge, _ = _make_ecmc_pair(
            ref_model, tampered_model, tag,
            seed_material=f"ecmc-epoch|{seed}|{tr}"
        )
        rng = random.Random(int(seed) * 1_000_003 + tr)
        detected = None
        trial_gap = False
        for slot in range(1, int(max_slots) + 1):
            idx = rng.randrange(len(SAMPLE_POOL))
            edge.infer(SAMPLE_POOL[idx])
            if rng.random() <= audit_probability:
                audit = cloud.audit_retained(edge.records)
                if audit["result"] == "FAIL":
                    detected = slot
                    break
                if audit["result"] == "COVERAGE_GAP":
                    trial_gap = True
                    break
        if trial_gap:
            coverage_gaps += 1
        first.append(detected)
    _replacement_run.last_coverage_gaps = coverage_gaps
    return first

_replacement_run.last_coverage_gaps = 0




