# v8.7 THREAT-MODEL + COMPLETE-EVALUATION ALIGNMENT LAYER
# =====================================================================
# Security scope:
#   * Kerckhoffs-style knowledge: algorithms/protocol/architecture are public.
#   * In-scope internal adversary may alter model/protocol state and switch
#     models, but cloud state/future challenges remain trusted/unpredictable.
#   * Arbitrary clean-copy evidence synthesis by fully rewritten instrumentation
#     is outside the software-only execution-provenance guarantee.
#   * Accidental corruption is evaluated separately as non-adversarial
#     integrity-change robustness, not as an adversarial threat.
#   * Exact function-preserving/internal-representation reparameterization is a
#     boundary/stress case, not a headline threat-model attack.
# =====================================================================

