# ------------------------- persistence --------------------------------
def mount_google_drive_output():
    """Require persistent Google Drive output; never silently fall back."""
    global RESULT_DIR, PLOT_DIR
    try:
        from google.colab import drive
    except ImportError as exc:
        raise RuntimeError(
            "v8.7 is configured for persistent Google Drive output. Run in "
            "Google Colab or explicitly adapt mount_google_drive_output()."
        ) from exc
    print("  [Drive] Mounting Google Drive...")
    drive.mount('/content/drive', force_remount=False)
    mydrive = Path('/content/drive/MyDrive')
    if not mydrive.exists():
        raise RuntimeError("Drive mounted but /content/drive/MyDrive is unavailable")
    root = mydrive / DRIVE_ROOT_SUBFOLDER
    RESULT_DIR = root / 'results'
    PLOT_DIR = root / 'plots'
    RESULT_DIR.mkdir(parents=True, exist_ok=True)
    PLOT_DIR.mkdir(parents=True, exist_ok=True)
    probe = root / '_drive_write_test.txt'
    probe.write_text(f'{V87_VERSION}: persistent output verified\n', encoding='utf-8')
    if not probe.exists() or 'verified' not in probe.read_text(encoding='utf-8'):
        raise RuntimeError("Google Drive write/read verification failed")
    print("  [Drive] WRITE TEST: PASS")
    print(f"  [Drive] Root    : {root}")
    print(f"  [Drive] Results : {RESULT_DIR}")
    print(f"  [Drive] Plots   : {PLOT_DIR}")
    return root

# ------------------------- helper utilities ----------------------------
def _v87_forward(model, x):
    # TinyBERT inputs are structured dictionaries; all forwarding must use
    # the architecture-specific wrapper.
    return _model_forward(model, x)


def _v87_model_bytes(model):
    total = 0
    for t in list(model.parameters()) + list(model.buffers()):
        if torch.is_tensor(t):
            total += int(t.numel()) * int(t.element_size())
    return int(total)


def _v87_proof_size_bytes(proof):
    # Canonical wire-size estimate. Tensor payloads use the same quantized
    # float32 representation as the authenticated proof construction.
    n = 0
    n += len(str(proof.get('node_id', '')).encode())
    n += len(str(proof.get('model_id', '')).encode())
    n += 8
    n += 16
    n += len(str(proof.get('layer', '')).encode())
    n += len(canonical_json(proof.get('icrsf', [])))
    n += 32  # binary SHA-256 digest equivalent
    if torch.is_tensor(proof.get('z')):
        n += len(_tensor_to_bytes(proof['z']))
    if torch.is_tensor(proof.get('dz')):
        n += len(_tensor_to_bytes(proof['dz']))
    n += 8   # magnitude as float64-equivalent reporting field
    n += 32  # HMAC-SHA256 tag equivalent
    return int(n)


