def _v87_bootstrap_mean_ci(values, seed=SEED, iters=V87_BOOTSTRAP_ITERS):
    a = np.asarray(values, dtype=float)
    if len(a) == 0:
        return (float('nan'), float('nan'))
    if len(a) == 1:
        return (float(a[0]), float(a[0]))
    rng = np.random.default_rng(int(seed))
    means = np.empty(int(iters), dtype=float)
    n = len(a)
    for i in range(int(iters)):
        means[i] = a[rng.integers(0, n, size=n)].mean()
    return float(np.percentile(means, 2.5)), float(np.percentile(means, 97.5))


def _v87_mcnemar_exact_p(a_full, b_without):
    # Exact two-sided McNemar/binomial test on discordant paired outcomes.
    a = np.asarray(a_full, dtype=bool)
    b = np.asarray(b_without, dtype=bool)
    n10 = int(np.sum(a & ~b))
    n01 = int(np.sum(~a & b))
    n = n10 + n01
    if n == 0:
        return 1.0, n10, n01
    k = min(n10, n01)
    tail = sum(math.comb(n, i) for i in range(k + 1)) / (2 ** n)
    return min(1.0, 2.0 * tail), n10, n01

# ----------------- informative challenge construction ------------------
_V87_ALPHA_CACHE = {}
_V87_ACTSIZE_CACHE = {}


def _v87_alpha(ref_model, layer):
    if layer not in _V87_ALPHA_CACHE:
        _V87_ALPHA_CACHE[layer] = compute_alpha(ref_model, layer, SAMPLE_POOL[:min(16, len(SAMPLE_POOL))])
    return _V87_ALPHA_CACHE[layer]


def _v87_activation_size(ref_model, layer, x):
    # Activation size may depend on input shape for some adapters, so cache by
    # layer only after observing the standard evaluation input shape.
    key = (layer, str(type(x)), tuple(x.shape) if torch.is_tensor(x) else 'structured')
    if key not in _V87_ACTSIZE_CACHE:
        _V87_ACTSIZE_CACHE[key] = layer_activation_size(ref_model, layer, x)
    return _V87_ACTSIZE_CACHE[key]


def _v87_prepare_informative_challenge(ref_model, experiment, scenario, trial,
                                       forced_layer=None, max_attempts=V87_MAX_CHALLENGE_ATTEMPTS):
    """Pre-screen challenge informativeness using only the trusted M*.

    Candidates with a zero/non-finite quantized reference Delta-z are never
    issued. This avoids undefined cosine(0,0) while preserving Kerckhoffs-style
    public algorithms: only future verifier randomness is unpredictable.
    """
    ref_ex = BehavioralExtractor(ref_model)
    for attempt in range(int(max_attempts)):
        token = f'v87|{experiment}|{scenario}|{trial}|candidate={attempt}|seed={SEED}'
        raw = hashlib.sha256(token.encode()).digest()
        idx = int.from_bytes(raw[:8], 'big') % len(SAMPLE_POOL)
        x = SAMPLE_POOL[idx]
        if forced_layer is None:
            li = int.from_bytes(raw[8:12], 'big') % len(CANDIDATE_LAYERS)
            layer = CANDIDATE_LAYERS[li]
        else:
            layer = forced_layer
        nonce = hashlib.sha256((token + '|nonce').encode()).digest()[:16]
        d = _v87_activation_size(ref_model, layer, x)
        delta = derive_delta(nonce, d)
        alpha = _v87_alpha(ref_model, layer)
        zr, zpr, ref_events, ref_digest = ref_ex.extract(
            x, layer, alpha, delta, capture_icrsf=True, nonce=nonce
        )
        dzr = zpr - zr
        qdz = _quantize_tensor(dzr)
        qnorm = float(qdz.norm().item())
        if math.isfinite(qnorm) and qnorm > V87_DZ_NORM_EPS:
            return {
                'x': x, 'layer': layer, 'nonce': nonce, 'alpha': alpha,
                'delta': delta, 'zr': zr, 'dzr': dzr,
                'ref_events': ref_events, 'ref_digest': ref_digest,
                'attempts': attempt + 1, 'reference_dz_qnorm': qnorm,
            }
    raise RuntimeError(
        f'No informative challenge found for {experiment}/{scenario}/trial={trial} '
        f'after {max_attempts} candidates.'
    )


def _v87_trial(ref_model, edge_model, profile, node_id, scenario, trial,
               experiment='primary', forced_layer=None, k_t=None):
    enrolled = profile_for_node(node_id)
    if profile is not enrolled:
        raise RuntimeError(
            f'Cross-node profile use blocked: {node_id} must use its own frozen Node x Layer profile.'
        )
    k_t = k_t or (b'V' * 32)
    ch = _v87_prepare_informative_challenge(
        ref_model, experiment, scenario, trial, node_id=node_id, forced_layer=forced_layer
    )
    proof = explicit_proof(
        edge_model, ch['x'], ch['layer'], ch['alpha'], ch['delta'], node_id,
        ch['nonce'], trial + 1, k_t
    )
    vr = verify_explicit(
        ref_model, proof, ch['x'], ch['layer'], ch['alpha'], ch['delta'],
        node_id, ch['nonce'], trial + 1, k_t, profile
    )
    tau_s = profile.tau_struct_by_layer.get(ch['layer'], profile.tau_struct)
    cmp = compare_icrsf(proof['icrsf'], ch['ref_events'], tau_s)
    struct_detect = not bool(cmp['pass'])
    beh_detect = not bool(vr.get('ez', False) and vr.get('ed', False) and vr.get('em', False))
    combined_detect = bool(struct_detect or beh_detect or not vr.get('auth', False))
    return {
        'Scenario': scenario,
        'Trial': trial,
        'Layer': ch['layer'],
        'ChallengeAttempts': ch['attempts'],
        'ReferenceDzQuantizedNorm': ch['reference_dz_qnorm'],
        'AuthPass': bool(vr.get('auth', False)),
        'StructPass': bool(cmp['pass']),
        'StructValid': bool(cmp.get('valid', True)),
        'GraphOK': bool(cmp.get('graph_ok', False)),
        'StructDistance': float(cmp.get('distance', 1.0)),
        'TauS': float(tau_s),
        'CosZ': float(vr.get('cosz', float('nan'))),
        'TauZ': float(profile.tau_z[ch['layer']]),
        'CosDelta': float(vr.get('cosdz', float('nan'))),
        'TauDelta': float(profile.tau_dz[ch['layer']]),
        'MagRatio': float(vr.get('mag_ratio', float('nan'))),
        'TauMag': float(profile.tau_mag[ch['layer']]),
        'EZPass': bool(vr.get('ez', False)),
        'EDPass': bool(vr.get('ed', False)),
        'EMPass': bool(vr.get('em', False)),
        'StructuralDetect': bool(struct_detect),
        'BehavioralDetect': bool(beh_detect),
        'CombinedDetect': bool(combined_detect),
        'FullPass': bool(vr.get('pass', False)),
        'ProofBytes': _v87_proof_size_bytes(proof),
    }

# ------------------ v8.7 enrollment / threshold hygiene ----------------
def calibrate_profile(ref_model, samples, edge_model=None, node_id='node'):
    """Trusted enrollment using only informative behavioral challenges.

    Zero/non-finite canonical Delta-z candidates are excluded before threshold
    estimation; otherwise clean-clean cosine calibration can collapse toward
    0/-1 because cosine(0,0) is undefined. tau_M remains the predeclared +/-10%
    tolerance, not attack-tuned.
    """
    edge_model = edge_model or ref_model
    profile = IntegrityProfile(node_id=node_id)
    ref_ex = BehavioralExtractor(ref_model)
    edge_ex = BehavioralExtractor(edge_model)
    base_samples = list(samples)
    if not base_samples:
        raise RuntimeError('Enrollment requires trusted samples')
    profile.informative_counts = {}
    profile.candidate_counts = {}

    print(f"\n  [Enrollment v8.7] {node_id}: target {ENROLL_INPUTS} informative inputs/layer")
    for layer in CANDIDATE_LAYERS:
        cz, cd, struct_dist = [], [], []
        attempts = 0
        j = 0
        max_candidates = max(ENROLL_INPUTS * 10, 50)
        while len(cd) < ENROLL_INPUTS and attempts < max_candidates:
            x = base_samples[j % len(base_samples)]
            nonce = hashlib.sha256(
                f'v87-enroll|{SEED}|{layer}|{attempts}|{j}'.encode()
            ).digest()[:16]
            d = _v87_activation_size(ref_model, layer, x)
            delta = derive_delta(nonce, d)
            alpha = _v87_alpha(ref_model, layer)
            zr, zpr, re, _ = ref_ex.extract(x, layer, alpha, delta, True, nonce)
            qdzr = _quantize_tensor(zpr - zr)
            attempts += 1
            j += 1
            qnorm = float(qdzr.norm().item())
            if not math.isfinite(qnorm) or qnorm <= V87_DZ_NORM_EPS:
                continue
            ze, zpe, ee, _ = edge_ex.extract(x, layer, alpha, delta, True, nonce)
            dzr, dze = zpr-zr, zpe-ze
            cz.append(_cos(_quantize_tensor(zr), _quantize_tensor(ze)))
            cd.append(_cos(_quantize_tensor(dzr), _quantize_tensor(dze)))
            cmp = compare_icrsf(ee, re, tau=1.0)
            if cmp.get('valid', True):
                struct_dist.append(float(cmp['distance']))

        if len(cd) < max(3, min(ENROLL_INPUTS, 5)):
            raise RuntimeError(
                f'Insufficient informative enrollment challenges for layer {layer}: '
                f'{len(cd)}/{ENROLL_INPUTS} after {attempts} candidates.'
            )

        def _tau(vals, sigma_floor, fallback):
            if len(vals) < 2:
                return fallback
            zvals = _fisher_z(np.asarray(vals, dtype=float))
            mu = float(zvals.mean())
            sd = max(float(zvals.std(ddof=1)), float(sigma_floor))
            raw = _fisher_inv(mu - K_SIGMA * sd)
            return float(np.floor(raw * (10**QUANTIZE_DECIMALS)) / (10**QUANTIZE_DECIMALS))

        profile.tau_z[layer] = _tau(cz, SIGMA_Z_FLOOR, 0.95)
        profile.tau_dz[layer] = _tau(cd, SIGMA_DZ_FLOOR, 0.90)
        profile.tau_mag[layer] = 0.10
        smu = float(np.mean(struct_dist)) if struct_dist else 0.0
        ssd = float(np.std(struct_dist, ddof=1)) if len(struct_dist) > 1 else 0.0
        profile.tau_struct_by_layer[layer] = max(ICRSF_DISTANCE_TAU, smu + K_SIGMA * ssd)
        profile.informative_counts[layer] = len(cd)
        profile.candidate_counts[layer] = attempts
        print(
            f"    {layer:<14} informative={len(cd):>2}/{attempts:<3} "
            f"tau_z={profile.tau_z[layer]:.4f} tau_dz={profile.tau_dz[layer]:.4f} "
            f"tau_S={profile.tau_struct_by_layer[layer]:.5f}"
        )
    return profile


def enroll_all_nodes(ref_model):
    """Freeze one trusted calibration template, then clone it to all simulated nodes."""
    global _NODE_POOL, _NODE_IDS, _INTEGRITY_PROFILES
    rng = random.Random(NODE_POOL_SEED)
    node_ids = [f'node_{i}' for i in range(len(NODE_POOL_MODELS))]
    rng.shuffle(node_ids)
    trusted_edge = load_model(CLEAN_PATH)
    samples = SAMPLE_POOL[:max(ENROLL_INPUTS, min(len(SAMPLE_POOL), ENROLL_INPUTS * 3))]
    print('\n' + '='*72)
    print(f'NODE POOL ENROLLMENT v8.7 ({len(node_ids)} nodes; clean trusted template)')
    print('='*72)
    template = calibrate_profile(ref_model, samples, edge_model=trusted_edge, node_id='trusted-template')
    _INTEGRITY_PROFILES = {}
    for nid, scenario_path in zip(node_ids, NODE_POOL_MODELS):
        prof = copy.deepcopy(template)
        prof.node_id = nid
        _INTEGRITY_PROFILES[nid] = prof
        print(f'  {nid:<10} enrolled=CLEAN_PATH  assigned_after_enrollment={Path(scenario_path).name}')
    _NODE_IDS = node_ids
    _NODE_POOL = dict(zip(node_ids, NODE_POOL_MODELS))
    print('  All node profiles frozen before adversarial scenario assignment.')
    return _INTEGRITY_PROFILES

# ---------------- verified anchor with informative challenge -------------
def establish_verified_anchor(ref_model, node_id, previous_chain,
                              challenge_tag='epoch-anchor', max_attempts=V87_MAX_CHALLENGE_ATTEMPTS):
    profile = profile_for_scenario(CLEAN_PATH)
    ch = _v87_prepare_informative_challenge(
        ref_model, 'verified-anchor', challenge_tag, 0, node_id=node_id,
        forced_layer=None, max_attempts=max_attempts
    )
    k_t = b'T' * 32
    proof = explicit_proof(
        ref_model, ch['x'], ch['layer'], ch['alpha'], ch['delta'], node_id,
        ch['nonce'], 1, k_t
    )
    vr = verify_explicit(
        ref_model, proof, ch['x'], ch['layer'], ch['alpha'], ch['delta'], node_id,
        ch['nonce'], 1, k_t, profile
    )
    if not vr.get('pass', False):
        raise RuntimeError(
            f"Trusted anchor establishment failed on an informative challenge: "
            f"layer={ch['layer']}, dz_qnorm={ch['reference_dz_qnorm']:.6g}, result={vr}"
        )
    anchor = make_verified_anchor(
        previous_chain, node_id, get_enrolled_model_id(), ch['nonce'], vr, proof=proof
    )
    return anchor, vr, proof

# ---------------- RESULT 1: primary threat-model integrity ---------------
def v87_result1_primary_integrity(ref_model):
    _result_banner(
        'RESULT 1 — PRIMARY THREAT-MODEL MODEL-INTEGRITY EVALUATION',
        'ADR/AER and clean FRR/CAR with informative verifier challenges and 95% Wilson intervals.'
    )
    rows = []
    for label, path, is_arch, ground in _v87_primary_scenarios():
        model = _v87_attack_model(path, is_arch)
        prof, nid = _v87_profile_node(path)
        forced = _v87_arch_layer() if is_arch else None
        for r in range(V87_SECURITY_ROUNDS):
            rec = _v87_trial(
                ref_model, model, prof, nid, label, r,
                experiment='v87-primary', forced_layer=forced
            )
            rec['Ground'] = ground
            rows.append(rec)
        print(f"  completed {label}: {V87_SECURITY_ROUNDS} trials")
    trials = pd.DataFrame(rows)
    save_table(trials, 'result1_primary_threat_trials.csv')

    summary = []
    for scenario, g in trials.groupby('Scenario', sort=False):
        ground = str(g['Ground'].iloc[0])
        n = len(g)
        rejects = int(g['CombinedDetect'].sum())
        invalid = int((~g['StructValid'].astype(bool)).sum())
        valid_g = g[g['StructValid'].astype(bool)]
        valid_rejects = int(valid_g['CombinedDetect'].sum())
        lo, hi = wilson_interval(rejects, n)
        if ground == 'clean':
            metric = 'FRR'
            primary_rate = rejects / n
            complementary = 1.0 - primary_rate  # CAR
        else:
            metric = 'ADR'
            primary_rate = rejects / n
            complementary = 1.0 - primary_rate  # AER
        summary.append({
            'Scenario': scenario, 'Ground': ground, 'Trials': n,
            'Metric': metric, 'Rate': primary_rate,
            'ComplementaryMetric': 'CAR' if ground == 'clean' else 'AER',
            'ComplementaryRate': complementary,
            'CI_low': lo, 'CI_high': hi,
            'InvalidEvidence': invalid,
            'InvalidEvidenceRate': invalid / n,
            'DecidableValidTrials': len(valid_g),
            'RateAmongValidEvidence': valid_rejects / max(1, len(valid_g)),
            'MeanChallengeAttempts': float(g['ChallengeAttempts'].mean()),
            'MaxChallengeAttempts': int(g['ChallengeAttempts'].max()),
            'MeanProofBytes': float(g['ProofBytes'].mean()),
        })
    summary_df = pd.DataFrame(summary)
    save_table(summary_df, 'result1_primary_threat_summary.csv')
    print(summary_df.to_string(index=False))
    return trials, summary_df

# -------- RESULT 2: structural / behavioral / combined complementarity --
def v87_result2_complementarity(primary_trials):
    _result_banner(
        'RESULT 2 — STRUCTURAL-ONLY vs BEHAVIORAL-ONLY vs COMBINED',
        'Includes mutually exclusive S-only/B-only/both/miss decomposition and combined-coverage gain.'
    )
    attack = primary_trials[primary_trials['Ground'] == 'attack'].copy()
    rows = []
    for scenario, g in attack.groupby('Scenario', sort=False):
        s = g['StructuralDetect'].astype(bool).to_numpy()
        b = g['BehavioralDetect'].astype(bool).to_numpy()
        c = np.logical_or(s, b)
        ds, db, dc = float(s.mean()), float(b.mean()), float(c.mean())
        rows.append({
            'Scenario': scenario, 'Trials': len(g),
            'StructuralDetection': ds,
            'BehavioralDetection': db,
            'CombinedDetection': dc,
            'StructuralOnly': float(np.mean(s & ~b)),
            'BehavioralOnly': float(np.mean(~s & b)),
            'Both': float(np.mean(s & b)),
            'Miss': float(np.mean(~s & ~b)),
            'CombinedCoverageGain': dc - max(ds, db),
        })
    out = pd.DataFrame(rows)
    save_table(out, 'result2_channel_complementarity.csv')

    clean = primary_trials[primary_trials['Ground'] == 'clean']
    s_frr = float(clean['StructuralDetect'].mean())
    b_frr = float(clean['BehavioralDetect'].mean())
    c_frr = float(clean['CombinedDetect'].mean())
    clean_df = pd.DataFrame([{
        'Trials': len(clean),
        'Structural_FRR': s_frr, 'Structural_CAR': 1-s_frr,
        'Behavioral_FRR': b_frr, 'Behavioral_CAR': 1-b_frr,
        'Combined_FRR': c_frr, 'Combined_CAR': 1-c_frr,
    }])
    save_table(clean_df, 'result2_clean_channel_frr.csv')
    print(out.to_string(index=False))
    print('\nClean-model channel FRR/CAR:')
    print(clean_df.to_string(index=False))
    return out, clean_df

# ---------------- RESULT 3: evidence / challenge diagnostics -------------
def v87_result3_evidence_diagnostics(primary_trials):
    _result_banner(
        'RESULT 3 — EVIDENCE, GATE, AND CHALLENGE-QUALITY DIAGNOSTICS',
        'No invalid descriptor or challenge-screening behavior is hidden inside a detection percentage.'
    )
    rows = []
    gates = []
    challenges = []
    for scenario, g in primary_trials.groupby('Scenario', sort=False):
        valid = g['StructValid'].astype(bool)
        rows.append({
            'Scenario': scenario, 'Trials': len(g),
            'GraphMismatchRate': float((~g['GraphOK'].astype(bool)).mean()),
            'InvalidEvidenceRate': float((~valid).mean()),
            'MeanStructDistance': float(g['StructDistance'].mean()),
            'MedianStructDistance': float(g['StructDistance'].median()),
            'P95StructDistance': float(np.percentile(g['StructDistance'], 95)),
            'MaxStructDistance': float(g['StructDistance'].max()),
            'MeanStructMargin_dMinusTau': float((g['StructDistance']-g['TauS']).mean()),
        })
        gates.append({
            'Scenario': scenario,
            'EZ_FailureRate': float((~g['EZPass'].astype(bool)).mean()),
            'ED_FailureRate': float((~g['EDPass'].astype(bool)).mean()),
            'EM_FailureRate': float((~g['EMPass'].astype(bool)).mean()),
            'CosZ_mean': float(g['CosZ'].mean()),
            'CosZ_P5': float(np.percentile(g['CosZ'], 5)),
            'CosDelta_mean': float(g['CosDelta'].mean()),
            'CosDelta_P5': float(np.percentile(g['CosDelta'], 5)),
            'MagRatio_mean': float(g['MagRatio'].mean()),
            'MagRatio_median': float(g['MagRatio'].median()),
        })
        total_candidates = int(g['ChallengeAttempts'].sum())
        issued = len(g)
        challenges.append({
            'Scenario': scenario,
            'IssuedChallenges': issued,
            'CandidateChallenges': total_candidates,
            'InformativeChallengeRate': issued / max(1, total_candidates),
            'ChallengeRejectRate': (total_candidates-issued) / max(1, total_candidates),
            'MeanAttempts': float(g['ChallengeAttempts'].mean()),
            'MaxAttempts': int(g['ChallengeAttempts'].max()),
            'MinReferenceDzQNorm': float(g['ReferenceDzQuantizedNorm'].min()),
        })
    struct_df = pd.DataFrame(rows)
    gate_df = pd.DataFrame(gates)
    challenge_df = pd.DataFrame(challenges)
    save_table(struct_df, 'result3a_icrsf_diagnostics.csv')
    save_table(gate_df, 'result3b_behavioral_gate_matrix.csv')
    save_table(challenge_df, 'result3c_challenge_quality.csv')
    print('\n3A — ICRSF diagnostics')
    print(struct_df.to_string(index=False))
    print('\n3B — Behavioral gate diagnostics')
    print(gate_df.to_string(index=False))
    print('\n3C — Challenge quality')
    print(challenge_df.to_string(index=False))
    return struct_df, gate_df, challenge_df

# ---------------- RESULT 4: protocol + transmission attacks --------------
def _v87_retag(proof, node_id, nonce, counter, layer, key):
    proof['mag'] = float(proof['dz'].norm().item()) if torch.is_tensor(proof.get('dz')) else proof.get('mag', 0.0)
    payload = _explicit_auth_payload(
        node_id, get_enrolled_model_id(), nonce, counter, layer,
        proof['icrsf_digest'], proof['z'], proof['dz']
    )
    proof['tag'] = hmac.new(key, payload, hashlib.sha256).hexdigest()
    return proof


def v87_result4_protocol_channel(ref_model):
    _result_banner(
        'RESULT 4 — VERIFICATION-PROTOCOL AND TRANSMISSION-CHANNEL ATTACKS',
        'Replay, theft, external forgery, authenticated internal fabrication, context modification, and impersonation.'
    )
    keyA, keyB = b'A'*32, b'B'*32
    nodeA = get_node_for_scenario(CLEAN_PATH)
    nodeB = next((n for n in _NODE_IDS if n != nodeA), nodeA)
    profA = profile_for_scenario(CLEAN_PATH)
    profB = _INTEGRITY_PROFILES[nodeB]
    attack_names = [
        'Replay', 'Proof theft', 'External proof forgery',
        'Authenticated internal behavioral fabrication',
        'Authenticated internal structural fabrication',
        'Challenge/context modification', 'Response modification in transit',
        'Endpoint impersonation / rogue key',
    ]
    stats = {a: {'accepted':0, 'attempts':0, 'auth_pass':0} for a in attack_names}

    for r in range(V87_PROTOCOL_ROUNDS):
        ch = _v87_prepare_informative_challenge(
            ref_model, 'protocol', 'base', r, node_id=nodeA
        )
        good = explicit_proof(
            ref_model, ch['x'], ch['layer'], ch['alpha'], ch['delta'], nodeA,
            ch['nonce'], r+1, keyA
        )
        nonce2 = hashlib.sha256(ch['nonce'] + b'fresh-next').digest()[:16]

        cases = {}
        # stale proof under new nonce/counter
        cases['Replay'] = (good, nodeA, nonce2, r+2, keyA, profA, ch['delta'])
        cases['Proof theft'] = (good, nodeB, ch['nonce'], r+1, keyB, profB, ch['delta'])

        ext = copy.deepcopy(good)
        ext['z'] = torch.randn_like(good['z'])
        ext['dz'] = torch.randn_like(good['dz'])
        _v87_retag(ext, nodeA, ch['nonce'], r+1, ch['layer'], os.urandom(32))
        cases['External proof forgery'] = (ext, nodeA, ch['nonce'], r+1, keyA, profA, ch['delta'])

        ib = copy.deepcopy(good)
        ib['z'] = good['z'] + torch.ones_like(good['z']) * 7.0
        ib['dz'] = torch.randn_like(good['dz']) * 3.0
        _v87_retag(ib, nodeA, ch['nonce'], r+1, ch['layer'], keyA)
        cases['Authenticated internal behavioral fabrication'] = (ib, nodeA, ch['nonce'], r+1, keyA, profA, ch['delta'])

        ins = copy.deepcopy(good)
        if ins.get('icrsf'):
            ins['icrsf'][0] = dict(ins['icrsf'][0])
            ins['icrsf'][0]['op'] = 'FORGED_OPERATOR'
        ins['icrsf_digest'] = icrsf_digest_from_events(ins.get('icrsf', []), ch['nonce'])
        _v87_retag(ins, nodeA, ch['nonce'], r+1, ch['layer'], keyA)
        cases['Authenticated internal structural fabrication'] = (ins, nodeA, ch['nonce'], r+1, keyA, profA, ch['delta'])

        cases['Challenge/context modification'] = (good, nodeA, nonce2, r+1, keyA, profA, ch['delta'])

        rm = copy.deepcopy(good)
        rm['z'] = rm['z'].clone(); rm['z'].reshape(-1)[0] += 0.5
        cases['Response modification in transit'] = (rm, nodeA, ch['nonce'], r+1, keyA, profA, ch['delta'])

        rogue = explicit_proof(
            ref_model, ch['x'], ch['layer'], ch['alpha'], ch['delta'], nodeA,
            ch['nonce'], r+1, os.urandom(32)
        )
        cases['Endpoint impersonation / rogue key'] = (rogue, nodeA, ch['nonce'], r+1, keyA, profA, ch['delta'])

        for name, (proof, expected_node, expected_nonce, ctr, key, prof, delta_for_verify) in cases.items():
            # If expected nonce changes, derive the verifier-side perturbation from that nonce.
            if expected_nonce != ch['nonce']:
                d = _v87_activation_size(ref_model, ch['layer'], ch['x'])
                delta_for_verify = derive_delta(expected_nonce, d)
            vr = verify_explicit(
                ref_model, proof, ch['x'], ch['layer'], ch['alpha'], delta_for_verify,
                expected_node, expected_nonce, ctr, key, prof
            )
            stats[name]['attempts'] += 1
            stats[name]['accepted'] += int(bool(vr.get('pass', False)))
            stats[name]['auth_pass'] += int(bool(vr.get('auth', False)))

    rows = []
    for name in attack_names:
        n = stats[name]['attempts']; accepted = stats[name]['accepted']
        rejected = n - accepted
        pdr = rejected / max(1,n); pasr = accepted / max(1,n)
        lo, hi = wilson_interval(rejected, n)
        rows.append({
            'Attack': name, 'Attempts': n, 'Accepted': accepted, 'Rejected': rejected,
            'PASR': pasr, 'PDR': pdr, 'PDR_CI_low': lo, 'PDR_CI_high': hi,
            'AuthPassRate': stats[name]['auth_pass']/max(1,n),
        })
    out = pd.DataFrame(rows)
    save_table(out, 'result4_protocol_and_channel_attacks.csv')
    print(out.to_string(index=False))
    return out

# ---------------- RESULT 5: ECMC replacement / chain audit ---------------
def _v87_replacement_detailed(ref_model, tampered_model, seed, trials, max_slots):
    records = []
    for tr in range(int(trials)):
        cloud, edge, _ = _make_ecmc_pair(
            ref_model, tampered_model, f'v87-rep-{seed}-{tr}',
            seed_material=f'v87-rep-epoch|{seed}|{tr}'
        )
        rng = random.Random(int(seed)*1000003 + tr)
        detected_slot = None
        gap_slot = None
        audits = 0
        for slot in range(1, int(max_slots)+1):
            edge.infer(SAMPLE_POOL[rng.randrange(len(SAMPLE_POOL))])
            if rng.random() <= ECMC_AUDIT_PROB:
                audits += 1
                audit = cloud.audit_retained(edge.records)
                if audit['result'] == 'FAIL':
                    detected_slot = slot; break
                if audit['result'] == 'COVERAGE_GAP':
                    gap_slot = slot; break
        records.append({
            'Trial': tr, 'DetectedSlot': detected_slot,
            'CoverageGapSlot': gap_slot, 'Audits': audits,
            'EligibleSlots': int(max_slots if detected_slot is None and gap_slot is None else (detected_slot or gap_slot)),
        })
    return pd.DataFrame(records)


def _tinybert_replacement_corruption_audit(ref_model, tampered_model, denom=100):
    """Fail fast if replacement corruption is concentrated in only one tensor."""
    counts = ecmc_changed_counts(ref_model, tampered_model)
    changed = [r for r in counts if int(r.get('t', 0)) > 0]
    registry = build_parameter_registry(ref_model)
    if len(changed) <= 1:
        raise RuntimeError(
            'TinyBERT replacement corruption is concentrated in <=1 ECMC tensor. '
            'Delete stale corruption checkpoints and regenerate with distributed v2 corruption.'
        )
    total_p = sum(int(r.get('P', 0)) for r in counts)
    total_t = sum(int(r.get('t', 0)) for r in counts)
    frac = total_t / max(total_p, 1)
    target = 1.0 / float(denom)
    # Rounding/quantization can move the exact changed fraction slightly, but
    # a grossly sparse checkpoint (the old bug) must be rejected.
    if frac < 0.25 * target:
        raise RuntimeError(
            f'TinyBERT replacement corruption too sparse: changed fraction={frac:.6f}, '
            f'expected order of {target:.6f}.'
        )
    print(
        f'[preflight] TinyBERT replacement corruption: PASS | '
        f'changed ECMC tensors={len(changed)}/{len(registry)}, changed fraction={frac:.6f}'
    )
    return counts


def v87_result5_replacement_ecmc(ref_model):
    _result_banner(
        'RESULT 5 — VERIFICATION-AWARE REPLACEMENT AND ECMC CONTINUITY',
        'Replacement is treated as a protocol-level attack; exact theory, selector Monte Carlo, audits, latency, escape, and coverage gaps are all reported.'
    )
    tampered = load_model(CORRUPT_100)
    _tinybert_replacement_corruption_audit(ref_model, tampered, denom=100)
    exact_pd, _ = ecmc_exact_single_request_detection_probability(
        ref_model, tampered, ECMC_M_OPERATORS, ECMC_K_VALUES
    )
    mc = ecmc_selector_monte_carlo(
        ref_model, tampered, trials=V87_SELECTOR_TRIALS,
        m=ECMC_M_OPERATORS, k=ECMC_K_VALUES, seed=SEED+8700
    )
    trials = _v87_replacement_detailed(
        ref_model, tampered, SEED+8710, V87_REPLACEMENT_TRIALS,
        V87_REPLACEMENT_MAX_SLOTS
    )
    save_table(trials, 'result5a_replacement_trials.csv')

    checkpoints = [x for x in (1,5,10,20,25,50,100) if x <= V87_REPLACEMENT_MAX_SLOTS]
    theory = ecmc_detection_curve_theory(exact_pd, ECMC_AUDIT_PROB, V87_REPLACEMENT_MAX_SLOTS)
    curve = []
    for r in checkpoints:
        hits = int(sum(pd.notna(x) and int(x) <= r for x in trials['DetectedSlot']))
        gaps = int(sum(pd.notna(x) and int(x) <= r for x in trials['CoverageGapSlot']))
        n = len(trials)
        emp = hits/n
        lo, hi = wilson_interval(hits,n)
        th = theory[r]
        curve.append({
            'Slots': r, 'Trials': n, 'Detected': hits, 'CoverageGapsBySlot': gaps,
            'EmpiricalDetection': emp, 'EscapeProbability': 1-emp,
            'CI_low': lo, 'CI_high': hi,
            'ExactSingleRequest_p_d': exact_pd,
            'ConfiguredAuditProbability': ECMC_AUDIT_PROB,
            'TheoryDetection': th,
            'AbsoluteTheoryError': abs(emp-th),
            'TheoryInside95CI': lo <= th <= hi,
        })
    curve_df = pd.DataFrame(curve)
    save_table(curve_df, 'result5b_replacement_curve.csv')

    detected = [int(x) for x in trials['DetectedSlot'].dropna().tolist()]
    total_audits = int(trials['Audits'].sum())
    total_slots = int(trials['EligibleSlots'].sum())
    summary = pd.DataFrame([{
        'Trials': len(trials),
        'DetectedByHorizon': len(detected),
        'DetectionRateByHorizon': len(detected)/len(trials),
        'UndetectedCensoredRate': float(((trials['DetectedSlot'].isna()) & (trials['CoverageGapSlot'].isna())).mean()),
        'CoverageGapRate': float(trials['CoverageGapSlot'].notna().mean()),
        'MeanDetectionSlotDetectedOnly': float(np.mean(detected)) if detected else np.nan,
        'MedianDetectionSlotDetectedOnly': float(np.median(detected)) if detected else np.nan,
        'P95DetectionSlotDetectedOnly': float(np.percentile(detected,95)) if detected else np.nan,
        'ConfiguredAuditProbability': ECMC_AUDIT_PROB,
        'ObservedAuditRate': total_audits/max(1,total_slots),
        'ExactSingleRequest_p_d': exact_pd,
        'SelectorMonteCarlo_p_d': mc['rate'],
        'SelectorCI_low': mc['CI_low'], 'SelectorCI_high': mc['CI_high'],
        'ExactTheoryInsideSelector95CI': mc['CI_low'] <= exact_pd <= mc['CI_high'],
    }])
    save_table(summary, 'result5c_replacement_summary.csv')

    # Continuity record manipulation attacks, plus an explicit coverage-gap test.
    cloud, edge, _ = _make_ecmc_pair(ref_model, load_model(CLEAN_PATH), 'v87-chain', seed_material='v87-chain')
    for i in range(min(6, ECMC_WINDOW)):
        edge.infer(SAMPLE_POOL[i % len(SAMPLE_POOL)])
    clean = copy.deepcopy(edge.records)
    attacks = []
    dup = copy.deepcopy(clean); dup.insert(3, copy.deepcopy(dup[2])); attacks.append(('Duplicate record', dup))
    reorder = copy.deepcopy(clean); reorder[2], reorder[3] = reorder[3], reorder[2]; attacks.append(('Record reordering', reorder))
    delete = copy.deepcopy(clean); del delete[2]; attacks.append(('Record deletion', delete))
    rollback = copy.deepcopy(clean); rollback[-1] = copy.deepcopy(clean[-2]); attacks.append(('Rollback', rollback))
    cross = copy.deepcopy(clean); cross[2]['epoch'] = int(cross[2]['epoch']) - 1; attacks.append(('Cross-epoch replay', cross))
    chain_rows = []
    for name, recs in attacks:
        a = cloud.audit(recs, start_chain=cloud.anchor, start_counter=0)
        chain_rows.append({'Attack':name,'Result':a['result'],'Detected':a['result']=='FAIL','Reason':a['reason']})

    cloud2, edge2, _ = _make_ecmc_pair(ref_model, load_model(CLEAN_PATH), 'v87-gap', seed_material='v87-gap')
    for i in range(ECMC_WINDOW + 3):
        edge2.infer(SAMPLE_POOL[i % len(SAMPLE_POOL)])
    gap = cloud2.audit_retained(edge2.records)
    chain_rows.append({'Attack':'Expired retained-window request','Result':gap['result'],
                       'Detected':gap['result']=='COVERAGE_GAP','Reason':gap['reason']})
    chain_df = pd.DataFrame(chain_rows)
    save_table(chain_df, 'result5d_continuity_record_attacks.csv')

    print(summary.to_string(index=False))
    print('\nReplacement curve:')
    print(curve_df.to_string(index=False))
    print('\nContinuity record attacks:')
    print(chain_df.to_string(index=False))
    return {'trials':trials,'curve':curve_df,'summary':summary,'chain':chain_df}

# ---------------- RESULT 6: paired channel ablation -----------------------
def v87_result6_channel_ablation(primary_trials):
    _result_banner(
        'RESULT 6 — PAIRED CHANNEL ABLATION',
        'The same attack trials are reinterpreted with structural or behavioral evidence removed; paired bootstrap CIs and exact McNemar tests are reported.'
    )
    attack = primary_trials[primary_trials['Ground']=='attack']
    rows=[]
    for scenario,g in attack.groupby('Scenario',sort=False):
        s=g['StructuralDetect'].astype(bool).to_numpy()
        b=g['BehavioralDetect'].astype(bool).to_numpy()
        full=np.logical_or(s,b)
        for removed, without in [('Structural channel',b),('Behavioral channel',s)]:
            diffs=full.astype(float)-without.astype(float)
            lo,hi=_v87_bootstrap_mean_ci(diffs, seed=SEED+len(rows)+1)
            p,n10,n01=_v87_mcnemar_exact_p(full,without)
            rows.append({
                'Scenario':scenario,'Removed':removed,'Trials':len(g),
                'DetectionFull':float(full.mean()),
                'DetectionWithout':float(without.mean()),
                'DetectionDrop':float(diffs.mean()),
                'Drop_CI_low':lo,'Drop_CI_high':hi,
                'Discordant_FullOnly':n10,'Discordant_WithoutOnly':n01,
                'McNemarExact_p':p,
            })
    out=pd.DataFrame(rows)
    save_table(out,'result6_channel_ablation.csv')
    print(out.to_string(index=False))
    return out

# -------- RESULT 7: non-adversarial robustness + boundary stress ----------
def v87_result7_nonadversarial_and_boundary(ref_model):
    _result_banner(
        'RESULT 7 — NON-ADVERSARIAL ROBUSTNESS AND OUT-OF-SCOPE STRESS CASE',
        'Accidental parameter corruption is not an adversarial threat; exact/internal reparameterization is reported separately as a boundary case.'
    )
    rows=[]
    for label,path in [
        ('Accidental parameter corruption 1/10000',CORRUPT_10K),
        ('Accidental parameter corruption 1/1000',CORRUPT_1K),
        ('Accidental parameter corruption 1/100',CORRUPT_100),
    ]:
        model=load_model(path); prof,nid=_v87_profile_node(path)
        detections=[]; invalid=[]
        for r in range(V87_SECURITY_ROUNDS):
            rec=_v87_trial(ref_model,model,prof,nid,label,r,experiment='v87-nonadversarial')
            detections.append(rec['CombinedDetect']); invalid.append(not rec['StructValid'])
        hits=int(sum(detections)); lo,hi=wilson_interval(hits,len(detections))
        rows.append({
            'Case':label,'Category':'Non-adversarial integrity change','Trials':len(detections),
            'IntegrityChangeDetectionRate':hits/len(detections),'CI_low':lo,'CI_high':hi,
            'InvalidEvidenceRate':float(np.mean(invalid)),
            'Interpretation':'True integrity change detection; not a false positive.'
        })

    # Clean repeatability is the actual false-rejection/noise-stability proxy.
    clean_prof,clean_nid=_v87_profile_node(CLEAN_PATH)
    clean_model=load_model(CLEAN_PATH); clean_rej=[]
    for r in range(V87_SECURITY_ROUNDS):
        rec=_v87_trial(ref_model,clean_model,clean_prof,clean_nid,'Clean repeatability',r,experiment='v87-benign-repeat')
        clean_rej.append(rec['CombinedDetect'])
    h=int(sum(clean_rej)); lo,hi=wilson_interval(h,len(clean_rej))
    rows.append({
        'Case':'Clean repeated execution','Category':'Benign repeatability','Trials':len(clean_rej),
        'IntegrityChangeDetectionRate':h/len(clean_rej),'CI_low':lo,'CI_high':hi,
        'InvalidEvidenceRate':0.0,
        'Interpretation':'This rate is FRR; it is the relevant false-positive/false-rejection robustness metric.'
    })
    robust_df=pd.DataFrame(rows)
    save_table(robust_df,'result7a_nonadversarial_robustness.csv')

    stress_model=load_model(OUTPUTPRES_PATH)
    prof,nid=_v87_profile_node(OUTPUTPRES_PATH)
    stress=[]
    stress_label='Internal representation / function-preserving stress case'
    forced = CANDIDATE_LAYERS[0] if CANDIDATE_LAYERS[0] in CANDIDATE_LAYERS else None
    for r in range(V87_SECURITY_ROUNDS):
        stress.append(_v87_trial(ref_model,stress_model,prof,nid,stress_label,r,
                                 experiment='v87-boundary-stress',forced_layer=forced))
    s=pd.DataFrame(stress)
    stress_summary=pd.DataFrame([{
        'Case':stress_label,'Scope':'OUT_OF_SCOPE_STRESS','Trials':len(s),
        'StructuralDetection':float(s['StructuralDetect'].mean()),
        'BehavioralDetection':float(s['BehavioralDetect'].mean()),
        'CombinedDetection':float(s['CombinedDetect'].mean()),
        'EZFailure':float((~s['EZPass']).mean()),
        'EDFailure':float((~s['EDPass']).mean()),
        'EMFailure':float((~s['EMPass']).mean()),
    }])
    save_table(s,'result7b_boundary_stress_trials.csv')
    save_table(stress_summary,'result7c_boundary_stress_summary.csv')
    print(robust_df.to_string(index=False))
    print('\nBoundary stress case:')
    print(stress_summary.to_string(index=False))
    return robust_df, stress_summary

# ---------------- RESULT 8: performance + resource completeness -----------
def _v87_dual_model_cost(ref_model):
    model2=load_model(CLEAN_PATH).eval()
    xlist=[SAMPLE_POOL[i%len(SAMPLE_POOL)] for i in range(V87_DUAL_TIMING_WARMUP+V87_DUAL_TIMING_ITERS)]
    def t_single(x):
        t=time.perf_counter()
        with torch.no_grad(): _v87_forward(ref_model,x)
        return (time.perf_counter()-t)*1000
    def t_dual(x):
        t=time.perf_counter()
        with torch.no_grad():
            _v87_forward(ref_model,x); _v87_forward(model2,x)
        return (time.perf_counter()-t)*1000
    for x in xlist[:V87_DUAL_TIMING_WARMUP]:
        t_single(x); t_dual(x)
    single=[];dual=[]
    for x in xlist[V87_DUAL_TIMING_WARMUP:]:
        single.append(t_single(x)); dual.append(t_dual(x))
    s=float(np.mean(single)); d=float(np.mean(dual))
    one_bytes=_v87_model_bytes(ref_model); two_bytes=one_bytes+_v87_model_bytes(model2)
    return pd.DataFrame([{
        'SingleModelBytes':one_bytes,'TwoResidentModelsBytes':two_bytes,
        'ResidentMemoryMultiplier_model_state':two_bytes/max(1,one_bytes),
        'SingleForwardMean_ms':s,'SequentialDualForwardMean_ms':d,
        'DualExecutionLatencyMultiplier':d/max(1e-12,s),
        'SingleThroughput_ops_s':1000/s,'DualSequentialThroughput_pairs_s':1000/d,
        'Interpretation':'Two resident copies impose model-state memory cost; executing both per request imposes additional computation. This is an operational cost, not a cryptographic guarantee.'
    }])


def v87_result8_performance_resources(ref_model, clean_profile):
    _result_banner(
        'RESULT 8 — PERFORMANCE, COMMUNICATION, MEMORY, AND DUAL-MODEL ATTACKER COST',
        'Uses the paired alternating-order baseline/ECMC timing already implemented by the v8.5+ benchmark.'
    )
    perf,periodic,resources = result8_performance(ref_model,clean_profile)
    # Representative proof communication size.
    prof,nid=_v87_profile_node(CLEAN_PATH)
    rec_ch=_v87_prepare_informative_challenge(
        ref_model,'resources','proof-size',0,node_id=nid
    )
    proof=explicit_proof(ref_model,rec_ch['x'],rec_ch['layer'],rec_ch['alpha'],rec_ch['delta'],
                         nid,rec_ch['nonce'],1,b'R'*32)
    comm=pd.DataFrame([{
        'ExplicitProofBytes_estimatedWire':_v87_proof_size_bytes(proof),
        'ECMCChainHeadBytes':32,'ECMCNonceBytes':32,
        'ApproxECMCRecordBytes':80,
        'WindowRecords':ECMC_WINDOW,
        'ApproxWindowBytes':80*ECMC_WINDOW,
        'BytesPer1000NormalRequests_if_head_only_each_request':32*1000,
    }])
    save_table(comm,'result8f_communication_complete.csv')
    dual=_v87_dual_model_cost(ref_model)
    save_table(dual,'result8g_dual_model_attacker_cost.csv')
    print('\n8F — Communication')
    print(comm.to_string(index=False))
    print('\n8G — Dual-model attacker resource cost')
    print(dual.to_string(index=False))
    return {'performance':perf,'periodic':periodic,'resources':resources,'communication':comm,'dual_model_cost':dual}

