# ---------------- RESULT 10: cross-seed robustness -----------------------
def v87_result10_cross_seed(ref_model):
    _result_banner(
        'RESULT 10 — CROSS-SEED ROBUSTNESS OF PRIMARY SECURITY CLAIMS',
        'No out-of-scope channel-permutation case is used as a headline robustness claim.'
    )
    scenarios=[
        ('Architecture substitution',CLEAN_PATH,True),
        ('Post-deployment backdoor insertion',BACKDOOR_PATH,False),
        ('Unauthorized fine-tuning',FINETUNE_PATH,False),
        ('Early-layer tamper',EARLYMOD_PATH,False),
        ('Output bias',BIAS_PATH,False),
        ('Logit scaling',SCALE_PATH,False),
    ]
    rows=[]
    for seed in ROBUSTNESS_SEEDS:
        for label,path,is_arch in scenarios:
            model=_v87_attack_model(path,is_arch); prof,nid=_v87_profile_node(path)
            forced=_v87_arch_layer() if is_arch else None
            hits=0
            for r in range(V87_ROBUSTNESS_ROUNDS):
                # seed is folded into experiment label so challenge stream is independent.
                rec=_v87_trial(ref_model,model,prof,nid,label,r,
                               experiment=f'v87-robust-seed-{seed}',forced_layer=forced)
                hits+=int(rec['CombinedDetect'])
            rows.append({'Seed':seed,'Scenario':label,'Trials':V87_ROBUSTNESS_ROUNDS,
                         'Hits':hits,'DetectionRate':hits/V87_ROBUSTNESS_ROUNDS})
    seed_df=pd.DataFrame(rows)
    save_table(seed_df,'result10a_primary_cross_seed.csv')
    agg=[]
    for scenario,g in seed_df.groupby('Scenario',sort=False):
        total=int(g['Hits'].sum()); n=int(g['Trials'].sum()); lo,hi=wilson_interval(total,n)
        agg.append({'Scenario':scenario,'Seeds':len(g),'TotalTrials':n,
                    'AggregateRate':total/n,'SeedMean':float(g['DetectionRate'].mean()),
                    'SeedSD':float(g['DetectionRate'].std(ddof=1)) if len(g)>1 else 0.0,
                    'SeedMin':float(g['DetectionRate'].min()),'SeedMax':float(g['DetectionRate'].max()),
                    'CI_low':lo,'CI_high':hi})
    agg_df=pd.DataFrame(agg)
    save_table(agg_df,'result10b_primary_cross_seed_aggregate.csv')
    print(agg_df.to_string(index=False))
    return seed_df,agg_df

