        'v8.8 implementation alignment:',
        '- Canonical runtime sequence G uses only stable operator ID/type/attributes/shapes.',
        '- Allocator-derived predecessor hints are excluded from acceptance and proof binding.',
        '- G is exact-matched; numeric distance applies only to participation pattern P.',
        '- Trusted enrollment aborts on clean canonical-sequence mismatch.',
        '- alpha_L and all thresholds are frozen during trusted enrollment.',
        '- Explicit proof binds node/model/nonce/counter/layer/input digest/structural evidence/z/Delta-z.',
