# ============================================================================
# PAPER REPORTING LAYER
# Displays every paper-facing table/figure in Colab and saves identical
# artifacts to Google Drive. This layer does not alter any experiment result.
# ============================================================================

def _paper_display_table(title, df, filename=None):
    """Show a complete paper-facing table in Colab and optionally save CSV."""
    if df is None:
        return
    if not isinstance(df, pd.DataFrame):
        try:
            df = pd.DataFrame(df)
        except Exception:
            return
    print('\n' + '='*78)
    print(title)
    print('='*78)
    try:
        from IPython.display import display
        display(df)
    except Exception:
        print(df.to_string(index=False))
    if filename:
        save_table(df, filename)


def _paper_save_show_figure(fig, stem):
    """Save publication-ready PNG/PDF to Drive and render inline in Colab."""
    PLOT_DIR.mkdir(parents=True, exist_ok=True)
    png = PLOT_DIR / f'{stem}.png'
    pdf = PLOT_DIR / f'{stem}.pdf'
    fig.tight_layout()
    fig.savefig(png, dpi=300, bbox_inches='tight')
    fig.savefig(pdf, bbox_inches='tight')
    print(f'  [Drive] Figure saved: {png}')
    print(f'  [Drive] Figure saved: {pdf}')
    try:
        plt.show()
    finally:
        plt.close(fig)
    return png, pdf


def _paper_plot_eq1(eq1):
    d=eq1.copy()
    d['PaperRate']=np.where(d['Ground'].eq('clean'), d['ComplementaryRate'], d['Rate']) if 'Ground' in d else d['Rate']
    d['PaperMetric']=np.where(d['Ground'].eq('clean'), 'FRR', 'ADR') if 'Ground' in d else d['Metric']
    fig,ax=plt.subplots(figsize=(10,5.2))
    labels=[str(x).replace('Post-deployment ','').replace('Unauthorized ','Unauth. ') for x in d['Scenario']]
    vals=100*d['PaperRate'].astype(float)
    ax.barh(range(len(d)), vals)
    ax.set_yticks(range(len(d))); ax.set_yticklabels(labels)
    ax.set_xlabel('Rate (%)'); ax.set_title('EQ1: Model integrity detection and clean rejection')
    ax.set_xlim(0,105); ax.invert_yaxis(); ax.grid(axis='x',alpha=.25)
    for i,v in enumerate(vals): ax.text(min(v+1,101),i,f'{v:.1f}%',va='center',fontsize=8)
    return _paper_save_show_figure(fig,'paper_EQ1_ADR_FRR')


def _paper_plot_eq2(eq2):
    d=eq2.copy(); y=np.arange(len(d)); h=.25
    fig,ax=plt.subplots(figsize=(11,5.8))
    ax.barh(y-h,100*d['StructuralDetection'],height=h,label='Structural')
    ax.barh(y,100*d['BehavioralDetection'],height=h,label='Behavioral')
    ax.barh(y+h,100*d['CombinedDetection'],height=h,label='Combined')
    ax.set_yticks(y); ax.set_yticklabels([str(x).replace('Function-preserving structural substitution (FPSS)','FPSS (controlled)') for x in d['Scenario']])
    ax.set_xlabel('Detection rate (%)'); ax.set_title('EQ2: Structural and behavioral evidence complementarity')
    ax.set_xlim(0,105); ax.invert_yaxis(); ax.legend(); ax.grid(axis='x',alpha=.25)
    return _paper_save_show_figure(fig,'paper_EQ2_complementarity')


def _paper_plot_eq3_protocol(protocol):
    d=protocol.copy(); vals=100*d['PASR'].astype(float)
    fig,ax=plt.subplots(figsize=(10,4.8))
    ax.barh(range(len(d)),vals)
    ax.set_yticks(range(len(d))); ax.set_yticklabels(d['Attack'])
    ax.set_xlabel('PASR (%)'); ax.set_title('EQ3: Verification-protocol and communication attacks')
    ax.set_xlim(0,max(5,float(vals.max())*1.15 if len(vals) else 5)); ax.invert_yaxis(); ax.grid(axis='x',alpha=.25)
    for i,v in enumerate(vals): ax.text(v+0.1,i,f'{v:.1f}%',va='center',fontsize=8)
    return _paper_save_show_figure(fig,'paper_EQ3_protocol_PASR')


def _paper_plot_replacement(curve):
    d=curve.copy(); fig,ax=plt.subplots(figsize=(7.6,4.8))
    ax.plot(d['Slots'],100*d['EmpiricalDetection'],marker='o',label='Empirical')
    ax.plot(d['Slots'],100*d['TheoryDetection'],marker='s',label='Theoretical')
    if {'CI_low','CI_high'}.issubset(d.columns):
        ax.fill_between(d['Slots'].astype(float).to_numpy(),100*d['CI_low'].astype(float).to_numpy(),100*d['CI_high'].astype(float).to_numpy(),alpha=.15,label='95% CI')
    ax.set_xlabel('Ordinary inference slots'); ax.set_ylabel('Detection probability (%)')
    ax.set_title('EQ3: ECMC replacement detection horizon'); ax.set_ylim(0,105); ax.legend(); ax.grid(alpha=.25)
    return _paper_save_show_figure(fig,'paper_EQ3_ECMC_replacement_curve')


def _paper_plot_eq4_latency(perf):
    d=perf.copy(); vals=d['mean_ms'].astype(float)
    fig,ax=plt.subplots(figsize=(9,4.8))
    ax.barh(range(len(d)),vals)
    ax.set_yticks(range(len(d))); ax.set_yticklabels(d['Condition'])
    ax.set_xlabel('Mean latency (ms)'); ax.set_title('EQ4: Inference and explicit-verification latency')
    ax.invert_yaxis(); ax.grid(axis='x',alpha=.25)
    for i,v in enumerate(vals): ax.text(v+max(vals)*.01,i,f'{v:.2f}',va='center',fontsize=8)
    return _paper_save_show_figure(fig,'paper_EQ4_latency')


def _paper_plot_periodic(periodic):
    d=periodic.copy(); fig,ax=plt.subplots(figsize=(7.6,4.6))
    ax.plot(d['R_normal_per_EV'],d['Overhead_vs_unprotected_normal_pct'],marker='o')
    ax.set_xscale('log'); ax.set_xlabel('Normal inferences per explicit verification (R)')
    ax.set_ylabel('Amortized overhead (%)'); ax.set_title('EQ4: Periodic verification overhead')
    ax.grid(alpha=.25)
    return _paper_save_show_figure(fig,'paper_EQ4_periodic_overhead')


def generate_paper_reporting_outputs(results):
    """Create the complete paper-facing Colab/Drive reporting package.

    Every table is displayed inline and saved as CSV. Every core figure is
    displayed inline and saved as both 300-dpi PNG and vector PDF.
    """
    print('\n'+'#'*78)
    print('PAPER REPORTING OUTPUTS — TABLES AND FIGURES')
    print('#'*78)

    # Persistent protocol lifecycle
    if isinstance(results.get('Lifecycle'), dict):
        _paper_display_table('Table: Persistent node lifecycle — phase execution',
                             results['Lifecycle'].get('phases'),
                             'PAPER_TABLE_node_lifecycle_phases.csv')
        _paper_display_table('Table: Persistent node lifecycle — final state',
                             results['Lifecycle'].get('states'),
                             'PAPER_TABLE_node_lifecycle_state.csv')

    # Experimental setup
    setup = results['EQ4']['node_setup']
    _paper_display_table('Table: Experimental setup — nine heterogeneous edge nodes', setup,
                         'PAPER_TABLE_experimental_setup.csv')

    # EQ1
    eq1=results['EQ1']
    _paper_display_table('Table: EQ1 — Model integrity ADR and clean FRR',eq1,
                         'PAPER_TABLE_EQ1_ADR_FRR.csv')
    _paper_plot_eq1(eq1)

    # EQ2, including the controlled FPSS witness
    eq2=results['EQ2']
    _paper_display_table('Table: EQ2 — Evidence complementarity',eq2,
                         'PAPER_TABLE_EQ2_complementarity.csv')
    _paper_plot_eq2(eq2)

    fpss_path=RESULT_DIR/'EQ2_FPSS_witness_summary.csv'
    if fpss_path.exists():
        _paper_display_table('Table: EQ2 — FPSS structural-only witness',pd.read_csv(fpss_path),
                             'PAPER_TABLE_EQ2_FPSS_witness.csv')

    # EQ3 protocol + continuity + replacement
    eq3=results['EQ3']; protocol=eq3['protocol']; rep=eq3['replacement']
    _paper_display_table('Table: EQ3 — Protocol and communication attack PASR',protocol,
                         'PAPER_TABLE_EQ3_protocol_PASR.csv')
    _paper_plot_eq3_protocol(protocol)
    if isinstance(rep,dict):
        _paper_display_table('Table: EQ3 — ECMC replacement summary',rep.get('summary'),
                             'PAPER_TABLE_EQ3_replacement_summary.csv')
        _paper_display_table('Table: EQ3 — ECMC detection horizon and theory comparison',rep.get('curve'),
                             'PAPER_TABLE_EQ3_replacement_curve.csv')
        _paper_display_table('Table: EQ3 — Continuity manipulation results',rep.get('chain'),
                             'PAPER_TABLE_EQ3_continuity_attacks.csv')
        if isinstance(rep.get('curve'),pd.DataFrame): _paper_plot_replacement(rep['curve'])

    # EQ4 measured performance, communication, storage, and heterogeneous nodes
    eq4=results['EQ4']; raw=eq4['measured']
    if isinstance(raw,dict):
        _paper_display_table('Table: EQ4 — Measured latency and throughput',raw.get('performance'),
                             'PAPER_TABLE_EQ4_performance.csv')
        _paper_display_table('Table: EQ4 — Periodic verification overhead',raw.get('periodic'),
                             'PAPER_TABLE_EQ4_periodic_overhead.csv')
        _paper_display_table('Table: EQ4 — Continuity storage',raw.get('resources'),
                             'PAPER_TABLE_EQ4_storage.csv')
        _paper_display_table('Table: EQ4 — Communication/proof size',raw.get('communication'),
                             'PAPER_TABLE_EQ4_communication.csv')
        if isinstance(raw.get('performance'),pd.DataFrame): _paper_plot_eq4_latency(raw['performance'])
        if isinstance(raw.get('periodic'),pd.DataFrame): _paper_plot_periodic(raw['periodic'])
    _paper_display_table('Table: EQ4 — Network/resource-profile projection',eq4['network_projection'],
                         'PAPER_TABLE_EQ4_network_profiles.csv')

    # Index all reporting artifacts so a Colab run has one definitive checklist.
    table_files=sorted(x.name for x in RESULT_DIR.glob('PAPER_TABLE_*.csv'))
    figure_files=sorted(x.name for x in PLOT_DIR.glob('paper_EQ*.*'))
    index=pd.DataFrame(
        [{'ArtifactType':'Table','File':x,'DriveDirectory':str(RESULT_DIR)} for x in table_files] +
        [{'ArtifactType':'Figure','File':x,'DriveDirectory':str(PLOT_DIR)} for x in figure_files]
    )
    save_table(index,'PAPER_REPORTING_ARTIFACT_INDEX.csv')
    _paper_display_table('Paper reporting artifact index',index)
    print('\nAll paper-facing tables were displayed above and saved to Google Drive.')
    print(f'Tables/results: {RESULT_DIR}')
    print(f'Figures (PNG + PDF): {PLOT_DIR}')
    return index




# =====================================================================
# PAPER LIFECYCLE ORCHESTRATION — persistent nine-node deployment state
# =====================================================================
@dataclass
class PaperEdgeNodeState:
    """Persistent state for one logical edge deployment in the paper setup."""
    node_id: str
    assigned_model_path: object
    resource_profile: object
    integrity_profile: object
    enrolled: bool = False
    deployment_model: object = None
    explicit_counter: int = 0
    last_explicit_result: object = None
    last_proof: object = None
    verified_anchor: object = None
    epoch: int = 0
    epoch_seed: object = None
    ecmc_edge: object = None
    ecmc_cloud: object = None
    last_audit: object = None

    def phase_row(self, phase, status, **kw):
        row = {
            'Node': self.node_id,
            'Profile': self.resource_profile.name,
            'Phase': phase,
            'Status': status,
            'AssignedModel': Path(self.assigned_model_path).name,
        }
        row.update(kw)
        return row


_PAPER_NODES = {}


def build_persistent_paper_nodes():
    """Build the nine persistent node objects after trusted enrollment.

    Each enrollment profile was independently produced and frozen by
    enroll_all_nodes(). This function binds those node-specific profiles to
    the paper resource classes and to the model assigned after a verified
    clean anchor exists.
    """
    global _PAPER_NODES
    if not _NODE_RESOURCE_PROFILE:
        assign_paper_node_profiles()
    nodes = {}
    for nid in sorted(_NODE_IDS):
        nodes[nid] = PaperEdgeNodeState(
            node_id=nid,
            assigned_model_path=_NODE_POOL[nid],
            resource_profile=_NODE_RESOURCE_PROFILE[nid],
            integrity_profile=_INTEGRITY_PROFILES[nid],
            enrolled=True,
        )
    _PAPER_NODES = nodes
    return nodes


def _paper_phase_explicit_and_anchor(ref_model, node, phase_rows):
    """Run a real explicit verification on the enrolled clean model and anchor it."""
    print(f'\n[{node.node_id}] PHASE 2 — EXPLICIT VERIFICATION')
    clean_edge = load_model(CLEAN_PATH)
    node.explicit_counter += 1
    ch = _v87_prepare_informative_challenge(
        ref_model, 'paper-lifecycle', node.node_id, node.explicit_counter, node_id=node.node_id
    )
    key = b'L' * 32
    proof = explicit_proof(
        clean_edge, ch['x'], ch['layer'], ch['alpha'], ch['delta'],
        node.node_id, ch['nonce'], node.explicit_counter, key
    )
    vr = verify_explicit(
        ref_model, proof, ch['x'], ch['layer'], ch['alpha'], ch['delta'],
        node.node_id, ch['nonce'], node.explicit_counter, key,
        node.integrity_profile
    )
    node.last_explicit_result, node.last_proof = vr, proof
    print('  E_A={} E_G={} E_P={} E_Z={} E_D={} E_M={}  PASS_EV={}'.format(
        int(bool(vr.get('auth'))), int(bool(vr.get('eg'))), int(bool(vr.get('ep'))),
        int(bool(vr.get('ez'))), int(bool(vr.get('ed'))), int(bool(vr.get('em'))),
        int(bool(vr.get('pass')))))
    phase_rows.append(node.phase_row(
        'Explicit verification', 'PASS' if vr.get('pass') else 'FAIL',
        EA=bool(vr.get('auth')), EG=bool(vr.get('eg')), EP=bool(vr.get('ep')),
        EZ=bool(vr.get('ez')), ED=bool(vr.get('ed')), EM=bool(vr.get('em')),
        PASS_EV=bool(vr.get('pass')), Layer=ch['layer'],
        ProofBytes=_v87_proof_size_bytes(proof)
    ))
    if not vr.get('pass'):
        raise RuntimeError(f'{node.node_id}: lifecycle cannot enter ECMC without PASS_EV')

    print(f'[{node.node_id}] PHASE 3 — VERIFIED ANCHOR + ECMC EPOCH')
    previous_chain = sha256_bytes(b'PAPER-LIFECYCLE-PREV|' + node.node_id.encode())
    anchor = make_verified_anchor(
        previous_chain, node.node_id, get_enrolled_model_id(), ch['nonce'], vr,
        proof=proof
    )
    node.verified_anchor = anchor
    node.epoch = 1
    node.epoch_seed = hashlib.sha256(
        b'PAPER-ECMC-EPOCH|' + node.node_id.encode() + anchor
    ).digest()
    # The same verified anchor initializes both sides of this node's epoch.
    node.ecmc_cloud = ECMCCloudVerifier(
        ref_model, node.node_id, get_enrolled_model_id(), epoch=node.epoch,
        epoch_seed=node.epoch_seed, initial_chain=anchor
    )
    # Model assignment occurs only now, after clean enrollment + PASS_EV + anchor.
    node.deployment_model = load_model(node.assigned_model_path)
    node.ecmc_edge = ECMCEdgeState(
        node.deployment_model, node.node_id, get_enrolled_model_id(),
        epoch=node.epoch, epoch_seed=node.epoch_seed, initial_chain=anchor
    )
    print(f'  Anchor={anchor.hex()[:16]}...  epoch={node.epoch}')
    print(f'  Deployment model assigned: {Path(node.assigned_model_path).name}')
    phase_rows.append(node.phase_row(
        'Verified anchor / ECMC epoch', 'INITIALIZED', PASS_EV=True,
        Epoch=node.epoch, AnchorPrefix=anchor.hex()[:16]
    ))


def run_persistent_node_lifecycle(ref_model, ordinary_requests=3):
    """Execute and report the paper protocol lifecycle for all nine nodes.

    This is deliberately separate from aggregate EQ trial loops.  It validates
    that the implementation can execute the methodology in causal order on
    persistent node state: enrollment -> explicit PASS -> anchor -> ECMC epoch
    -> ordinary inference -> retained-record audit.  Tampered deployment models
    are assigned only after the clean verified anchor has been established.
    """
    nodes = build_persistent_paper_nodes()
    rows = []
    print('\n' + '='*78)
    print('PHASE 1 — TRUSTED NODE ENROLLMENT (PERSISTENT DEPLOYMENT OBJECTS)')
    print('='*78)
    for node in nodes.values():
        print(f'  {node.node_id:<10} enrolled=True  profile={node.resource_profile.name:<11} '
              f'assignment={Path(node.assigned_model_path).name}')
        rows.append(node.phase_row('Trusted enrollment', 'PASS', Enrolled=True))

    for ni, node in enumerate(nodes.values()):
        _paper_phase_explicit_and_anchor(ref_model, node, rows)
        print(f'[{node.node_id}] PHASE 4 — ORDINARY INFERENCE + ECMC')
        for j in range(int(ordinary_requests)):
            x = SAMPLE_POOL[(ni * int(ordinary_requests) + j) % len(SAMPLE_POOL)]
            _, rec = node.ecmc_edge.infer(x)
            print(f"  request={rec['counter']} record={rec['chain'][:16]}... retained={len(node.ecmc_edge.records)}")
            rows.append(node.phase_row(
                'Ordinary inference / ECMC record', 'RECORDED',
                Epoch=node.epoch, RequestCounter=int(rec['counter']),
                ChainPrefix=rec['chain'][:16], RetainedRecords=len(node.ecmc_edge.records)
            ))

        print(f'[{node.node_id}] PHASE 5 — ECMC AUDIT')
        audit = node.ecmc_cloud.audit_retained(node.ecmc_edge.records)
        node.last_audit = audit
        print(f"  audit={audit.get('result')} reason={audit.get('reason')}")
        rows.append(node.phase_row(
            'ECMC audit', audit.get('result', 'UNKNOWN'), Epoch=node.epoch,
            AuditedThrough=node.ecmc_cloud.trusted_counter,
            AuditReason=audit.get('reason', '')
        ))

    lifecycle = pd.DataFrame(rows)
    save_table(lifecycle, 'PAPER_NODE_LIFECYCLE_PHASES.csv')
    try:
        from IPython.display import display
        print('\nPERSISTENT NODE LIFECYCLE RESULTS')
        display(lifecycle)
    except Exception:
        print(lifecycle.to_string(index=False))

    # Compact node-level state table for the paper/runtime record.
    states = pd.DataFrame([{
        'Node': n.node_id,
        'ResourceProfile': n.resource_profile.name,
        'Enrolled': n.enrolled,
        'ExplicitPASS': bool(n.last_explicit_result and n.last_explicit_result.get('pass')),
        'AnchorCreated': n.verified_anchor is not None,
        'ECMCEpoch': n.epoch,
        'OrdinaryRequests': n.ecmc_edge.counter if n.ecmc_edge else 0,
        'RetainedRecords': len(n.ecmc_edge.records) if n.ecmc_edge else 0,
        'AuditResult': (n.last_audit or {}).get('result', ''),
        'AssignedModel': Path(n.assigned_model_path).name,
    } for n in nodes.values()])
    save_table(states, 'PAPER_NODE_LIFECYCLE_STATE.csv')
    try:
        from IPython.display import display
        display(states)
    except Exception:
        print(states.to_string(index=False))
    return {'phases': lifecycle, 'states': states, 'nodes': nodes}



# =====================================================================
# PAPER TRIAL SCHEDULER — balanced-random coverage across all nine nodes
# =====================================================================
def _paper_balanced_node_schedule(n_trials, scenario, experiment='eq1'):
    """Return a reproducible balanced-random node schedule.

    Every node receives floor(n_trials / n_nodes) trials.  The remainder is
    assigned to reproducibly shuffled nodes, then the complete schedule is
    shuffled.  For 100 trials and 9 nodes this gives 11 trials/node plus one
    additional trial on one node.  This is preferable to unconstrained random
    node selection because it guarantees deployment-wide coverage.
    """
    nodes = sorted(_NODE_IDS)
    if len(nodes) != 9:
        raise RuntimeError(f'Paper trial scheduler requires 9 enrolled nodes; found {len(nodes)}')
    n_trials = int(n_trials)
    if n_trials < len(nodes):
        raise ValueError('Trial count must be at least the number of enrolled nodes')
    seed_bytes = hashlib.sha256(
        f'paper-balanced-nodes|{SEED}|{experiment}|{scenario}|{n_trials}'.encode()
    ).digest()
    rng = random.Random(int.from_bytes(seed_bytes[:8], 'big'))
    q, rem = divmod(n_trials, len(nodes))
    schedule = [nid for nid in nodes for _ in range(q)]
    extras = nodes.copy()
    rng.shuffle(extras)
    schedule.extend(extras[:rem])
    rng.shuffle(schedule)
    counts = {nid: schedule.count(nid) for nid in nodes}
    if max(counts.values()) - min(counts.values()) > 1:
        raise AssertionError(f'Unbalanced node schedule: {counts}')
    return schedule


def _paper_save_trial_coverage(trials, stem='EQ1_trial_coverage'):
    """Save/display node and layer coverage proving how trials were distributed."""
    if trials.empty:
        return pd.DataFrame()
    coverage = (
        trials.groupby(['Scenario','Node','Layer'], sort=False)
              .size().reset_index(name='Trials')
    )
    save_table(coverage, f'{stem}_node_layer.csv')
    node_cov = (
        trials.groupby(['Scenario','Node'], sort=False)
              .agg(Trials=('Trial','size'), UniqueLayers=('Layer','nunique'),
                   UniqueInputs=('InputIndex','nunique'))
              .reset_index()
    )
    save_table(node_cov, f'{stem}_node_summary.csv')
    try:
        from IPython.display import display
        print('\nTRIAL COVERAGE — NODE × LAYER')
        display(coverage)
        print('\nTRIAL COVERAGE — PER NODE')
        display(node_cov)
    except Exception:
        print(coverage.to_string(index=False))
        print(node_cov.to_string(index=False))
    return coverage


def v87_result1_primary_integrity(ref_model):
    """EQ1 trials balanced across all nine independently enrolled nodes.

    For every scenario, each trial first obtains its scheduled node.  The
    informative-challenge generator then reproducibly randomizes the input,
    eligible layer, and nonce for that node.  Verification uses only that
    node-layer's frozen enrollment profile.  No scenario is tied to one node.
    """
    _result_banner(
        'RESULT 1 — PRIMARY THREAT-MODEL MODEL-INTEGRITY EVALUATION',
        '100 trials/scenario: balanced-random across 9 nodes; randomized layer/input/nonce.'
    )
    rows = []
    for label, path, is_arch, ground in _v87_primary_scenarios():
        model = _v87_attack_model(path, is_arch)
        schedule = _paper_balanced_node_schedule(
            V87_SECURITY_ROUNDS, label, experiment='eq1-primary'
        )
        for r, nid in enumerate(schedule):
            prof = profile_for_node(nid)
            # Do not force a layer for architecture substitution: the paper
            # trial design samples an eligible layer from the selected node.
            rec = _v87_trial(
                ref_model, model, prof, nid, label, r,
                experiment='paper-eq1-balanced', forced_layer=None
            )
            rec['Ground'] = ground
            rec['ResourceProfile'] = (
                _NODE_RESOURCE_PROFILE[nid].name if nid in _NODE_RESOURCE_PROFILE else ''
            )
            rows.append(rec)
        counts = pd.Series(schedule).value_counts().sort_index().to_dict()
        print(f'  completed {label}: {V87_SECURITY_ROUNDS} trials across 9 nodes {counts}')

    trials = pd.DataFrame(rows)
    save_table(trials, 'result1_primary_threat_trials.csv')
    _paper_save_trial_coverage(trials, 'EQ1_trial_coverage')

    summary = []
    for scenario, g in trials.groupby('Scenario', sort=False):
        ground = str(g['Ground'].iloc[0]); n = len(g)
        rejects = int(g['CombinedDetect'].sum())
        invalid = int((~g['StructValid'].astype(bool)).sum())
        valid_g = g[g['StructValid'].astype(bool)]
        valid_rejects = int(valid_g['CombinedDetect'].sum())
        lo, hi = wilson_interval(rejects, n)
        if ground == 'clean':
            metric='FRR'; primary_rate=rejects/n; complementary=1.0-primary_rate
        else:
            metric='ADR'; primary_rate=rejects/n; complementary=1.0-primary_rate
        summary.append({
            'Scenario':scenario,'Ground':ground,'Trials':n,
            'NodesCovered':int(g['Node'].nunique()),
            'LayersCovered':int(g['Layer'].nunique()),
            'UniqueInputs':int(g['InputIndex'].nunique()),
            'Metric':metric,'Rate':primary_rate,
            'ComplementaryMetric':'CAR' if ground=='clean' else 'AER',
            'ComplementaryRate':complementary,'CI_low':lo,'CI_high':hi,
            'InvalidEvidence':invalid,'InvalidEvidenceRate':invalid/n,
            'DecidableValidTrials':len(valid_g),
            'RateAmongValidEvidence':valid_rejects/max(1,len(valid_g)),
            'MeanChallengeAttempts':float(g['ChallengeAttempts'].mean()),
            'MaxChallengeAttempts':int(g['ChallengeAttempts'].max()),
            'MeanProofBytes':float(g['ProofBytes'].mean()),
        })
    summary_df=pd.DataFrame(summary)
    save_table(summary_df,'result1_primary_threat_summary.csv')

    # Per-node rates expose whether aggregate ADR/FRR hides a weak node.
    per_node=[]
    for (scenario,nid),g in trials.groupby(['Scenario','Node'],sort=False):
        ground=str(g['Ground'].iloc[0]); rejects=int(g['CombinedDetect'].sum()); n=len(g)
        lo,hi=wilson_interval(rejects,n)
        per_node.append({'Scenario':scenario,'Node':nid,'Ground':ground,'Trials':n,
                         'Metric':'FRR' if ground=='clean' else 'ADR',
                         'Rate':rejects/n,'CI_low':lo,'CI_high':hi,
                         'LayersCovered':int(g['Layer'].nunique()),
                         'UniqueInputs':int(g['InputIndex'].nunique())})
    per_node_df=pd.DataFrame(per_node)
    save_table(per_node_df,'EQ1_per_node_ADR_FRR.csv')
    try:
        from IPython.display import display
        print('\nEQ1 OVERALL SUMMARY'); display(summary_df)
        print('\nEQ1 PER-NODE ADR/FRR'); display(per_node_df)
    except Exception:
        print(summary_df.to_string(index=False)); print(per_node_df.to_string(index=False))
    return trials, summary_df


def _paper_eq2_fpss_trials(ref_model):
    """Controlled FPSS trials with the same 9-node balanced-random design."""
    label='Function-preserving structural substitution (FPSS)'
    model=_v87_make_fpss_model()
    schedule=_paper_balanced_node_schedule(V87_SECURITY_ROUNDS,label,experiment='eq2-fpss')
    rows=[]
    for r,nid in enumerate(schedule):
        prof=profile_for_node(nid)
        rec=_v87_trial(ref_model,model,prof,nid,label,r,
                       experiment='paper-eq2-fpss-balanced',forced_layer=None)
        rec['Ground']='controlled-complementarity'
        rec['EQ2Case']='structural-only witness'
        rec['BehavioralPass']=bool(rec['EZPass'] and rec['EDPass'] and rec['EMPass'])
        rec['WitnessPass']=bool(rec['StructuralDetect'] and not rec['BehavioralDetect'])
        rec['ResourceProfile']=(
            _NODE_RESOURCE_PROFILE[nid].name if nid in _NODE_RESOURCE_PROFILE else ''
        )
        rows.append(rec)
    out=pd.DataFrame(rows)
    save_table(out,'EQ2_FPSS_controlled_trials.csv')
    _paper_save_trial_coverage(out,'EQ2_FPSS_trial_coverage')
    return out


# =====================================================================
# FINAL PATCH: RESULT 5 MUST USE REAL ENROLLED NODE IDS
# =====================================================================
# ECMC trial tags identify an experiment/epoch. They are NOT edge-node IDs.
# Every verified anchor must use one of the nine independently enrolled nodes
# so that challenge alpha and all verification thresholds come from that
# node's own Node x Layer enrollment profile.

def _ecmc_enrolled_node_ids():
    ids = [str(n) for n in _NODE_IDS if str(n) in _INTEGRITY_PROFILES]
    if len(ids) != len(_NODE_IDS):
        missing = [str(n) for n in _NODE_IDS if str(n) not in _INTEGRITY_PROFILES]
        raise RuntimeError(
            'ECMC requires independently enrolled node profiles before Result 5. '
            f'Missing profiles: {missing}'
        )
    return ids


def _make_ecmc_pair(ref_model, edge_model, tag='ecmc', seed_material=None, node_id=None):
    """Create one ECMC epoch bound to a real independently enrolled node.

    `tag` is only an experiment/epoch identifier.  It must never be used as
    the enrollment-profile key.  `node_id` selects the Node x Layer profile
    used by the explicit verification that creates the verified anchor.
    """
    enrolled_nodes = _ecmc_enrolled_node_ids()
    if node_id is None:
        # Deterministic default for non-statistical chain-manipulation helpers.
        node_id = enrolled_nodes[0]
    node_id = str(node_id)
    if node_id not in _INTEGRITY_PROFILES:
        raise KeyError(
            f'ECMC node {node_id!r} has no independently enrolled profile; '
            'synthetic trial tags cannot be used as node IDs.'
        )

    mid = get_enrolled_model_id()
    if seed_material is None:
        epoch_seed = os.urandom(32)
    else:
        epoch_seed = hashlib.sha256(str(seed_material).encode()).digest()

    previous_chain = sha256_bytes(
        b'PREVIOUS-TRUSTED-CHAIN|' + node_id.encode() + b'|' + str(tag).encode()
    )
    anchor, _, _ = establish_verified_anchor(
        ref_model,
        node_id,
        previous_chain,
        challenge_tag=f'{tag}|{seed_material}|anchor'
    )
    cloud = ECMCCloudVerifier(
        ref_model, node_id, mid, epoch=1,
        epoch_seed=epoch_seed, initial_chain=anchor
    )
    edge = ECMCEdgeState(
        edge_model, node_id, mid, epoch=1,
        epoch_seed=epoch_seed, initial_chain=anchor
    )
    return cloud, edge, anchor


def _v87_replacement_detailed(ref_model, tampered_model, seed, trials, max_slots):
    """Replacement trials balanced across all nine enrolled edge nodes."""
    records = []
    node_schedule = _paper_balanced_node_schedule(
        int(trials), 'Verification-aware replacement', experiment=f'eq3-ecmc-{seed}'
    )

    for tr, node_id in enumerate(node_schedule):
        trial_tag = f'v87-rep-{seed}-{tr}'
        cloud, edge, _ = _make_ecmc_pair(
            ref_model,
            tampered_model,
            tag=trial_tag,
            seed_material=f'v87-rep-epoch|{seed}|{tr}|node={node_id}',
            node_id=node_id,
        )
        rng = random.Random(int(seed) * 1000003 + tr)
        detected_slot = None
        gap_slot = None
        audits = 0
        for slot in range(1, int(max_slots) + 1):
            input_index = rng.randrange(len(SAMPLE_POOL))
            edge.infer(SAMPLE_POOL[input_index])
            if rng.random() <= ECMC_AUDIT_PROB:
                audits += 1
                audit = cloud.audit_retained(edge.records)
                if audit['result'] == 'FAIL':
                    detected_slot = slot
                    break
                if audit['result'] == 'COVERAGE_GAP':
                    gap_slot = slot
                    break
        records.append({
            'Trial': tr,
            'Node': node_id,
            'ResourceProfile': (_NODE_RESOURCE_PROFILE[node_id].name if node_id in _NODE_RESOURCE_PROFILE else ''),
            'DetectedSlot': detected_slot,
            'CoverageGapSlot': gap_slot,
            'Audits': audits,
            'EligibleSlots': int(
                max_slots if detected_slot is None and gap_slot is None
                else (detected_slot or gap_slot)
            ),
        })

    out = pd.DataFrame(records)
    # Explicitly expose Result-5 node coverage in Colab and Drive.
    cov = (out.groupby(['Node', 'ResourceProfile'], dropna=False)
             .size().reset_index(name='ReplacementTrials'))
    save_table(cov, 'EQ3_ECMC_replacement_node_coverage.csv')
    print('\nECMC replacement trial coverage across enrolled nodes:')
    print(cov.to_string(index=False))
    return out


