def _tinybert_preflight_audit():
    """Fail fast on model-specific wiring errors before expensive enrollment."""
    required = [
        '_model_forward', 'load_model', 'explicit_proof', 'verify_explicit',
        'run_explicit_trial', '_v87_make_arch_model', '_v87_make_fpss_model',
        '_v87_arch_layer', 'v87_result8_performance_resources',
        'paper_eq1_model_integrity', 'paper_eq2_complementarity',
        'paper_eq3_security_continuity', 'paper_eq4_efficiency',
    ]
    missing = [name for name in required if not callable(globals().get(name))]
    if missing:
        raise RuntimeError(f'TinyBERT preflight: missing required callables: {missing}')
    expected = {'bert', 'classifier'}
    got = set(CANDIDATE_LAYERS)
    if got != expected:
        raise RuntimeError(f'TinyBERT preflight: candidate layers must be {sorted(expected)}, got {CANDIDATE_LAYERS}')
    if _v87_arch_layer() not in got:
        raise RuntimeError(f'TinyBERT preflight: architecture layer {_v87_arch_layer()!r} is not enrolled')
    # Catch known cross-model residue that can cause late runtime failures.
    import inspect as _inspect
    critical = '\n'.join(_inspect.getsource(globals()[n]) for n in [
        'paper_eq1_model_integrity', 'paper_eq2_complementarity',
        'paper_eq3_security_continuity', 'paper_eq4_efficiency',
        'v87_result8_performance_resources'
    ])
    forbidden = ['layer4.1', 'conv1', 'main.3', 'main.6']
    bad = [x for x in forbidden if x in critical]
    if bad:
        raise RuntimeError(f'TinyBERT preflight: cross-model layer residue in active EQ path: {bad}')

    expected_scenarios = [
        'Clean', 'Architecture substitution', 'Post-deployment backdoor insertion',
        'Unauthorized fine-tuning', 'Early-layer tamper', 'Behavioral drift',
        'Output bias', 'Logit scaling', 'Model compression'
    ]
    scenarios = _v87_primary_scenarios()
    names = [row[0] for row in scenarios]
    if names != expected_scenarios:
        raise RuntimeError(f'TinyBERT preflight: EQ1 scenario list mismatch: {names}')
    if len(scenarios) != 9 or sum(1 for x in scenarios if x[3] == 'attack') != 8:
        raise RuntimeError('TinyBERT preflight: expected Clean + exactly 8 primary attacks')
    if not COMPRESSION_PATH.exists():
        raise RuntimeError(f'TinyBERT preflight: compression checkpoint missing: {COMPRESSION_PATH}')
    # Ensure the revised early attack really changes a first-encoder tensor.
    clean_state = torch.load(CLEAN_PATH, map_location='cpu')
    early_state = torch.load(EARLYMOD_PATH, map_location='cpu')
    changed_early = [k for k in clean_state if k in early_state and torch.is_tensor(clean_state[k]) and not torch.equal(clean_state[k], early_state[k])]
    if not any('encoder' in k for k in changed_early):
        raise RuntimeError(f'TinyBERT preflight: early-layer attack does not modify an encoder tensor: {changed_early[:5]}')
    comp_state = torch.load(COMPRESSION_PATH, map_location='cpu')
    changed_comp = sum(int((clean_state[k] != comp_state[k]).sum().item()) for k in clean_state if k in comp_state and torch.is_tensor(clean_state[k]) and torch.is_floating_point(clean_state[k]))
    if changed_comp <= 0:
        raise RuntimeError('TinyBERT preflight: compression checkpoint is numerically identical to M*')
    print(f'  [Preflight] Early tamper changed encoder tensors: {len(changed_early)}')
    print(f'  [Preflight] Compression changed scalar parameters: {changed_comp}')
    print('  [Preflight] TinyBERT/SST-2 active EQ1-EQ4 wiring: PASS (8 attacks registered)')


def paper_aligned_main():
    print("=" * 78)
    print("RQ1 PAPER-ALIGNED FULL EXPERIMENT — TinyBERT / SST-2")
    print("Full nine-node enrollment + explicit verification + verified anchor + ECMC + EQ1-EQ4")
    print("=" * 78)

    mount_google_drive_output()
    init_dataset()
    ensure_attack_models()
    ref = load_model(CLEAN_PATH).to(DEVICE)
    set_enrolled_model_id(ref)
    _tinybert_preflight_audit()
    enroll_all_nodes(ref)
    assign_paper_node_profiles()
    clean_profile = profile_for_scenario(CLEAN_PATH)

    lifecycle = run_persistent_node_lifecycle(ref, ordinary_requests=3)
    results = {"Lifecycle": lifecycle}
    eq1_trials, results["EQ1"] = paper_eq1_model_integrity(ref)
    results["EQ2"] = paper_eq2_complementarity(eq1_trials, ref)
    results["EQ3"] = paper_eq3_security_continuity(ref)
    results["EQ4"] = paper_eq4_efficiency(ref, clean_profile)

    manifest = write_paper_evaluation_manifest(results)
    write_summary_v88(results)
    generate_paper_reporting_outputs(results)

    print("\n" + "=" * 78)
    print("FULL PAPER-ALIGNED EQ1-EQ4 EXPERIMENTS COMPLETE")
    print("=" * 78)
    print("Results:", RESULT_DIR)
    print("Plots:", PLOT_DIR)
    print("Manifest:", manifest)

if __name__ == "__main__":
    paper_aligned_main()